export const MAGIC_ITEMS = [
  {"id":"adamantruestung","name":"Adamantrüstung","type":"Rüstung (mittelschwer oder schwer","rarity":"ungewöhnlich","desc":["Diese Rüstung ist mit Adamant verstärkt, einem der härtesten Materialien, die es gibt. Wenn du sie trägst, wird jeder kritische Treffer gegen dich zu einem normalen Treffer."],"attune":"mittelschwer oder schwer, nicht Fell"},
  {"id":"amulett-der-ebenen","name":"Amulett der Ebenen","type":"Wundersamer Gegenstand","rarity":"sehr selten","desc":["Wenn du dieses Amulett trägst, kannst du als Aktion einen Ort auf einer anderen Existenzebene benennen, mit dem du vertraut bist. Führe dann einen SG-15-Intelligenzwurf aus. Bei einem Erfolg wirkst du den Zauber Ebenenwechsel. Anderenfalls reist du und jede Kreatur und jeder Gegenstand im Abstand von bis zu 4,5 Metern von dir an einen zufälligen Ort. Würfle mit einem W100. Bei einer 1-60 reist ihr an einen zufälligen Ort auf der von dir genannten Ebene. Bei einer 61-100 reist ihr auf eine zufällig bestimmte Existenzebene."],"attune":"erfordert Einstimmung"},
  {"id":"amulett-der-gesundheit","name":"Amulett der Gesundheit","type":"Wundersamer Gegenstand","rarity":"selten","desc":["Wenn du dieses Amulett trägst, ist dein Konstitutionswert 19. Es hat keinen Effekt, wenn er bereits 19 oder höher ist."],"attune":"erfordert Einstimmung"},
  {"id":"amulett-des-schutzes-gegen-ortung-und-ausspaehung","name":"Amulett des Schutzes gegen Ortung und Ausspähung","type":"Wundersamer Gegenstand","rarity":"ungewöhnlich","desc":["Wenn du dieses Amulett trägst, bist du vor Erkenntnismagie versteckt. Du kannst nicht das Ziel solcher Magie sein oder durch magische Ausspähungssensoren wahrgenommen werden."],"attune":"erfordert Einstimmung"},
  {"id":"anhaenger-der-gesundheit","name":"Anhänger der Gesundheit","type":"Wundersamer Gegenstand","rarity":"ungewöhnlich","desc":["Wenn du diesen Anhänger trägst, bist du gegen alle Krankheiten immun. Wenn du bereits eine Krankheit hast, werden die Effekte der Krankheit unterdrückt, solange du den Anhänger trägst."]},
  {"id":"anhaenger-der-wundheilung","name":"Anhänger der Wundheilung","type":"Wundersamer Gegenstand","rarity":"ungewöhnlich","desc":["Wenn du diesen Anhänger trägst und sterben würdest, stabilisierst du dich zum Beginn deines Zugs. Wenn du einen Trefferwürfel verwendest, um Trefferpunkte zurückzuerhalten, verdoppelst du außerdem jedes Mal die zurückerhaltenen Trefferpunkte."],"attune":"erfordert Einstimmung"},
  {"id":"anhaenger-des-giftschutzes","name":"Anhänger des Giftschutzes","type":"Wundersamer Gegenstand","rarity":"selten","desc":["An dieser feinen Silberkette hängt ein schwarzer Edelsteinanhänger im Brillantschliff. Wenn du ihn trägst, haben Gifte keinen Effekt auf dich. Du bist gegen den Zustand Vergiftet und gegen Giftschaden immun."]},
  {"id":"apparat-der-krabbe","name":"Apparat der Krabbe","type":"Wundersamer Gegenstand","rarity":"legendär","desc":["Dieser Gegenstand scheint zunächst ein großes, versiegeltes Eisenfass zu sein, das 250 Kilogramm wiegt. Das Fass hat einen versteckten Haken, der mit einem erfolgreichen SG-20-Intelligenzwurf (Nachforschungen) gefunden werden kann. Wird der Haken gelöst, öffnet sich eine Luke am Ende des Fasses, durch die zwei höchstens mittelgroße Kreaturen ins Innere kriechen können. Am anderen Ende des Fassinneren befindet sich eine Reihe mit zehn Hebeln in neutraler Stellung. Die Hebel können nach oben und nach unten bewegt werden. Wenn bestimmte Hebel bewegt werden, verwandelt sich der Apparat in einen Riesenhummer.","Der Apparat der Krabbe ist ein großer Gegenstand mit den folgenden Werten:","Rüstungsklasse: 20","Trefferpunkte: 200","Bewegungsrate: 9 m, Schwimmen 9 m (oder 0 m für beides, wenn Beine und Schwanz nicht ausgefahren sind)","Schadensimmunitäten: Gift, psychisch","Um als Fahrzeug verwendet zu werden, benötigt der Apparat einen Piloten. Wenn die Luke des Apparats geschlossen ist, ist er lüft- und wasserdicht.","Der Innenraum enthält genug Atemluft für zehn Stunden (geteilt durch die Anzahl atmender Kreaturen im Apparat).","Der Apparat schwimmt auf dem Wasser. Er kann auch bis auf 270 Meter Tiefe tauchen. Bei größeren Tiefen erleidet das Fahrzeug durch den Druck 2W6 Wuchtschaden pro Minute.","Eine Kreatur im Apparat kann als Aktion bis zu zwei Hebel nach oben oder unten bewegen. Nach jedem Gebrauch kehren die Hebel in ihre neutrale Position zurück. Jeder Hebel funktioniert, von links nach rechts gelesen, wie in der Tabelle 'Hebel des Apparats der Krabbe' angegeben."]},
  {"id":"armschienen-der-verteidigung","name":"Armschienen der Verteidigung","type":"Wundersamer Gegenstand","rarity":"selten","desc":["Wenn du diese Armschienen trägst, erhältst du einen Bonus von +2 auf deine RK, falls du keine Rüstung trägst und keinen Schild verwendest."],"attune":"erfordert Einstimmung"},
  {"id":"armschienen-des-bogenschuetzen","name":"Armschienen des Bogenschützen ","type":"Wundersamer Gegenstand","rarity":"ungewöhnlich","desc":["Wenn du diese Armschienen trägst, bist du im Umgang mit Langbögen und Kurzbögen geübt und erhältst einen Bonus von +2 auf Schadenswürfe nach Fernkampfangriffen mit solchen Waffen."],"attune":"erfordert Einstimmung"},
  {"id":"augen-der-bezauberung","name":"Augen der Bezauberung","type":"Wundersamer Gegenstand","rarity":"ungewöhnlich","desc":["Diese kristallenen Gläser können als Brille getragen werden. Sie haben drei Ladungen. Wenn du sie trägst, kannst du als Aktion eine Ladung verbrauchen und den Zauber Person bezaubern (Zauberrettungswurf-SG 13) auf eine humanoide Kreatur im Abstand von bis zu neun Metern von dir wirken, sofern du und das Ziel euch gegenseitig sehen könnt. Die Gläser erhalten täglich im Morgengrauen alle verbrauchten Ladungen zurück."],"attune":"erfordert Einstimmung"},
  {"id":"augen-des-adlers","name":"Augen des Adlers","type":"Wundersamer Gegenstand","rarity":"ungewöhnlich","desc":["Diese kristallenen Gläser können als Brille getragen werden. Wenn du sie trägst, bist du bei Weisheitswürfen (Wahrnehmung), die einen klaren Blick erfordern, im Vorteil. Bei klaren Sichtverhältnissen kannst du selbst bei extrem weit entfernten Kreaturen und Gegenständen Details erkennen, wenn diese mindestens 60 Zentimeter groß sind."],"attune":"erfordert Einstimmung"},
  {"id":"augen-des-praezisen-sehens","name":"Augen des präzisen Sehens","type":"Wundersamer Gegenstand","rarity":"ungewöhnlich","desc":["Diese kristallenen Gläser können als Brille getragen werden. Wenn du sie trägst, kannst du im Abstand von bis zu 30 Zentimetern viel besser sehen als sonst. Du bist bei Intelligenzwürfen (Nachforschungen), die einen scharfen Blick erfordern, im Vorteil, wenn du einen Bereich oder einen Gegenstand innerhalb dieser Reichweite untersuchst."]},
  {"id":"belebter-schild","name":"Belebter Schild","type":"Rüstung (Schild)","rarity":"sehr selten","desc":["Wenn du diesen Schild hältst, kannst du als Bonusaktion sein Befehlswort sprechen und ihn animieren. Der Schild springt in die Luft und schwebt in deinem Bereich. Er schützt dich, als würdest du ihn führen, wobei du die Hände frei hast. Der Schild bleibt eine Minute lang animiert, bis du eine Bonusaktion verwendest, um diesen Effekt zu beenden oder bis du kampfunfähig wirst oder stirbst Daraufhin fällt der Schild auf den Boden oder in deine Hand, falls du eine Hand frei hast."],"attune":"Schild"},
  {"id":"berserkeraxt","name":"Berserkeraxt","type":"Waffe (beliebige Axt)","rarity":"selten","desc":["Du erhältst einen Bonus von +1 auf Angriffs- und Schadenswürfe, die du mit dieser magischen Waffe ausführst. Wenn du auf diese Waffe eingestimmt bist, erhöht sich dein Trefferpunktemaximum außerdem für jede Stufe, die du erreicht hast, um 1.","Fluch: Diese Axt ist verflucht, und wenn du dich auf sie einstimmst, geht der Fluch auf dich über. Solange du verflucht bist, bist du nicht bereit, dich von der Axt zu trennen. Du behältst sie stets in Reichweite. Außerdem bist du bei Angriffswürfen mit anderen Waffen als dieser im Nachteil, es sei denn, es befinden sich im Abstand von bis zu 18 Metern von dir keine Gegner, die du sehen oder hören kannst.","Wenn eine feindlich gesinnte Kreatur dir Schaden zufügt, während du die Axt besitzt, musst du einen SG-15-Weisheitsrettungswurf bestehen, oder du wirst rasend. Während du rasend bist, musst du deine Aktion in jeder Runde verwenden, um die Kreatur, die dir am nächsten ist, mit der Axt anzugreifen. Falls zu deiner Angriffsaktion zusätzliche Angriffe gehören, verwendest du diese zusätzlichen Angriffe. Wenn du dein aktuelles Ziel niedergestreckt hast, gehst du zur zweitnächsten Kreatur über. Wenn du mehrere mögliche Ziele hast, greifst du zufällig eins davon an. Du bist rasend, bist du deinen Zug beginnst, ohne dass sich Kreaturen im Abstand von bis zu 18 Metern von dir befinden, die du sehen oder hören kannst."],"attune":"beliebige Axt"},
  {"id":"bohnenbeutel","name":"Bohnenbeutel","type":"Wundersamer Gegenstand","rarity":"selten","desc":["In diesem schweren Stoffbeutel befinden sich 3W4 getrocknete Bohnen. Der Beutel wiegt 250 Gramm plus 125 Gramm für jede darin enthaltene Bohne.","Wenn du den Inhalt des Beutels auf den Boden ausleerst, explodieren die Bohnen in einem Radius von drei Metern. Jede Kreatur im Wirkungsbereich -einschließlich dir - muss einen SG-15-Geschicklich-keitsrettungswurf ausführen. Scheitert der Wurf, erleidet sie 5W4 Feuerschaden, anderenfalls die Hälfte. Das Feuer entzündet brennbare Gegenstände in der Umgebung, die nicht getragen oder gehalten werden.","Wenn du eine Bohne aus dem Beutel nimmst, sie in Erde oder Sand einpflanzt und bewässerst, produziert die Bohne eine Minute nach dem Pflanzen einen Effekt an der Stelle, wo sie gepflanzt wurde. Der SL kann einen Effekt aus der folgenden Tabelle auswählen, zufällig bestimmen oder einen Effekt erschaffen."]},
  {"id":"boesartige-waffe","name":"Bösartige Waffe","type":"Waffe (beliebig)","rarity":"selten","desc":["Wenn du bei einem Angriffswurf mit dieser magischen Waffe eine 20 würfelst, verursacht dein kritischer Treffer zusätzlich 2W6 Schaden des Typs, den die Waffe verursacht."],"attune":"beliebig"},
  {"id":"brosche-des-abschirmens","name":"Brosche des Abschirmens","type":"Wundersamer Gegenstand","rarity":"ungewöhnlich","desc":["Wenn du diese Brosche trägst, bist du gegen Energieschaden resistent und gegen Schaden durch den Zauber Magisches Geschoss immun."],"attune":"erfordert Einstimmung"},
  {"id":"brunnen-der-vielen-welten","name":"Brunnen der vielen Welten","type":"Wundersamer Gegenstand","rarity":"legendär","desc":["Dieses feine, schwarze Tuch ist seidenweich und auf die Größe eines Taschentuchs zusammengefaltet. Ausgebreitet ist es ein kreisrundes Tuch mit einem Durchmesser von 1,8 Metern.","Du kannst den Brunnen der vielen Welten als Aktion ausbreiten und auf einer festen Oberfläche platzieren, woraufhin er ein in beide Richtungen funktionierendes Portal zu einer anderen Welt oder Existenzebene erzeugt. Jedes Mal, wenn mit dem Gegenstand ein Portal geöffnet wird, entscheidet der SL, wohin es führt. Du kannst ein offenes Portal als Aktion schließen, indem du den Rand des Tuchs greifst und es zusammenfaltest. Nachdem ein Brunnen der vielen Welten ein Portal geöffnet hat, kann er erst in 1W8 Stunden wieder auf diese Weise verwendet werden."]},
  {"id":"daemonenruestung","name":"Dämonenrüstung","type":"Rüstung (Ritterrüstung)","rarity":"sehr selten","desc":["Wenn du diese Rüstung trägst, erhältst du einen Bonus von +1 auf deine RK und kannst Abyssisch verstehen und sprechen. Außerdem wandeln die klauenbesetzten Panzerhandschuhe der Rüstung waffenlose Angriffe mit deinen Händen in magische Waffen um, die Hiebschaden verursachen. Dabei hast du einen Bonus von +1 auf Angriffs- und Schadenswürfe und einen 1W8 als Schadenswürfel.","Fluch: Nachdem du diese verfluchte Rüstung angelegt hast, kannst du sie nur wieder ablegen, wenn du das Ziel des Zaubers Fluch brechen oder ähnlicher Magie wirst. Wenn du die Rüstung trägst, bist du bei Angriffswürfen gegen Dämonen und bei Rettungswürfen gegen ihre Zauber und Spezialfähigkeiten im Nachteil."],"attune":"Ritterrüstung"},
  {"id":"diadem-des-versengens","name":"Diadem des Versengens","type":"Wundersamer Gegenstand","rarity":"ungewöhnlich","desc":["Wenn du dieses Diadem trägst, kannst du damit als Aktion den Zauber Sengender Strahl wirken. Wenn du die Angriffswürfe für den Zauber ausführst, ist dein Angriffsbonus +5. Das Diadem kann erst im nächsten Morgengrauen wieder auf diese Weise verwendet werden."]},
  {"id":"dieb-der-neun-leben","name":"Dieb der neun Leben","type":"Waffe (beliebiges Schwert)","rarity":"sehr selten","desc":["Du erhältst einen Bonus von +2 auf Angriffs- und Schadenswürfe, die du mit dieser magischen Waffe ausführst.","Das Schwert hat 1W8+1 Ladungen. Wenn du einen kritischen Treffer gegen eine Kreatur landest, die weniger als 100 Trefferpunkte hat, muss die Kreatur einen SG-15-Konstitutionsrettungswurf bestehen, oder sie stirbt auf der Stelle, da das Schwert ihr ihre Lebensenergie entzieht (Konstrukte und Untote sind immun). Das Schwert verliert eine Ladung, wenn die Kreatur getötet wird. Wenn das Schwert keine Ladungen mehr hat, verliert es diese Eigenschaft."],"attune":"beliebiges Schwert"},
  {"id":"dimensionsfesseln","name":"Dimensionsfesseln","type":"Wundersamer Gegenstand","rarity":"selten","desc":["Du kannst diese Fesseln als Aktion einer kampfunfähigen Kreatur anlegen. Die Fesseln passen sich an kleine bis große Kreaturen an. Zusätzlich zu ihrer Funktion als normale Handschellen verhindern diese Fesseln, dass eine mit ihnen gefesselte Kreatur irgendeine Form von extradimensionaler Bewegung nutzen kann. Dazu gehören Teleportation und Reisen in eine andere Existenzebene. Sie hindern die Kreatur nicht daran, ein interdimensionales Portal zu durchqueren.","Du und jede Kreatur, die du bestimmst, wenn du die Fesseln verwendest, könnt sie als Aktion abnehmen. Die gefesselte Kreatur kann alle 30 Tage einmal einen SG-30-Stärkewurf (Athletik) ausführen. Bei einem Erfolg befreit sich die Kreatur und zerstört die Fesseln."]},
  {"id":"dolch-des-gifts","name":"Dolch des Gifts","type":"Waffe (Dolch)","rarity":"selten","desc":["Du erhältst einen Bonus von +1 auf Angriffs- und Schadenswürfe, die du mit dieser magischen Waffe ausführst.","Du kannst als Aktion ein dickflüssiges, schwarzes Gift auf der Klinge erscheinen lassen. Das Gift bleibt eine Minute lang wirksam, oder bis ein Angriff mit dieser Waffe eine Kreatur trifft. Diese Kreatur muss einen SG-15-Konstitutionsrettungswurf bestehen, oder sie erleidet 2W10 Giftschaden und ist eine Minute lang vergiftet. Der Dolch kann erst im nächsten Morgengrauen wieder auf diese Weise verwendet werden."],"attune":"Dolch"},
  {"id":"drachenschuppenpanzer","name":"Drachenschuppenpanzer","type":"Rüstung (Schuppenpanzer)","rarity":"sehr selten","desc":["Ein Drachenschuppenpanzer besteht aus den Schuppen einer einzelnen Drachenart. In manchen Fällen sammeln Drachen ihre abgeworfenen Schuppen und schenken sie Humanoiden. In anderen Fällen häuten Jäger einen toten Drachen und machen seine Haut vorsichtig haltbar. Unabhängig von ihrer Herkunft sind Drachenschuppenpanzer extrem wertvoll.","Wenn du diese Rüstung trägst, erhältst du einen Bonus von +1 auf deine RK, du bist bei Rettungswürfen gegen die Furchterregende Präsenz und die Odemwaffen von Drachen im Vorteil und bist gegen eine Schadensart resistent. Welche Schadensart das ist, hängt von der Drachenart ab, von der die Schuppen stammen (siehe Tabelle).","Außerdem kannst du dich als Aktion konzentrieren und auf magische Weise die Entfernung und Richtung des nächsten Drachen im Abstand von bis zu 48 Kilometern von dir erspüren, der mit der Art deiner Rüstung übereinstimmt. Diese besondere Aktion kann erst im nächsten Morgengrauen wiederverwendet werden."],"attune":"Schuppenpanzer"},
  {"id":"drachentoeter","name":"Drachentöter","type":"Waffe (beliebiges Schwert)","rarity":"selten","desc":["Du erhältst einen Bonus von +1 auf Angriffs- und Schadenswürfe, die du mit dieser magischen Waffe ausführst.","Wenn du einen Drachen mit dieser Waffe triffst, erleidet der Drache zusätzlich 3W6 Schaden vom Typ der Waffe. Für diese Waffe zählen alle Kreaturen als Drache, die den Typ 'Drache' haben, auch Drachenschildkröten und Wyvern."],"attune":"beliebiges Schwert"},
  {"id":"dreizack-der-fischherrschaft","name":"Dreizack der Fischherrschaft","type":"Waffe (Dreizack)","rarity":"ungewöhnlich","desc":["Dieser Dreizack ist eine magische Waffe. Er hat drei Ladungen. Wenn du ihn trägst, kannst du als Aktion eine Ladung verbrauchen, um den Zauber Tier beherrschen (Rettungswurf-SG 15) damit auf ein Tier zu wirken, das eine angeborene Schwimmbewegungsrate hat. Der Dreizack erhält täglich im Morgengrauen 1W3 verbrauchte Ladungen zurück."],"attune":"Dreizack"},
  {"id":"edelstein-der-helligkeit","name":"Edelstein der Helligkeit","type":"Wundersamer Gegenstand","rarity":"ungewöhnlich","desc":["Dieses Prisma hat 50 Ladungen. Wenn du es hältst, kannst du als Aktion eins von drei Befehlswörtern aussprechen und den entsprechenden Effekt auslösen:","Wenn alle Ladungen des Edelsteins verbraucht wurden, wird der Edelstein zu einem nichtmagischen Edelstein, der 50 GM wert ist."]},
  {"id":"edelstein-des-sehens","name":"Edelstein des Sehens","type":"Wundersamer Gegenstand","rarity":"selten","desc":["Dieser Edelstein hat drei Ladungen. Du kannst als Aktion das Befehlswort des Edelsteins aussprechen und eine Ladung verbrauchen. Die nächsten zehn Minuten lang hast du Wahrer Blick mit einer Reichweite von 36 Metern, wenn du durch den Edelstein schaust.","Der Edelstein erhält täglich im Morgengrauen 1W3 verbrauchte Ladungen zurück."],"attune":"erfordert Einstimmung"},
  {"id":"effizienter-koecher","name":"Effizienter Köcher","type":"Wundersamer Gegenstand","rarity":"ungewöhnlich","desc":["Jedes der drei Fächer des Köchers ist mit einem extradimensionalen Raum verbunden. Dadurch kann der Köcher viele Gegenstände fassen, ohne jemals mehr als ein Kilogramm zu wiegen. Das kürzeste Fach fasst bis zu 60 Pfeile, Bolzen oder ähnliche Gegenstände. Ins mittlere Fach passen bis zu 18 Wurfspeere oder ähnliche Gegenstände. Das längste Fach bietet genug Platz für sechs lange Gegenstände wie Bögen, Kampfstäbe oder Speere.","Du kannst einen Gegenstand aus dem Köcher ziehen, als wäre es ein normaler Köcher oder eine normale Scheide."]},
  {"id":"eisenbaender-des-bindens","name":"Eisenbänder des Bindens","type":"Wundersamer Gegenstand","rarity":"selten","desc":["Diese rostige Eisenkugel misst 7,5 Zentimeter im Durchmesser und wiegt 0,5 Kilogramm. Du kannst als Aktion das Befehlswort aussprechen und die Kugel auf eine höchstens riesige Kreatur werfen, die du im Abstand von bis zu 18 Metern von dir sehen kannst. Während die Kugel in der Luft ist, öffnet sie sich zu einem Gewirr aus Metallbändern.","Führe einen Fernkampfangriff aus, bei dem der Angriffsbonus deinem Geschicklichkeitsmodifikator plus deinem Übungsbonus entspricht. Bei einem Treffer ist das Ziel festgesetzt, bis du das Befehlswort als Bonusaktion erneut aussprichst, um es freizulassen. Dies oder ein fehlgeschlagener Angriff führt dazu, dass die Bänder sich wieder zu einer Kugel zusammenziehen.","Eine Kreatur, auch die festgesetzte, kann als Aktion einen SG-20-Stärkewurf ausführen, um die Eisenbänder aufzusprengen. Bei einem Erfolg wird der Gegenstand zerstört und die festgesetzte Kreatur befreit Anderenfalls scheitern alle weiteren Versuche der Kreatur in den nächsten 24 Stunden automatisch.","Nachdem die Bänder verwendet wurden, können sie erst im nächsten Morgengrauen wiederverwendet werden."]},
  {"id":"eiserne-flasche","name":"Eiserne Flasche","type":"Wundersamer Gegenstand","rarity":"legendär","desc":["Diese Eisenflasche hat einen Messingstopfen.","Du kannst als Aktion das Befehlswort der Flasche aussprechen und eine Kreatur im Abstand von bis zu 18 Metern von dir, die du sehen kannst, als Ziel bestimmen. Wenn das Ziel von einer anderen Existenzebene stammt als der, in der du dich befindest, muss es einen SG-17-Weisheitsrettungswurf bestehen, oder es wird in der Flasche gefangen. Wenn das Ziel bereits in der Flasche gefangen wurde, ist es bei dem Rettungswurf im Vorteil. Nachdem sie in der Flasche gefangen wurde, bleibt die Kreatur darin, bis sie wieder freigelassen wird. Die Flasche kann jeweils nur eine Kreatur gleichzeitig aufnehmen. Eine in der Flasche gefangene Kreatur muss nicht atmen, essen oder trinken und altert nicht.","Du kannst als Aktion den Stopfen der Flasche entfernen und die Kreatur freilassen, die in der Flasche gefangen ist Die Kreatur ist dir und deinen Verbündeten gegenüber eine Stunde lang freundlich gesinnt und gehorcht während dieser Zeit deinen Befehlen. Wenn du ihr keine Befehle gibst oder ihr einen Befehl erteilst, der sie wahrscheinlich töten würde, verteidigt sie sich, führt aber anderenfalls keine Aktionen aus. Am Ende der Wirkungsdauer verhält sich die Kreatur so, wie es ihrer normalen Veranlagung und Gesinnung entspricht.","Der Zauber Identifizieren offenbart, dass eine Kreatur in der Flasche ist. Um welchen Kreaturentyp es sich handelt, ist nur durch Öffnen der Flasche zu erfahren. Eine gerade entdeckte Flasche kann bereits eine vom SL gewählte oder zufällig bestimmte Kreatur enthalten."]},
  {"id":"elementarer-edelstein","name":"Elementarer Edelstein","type":"Wundersamer Gegenstand","rarity":"ungewöhnlich","desc":["Dieser Edelstein enthält ein Partikel Elementarenergie. Wenn du deine Aktion verwendest, um den Edelstein zu zerschmettern, wird ein Elementar beschworen, als hättest du den Zauber Elementar beschwören gewirkt. Die Magie des Edelsteins geht dadurch verloren. Die Art des Edelsteins bestimmt, was für ein Elementar durch den Zauber beschworen wird."]},
  {"id":"elfenruestung","name":"Elfenrüstung","type":"Rüstung (Kettenhemd)","rarity":"selten","desc":["Wenn du diese Rüstung trägst, erhältst du einen Bonus von +1 auf deine RK. Du giltst als im Umgang mit dieser Rüstung geübt, auch wenn du keine Übung im Umgang mit mittelschwerer Rüstung hast."],"attune":"Kettenhemd"},
  {"id":"elfenumhang","name":"Elfenumhang","type":"Wundersamer Gegenstand","rarity":"ungewöhnlich","desc":["Wenn du diesen Umhang mit aufgesetzter Kapuze trägst, sind Weisheitswürfe (Wahrnehmung), die erfolgen, um dich zu entdecken, im Nachteil. Außerdem du bei Geschicklichkeitswürfen (Heimlichkeit), um dich zu verstecken, im Vorteil, da der Umhang sich zur Tarnung and die Farbe der Umgebung anpasst. Das Auf- oder Absetzen der Kapuze erfordert eine Aktion."],"attune":"erfordert Einstimmung"},
  {"id":"ewiger-leim","name":"Ewiger Leim","type":"Wundersamer Gegenstand","rarity":"legendär","desc":["Diese zähflüssige, weiße Masse kann zwei Gegenstände dauerhaft miteinander verkleben. Der Tiegel oder die Flasche zur Aufbewahrung des Leims muss im Inneren mit Öl der Glätte bestrichen sein. Wenn er gefunden wird, enthält der Behälter 1W6+1 mal 20 Milliliter Leim.","20 Milliliter Leim reichen aus, um ein Quadrat mit 0,3 Metern Kantenlänge zu bedecken. Der Leim braucht eine Minute, um auszuhärten. Nach dem Aushärten kann die Klebeverbindung nur mit Universellem Lösungsmittel, Öl der Körperlosigkeit oder mit dem Zauber Wunsch gelöst werden."]},
  {"id":"faltboot","name":"Faltboot","type":"Wundersamer Gegenstand","rarity":"selten","desc":["Dieser Gegenstand sieht zunächst aus wie eine 30 Zentimeter lange, 15 Zentimeter breite und 15 Zentimeter hohe Holzkiste. Sie wiegt zwei Kilogramm und schwimmt auf Wasser. Sie kann geöffnet werden, um Gegenstände darin zu verstauen. Dieser Gegenstand hat außerdem drei Befehlswörter. Du kannst als Aktion jeweils eins davon aussprechen.","Auf ein Befehlswort hin entfaltet sich die Kiste zu einem drei Meter langen, 1,2 Meter breiten und 0,6 Meter tiefen Boot Das Boot hat ein Paar Ruder, einen Anker, einen Mast und ein Lateinersegel. Bis zu vier mittelgroße Kreaturen haben bequem darin Platz.","Auf das zweite Befehlswort hin entfaltet sich die Kiste zu einem 7,2 Meter langen, 2,4 Meter breiten und 1,8 Meter hohen Schiff. Das Schiff hat ein Deck, Rudersitze, fünf Paar Ruder, ein Steuerruder, einen Anker, eine Kabine an Deck und einen Mast mit einem quadratischen Segel. Fünfzehn mittelgroße Kreaturen haben bequem Platz darin.","Wenn die Kiste zu einem Gefährt wird, wiegt sie so viel wie ein normales Gefährt dieser Größe, und alles, was in der Kiste verstaut wurde, bleibt im Boot.","Du kannst die Peitsche als Bonusaktion in deinem Zug bis zu sechs Meter fliegen lassen und einen weiteren Angriff gegen eine Kreatur im Abstand von bis zu drei Metern von ihr ausführen. Die Peitsche verschwindet nach einer Stunde, wenn du eine Aktion verwendest, um sie verschwinden zu lassen oder wenn du kampfunfähig bist oder stirbst.","Wenn das dritte Befehlswort ausgesprochen wird, faltet sich das Faltboot wieder zu einer Kiste, sofern keine Kreaturen an Bord sind. Alle Gegenstände in dem Gefährt, die nicht in die Kiste passen, bleiben außerhalb der Kiste zurück. Alle Gegenstände in dem Gefährt, die in die Kiste passen, bleiben in der Kiste."]},
  {"id":"federfigur","name":"Federfigur","type":"Wundersamer Gegenstand","rarity":"selten","desc":["Dieser winzige Gegenstand sieht aus wie eine Feder. Es gibt verschiedene Federfiguren, die jeweils einen eigenen einmaligen Effekt haben. Der SL wählt die Art der Figur aus oder bestimmt sie zufällig.","Anker: Du kannst als Aktion mit der Figur ein Boot oder ein Schiff berühren. Die nächsten 24 Stunden lang kann das Gefährt durch nichts und niemanden bewegt werden. Berührt die Figur das Gefährt erneut, endet der Effekt Wenn der Effekt endet, verschwindet die Figur.","Baum: Um diese Figur zu verwenden, musst du dich im Freien befinden. Du kannst als Aktion eine freie Stelle auf dem Boden mit ihr berühren. Die Figur verschwindet und an ihrer Stelle erscheint eine nichtmagische Eiche. Der Baum ist 18 Meter hoch. Sein Stamm hat einen Durchmesser von 1,5 Metern, und die Krone erreicht einen Durchmesser von sechs Metern.","Fächer: Wenn du in einem Boot oder auf einem Schiff bist, kannst du die Figur als Aktion bis zu drei Meter in die Luft werfen. Die Figur verschwindet und an ihrer Stelle erscheint ein riesiger, wedelnder Fächer. Der Fächer schwebt und erzeugt einen Wind, der die Bewegungsrate des Schiffs für acht Stunden um acht Kilometer pro Stunde erhöht Du kannst den Fächer als Aktion verschwinden lassen.","Peitsche: Du kannst die Figur als Aktion an eine Stelle im Abstand von bis zu drei Metern von dir werfen. Die Figur verschwindet und an ihrer Stelle erscheint eine schwebende Peitsche. Du kannst dann als Bonusaktion einen Nahkampf-Zauberangriff gegen eine Kreatur im Abstand von bis zu drei Metern von der Peitsche ausführen. Dein Angriffsbonus ist +9. Bei einem Treffer erleidet das Ziel 1W6+5 Energieschaden.","Schwanenboot: Du kannst als Aktion ein Gewässer von mindestens 18 Metern Durchmesser mit der Figur berühren. Die Figur verschwindet und an ihrer Stelle erscheint ein 15 Meter langes und sechs Meter breites, schwanförmiges Boot Das Boot bewegt sich von allein und hat eine Bewegungsrate von 9,6 Kilometern pro Stunde. Während du dich im Boot befindest, kannst du es als Aktion fahren oder um bis zu 90 Grad wenden zu lassen. Das Boot kann bis zu 32 höchstens mittelgroße Kreaturen tragen. Eine große Kreatur zählt als vier mittelgroße, eine riesige Kreatur zählt als neun Kreaturen. Das Boot existiert 24 Stunden lang und verschwindet dann. Du kannst das Boot als Aktion verschwinden lassen.","Vogel: Du kannst die Figur als Aktion 1,5 Meter in die Luft werfen. Die Figur verschwindet und an ihrer Stelle erscheint ein riesiger, bunter Vogel. Der Vogel hat die Werte eines Rochs, aber er befolgt einfache Befehle von dir und kann nicht angreifen. Er kann bis zu 250 Kilogramm tragen, ohne dass sich seine Bewegungsrate im Flug (25,6 Kilometer pro Stunde für maximal 230,4 Kilometer pro Tag, unterbrochen von einer einstündigen Rast alle drei Stunden) vermindert. Bei halbierter Bewegungsrate kann er bis zu 500 Kilogramm tragen. Der Vogel verschwindet, wenn er seine maximale Entfernung für einen Tag geflogen ist oder wenn seine Trefferpunkte auf 0 sinken. Du kannst den Vogel als Aktion verschwinden lassen."]},
  {"id":"fesselseil","name":"Fesselseil","type":"Wundersamer Gegenstand","rarity":"selten","desc":["Dieses Seil ist neun Meter lang und wiegt 1,5 Kilogramm. Wenn du ein Ende des Seils festhältst und als Aktion das Befehlswort aussprichst, schießt das andere Ende hervor, um eine Kreatur zu verstricken, die du im Abstand von bis zu sechs Metern von dir sehen kannst. Das Ziel muss einen SG-15-Geschicklichkeitsrettungswurf bestehen, oder es wird festgesetzt.","Du kannst die Kreatur wieder freilassen, indem du als Bonusaktion ein zweites Befehlswort aussprichst. Ein vom Seil festgesetztes Ziel kann eine Aktion verwenden, um einen SG-15-Stärke- oder Geschicklichkeitswurf auszuführen (das Ziel entscheidet). Bei einem Erfolg ist die Kreatur nicht mehr vom Seil festgesetzt.","Das Seil besitzt eine RKvon 20 und 20 Trefferpunkte. Es erhält alle fünf Minuten 1 Trefferpunkt zurück, solange es noch mindestens 1 Trefferpunkt hat. Wenn die Trefferpunkte des Seils auf 0 sinken, ist das Seil zerstört."]},
  {"id":"feuerschale-der-feuerelementar-herrschaft","name":"Feuerschale der Feuerelementar-Herrschaft","type":"Wundersamer Gegenstand","rarity":"selten","desc":["Wenn in dieser kupfernen Feuerschale ein Feuer brennt, kannst du als Aktion das Befehlswort für die Feuerschale aussprechen und einen Feuerelementar beschwören, als hättest du den Zauber Elementar beschwören gewirkt. Die Feuerschale kann erst im nächsten Morgengrauen wieder auf diese Weise verwendet werden.","Die Feuerschale wiegt 2,5 Kilogramm."]},
  {"id":"figur-der-wundersamen-kraft","name":"Figur der wundersamen Kraft","type":"Wundersamer Gegenstand","rarity":"Seltenheit variiert","desc":["Eine Figur der wundersamen Kraft ist eine Tierstatue, die klein genug ist, um in eine Tasche zu passen. Wenn du eine Aktion verwendest, um das Befehlswort auszusprechen und die Figur an eine Stelle im Abstand von bis zu 18 Metern von dir auf den Boden zu werfen, wird die Figur zu einer lebendigen Kreatur. Wenn die Stelle, an der die Kreatur erscheinen würde, von anderen Kreaturen oder Gegenständen besetzt ist oder wenn nicht genug Platz für die Kreatur ist, wird die Figur nicht zu einer Kreatur.","Die Kreatur ist dir und deinen Verbündeten gegenüber freundlich gesinnt. Sie versteht deine Sprachen und gehorcht deinen gesprochenen Befehlen. Erteilst du keine Befehle, verteidigt die Kreatur sich, führt aber keine anderen Aktionen aus.","Die Kreatur existiert für eine für jede Kreatur spezifische Wirkungsdauer. Am Ende der jeweiligen Dauer wird die Kreatur wieder zur Figur. Dies geschieht sofort, wenn ihre Trefferpunkte auf 0 sinken oder du eine Aktion verwendest, um das Befehlswort erneut zu sprechen, während du sie berührst Ist die Kreatur wieder eine Figur, kann diese Eigenschaft von ihr erst nach der Dauer, die in ihrer Beschreibung genannt ist, wiederverwendet werden.","Bronze-Greif (selten): Dies ist die Bronzestatue eines wilden Greifs. Sie kann bis zu sechs Stunden lang zu einem Greif werden. Nachdem sie verwendet wurde, kann sie erst nach fünf Tagen wiederverwendet werden.","Ebenholz-Fliege (selten): Diese kleine Statue aus Ebenholz hat die Form einer Pferdebremse. Sie kann bis zu zwölf Stunden lang zu einer Riesenfliege werden und als Reittier verwendet werden. Nachdem sie verwendet wurde, kann sie erst nach zwei Tagen wiederverwendet werden.","Elfenbein-Ziegen (selten): Diese kleinen Ziegenstatuen aus Elfenbein werden immer zu drift erschaffen. Jede Ziege sieht einzigartig aus und hat eine spezielle Eigenschaft. Die Eigenschaften sind:","Goldene Löwen (selten): Diese kleinen Goldstatuen zweier Löwen werden immer als Paar erschaffen. Du kannst die Figuren einzeln oder beide gleichzeitig verwenden. Jede kann bis zu einer Stunde lang zu einem Löwen werden. Nachdem ein Löwe verwendet wurde, kann er erst nach sieben Tagen wiederverwendet werden.","Marmor-Elefant (selten): Diese Marmorstatuette ist etwa zehn Zentimeter hoch und lang. Sie kann bis zu 24 Stunden lang zu einem Elefanten werden. Nachdem sie verwendet wurde, kann sie erst nach sieben Tagen wiederverwendet werden.","Obsidianpferd (sehr selten): Dieses polierte Obsidianpferd kann bis zu 24 Stunden lang zu einem Nachtmahr werden. Der Nachtmahr kämpft nur, um sich selbst zu verteidigen. Nachdem sie verwendet wurde, kann sie erst nach fünf Tagen wiederverwendet werden.","Wenn deine Gesinnung gut ist, besteht bei jeder Verwendung der Figur eine zehnprozentige Wahrscheinlichkeit, dass sie deine Befehle ignoriert -einschließlich des Befehls, sich wieder in eine Figur zu verwandeln. Wenn du auf den Nachtmahr aufsitzt, während er deine Befehle ignoriert, werdet du und der Nachtmahr sofort an einen zufälligen Ort auf der Ebene Hades transportiert, wo der Nachtmahr sich wieder in eine Figur verwandelt.","Onyx-Hund (selten): Diese Onyxstatue eines Hundes kann bis zu sechs Stunden lang zu einer Dogge werden. Die Dogge hat einen Intelligenzwert von 8 und kann die Gemeinsprache sprechen. Sie hat außerdem Dunkelsicht mit einer Reichweite von bis zu 18 Metern und kann unsichtbare Kreaturen und Objekte innerhalb dieser Reichweite sehen. Nachdem sie verwendet wurde, kann sie erst nach sieben Tagen wiederverwendet werden.","Serpentin-Eule (selten): Diese Serpentinstatue einer Eule kann bis zu acht Stunden lang zu einer Rieseneule werden. Nachdem sie verwendet wurde, kann sie erst nach zwei Tagen wiederverwendet werden. Solange du dich auf derselben Existenzebene wie sie befindest, kann die Eule auf unbegrenzte Reichweite telepathisch mit dir kommunizieren.","Silber-Rabe (ungewöhnlich): Diese Silberstatue eines Raben kann bis zu zwölf Stunden lang zu einem Raben werden. Nachdem sie verwendet wurde, kann sie erst nach zwei Tagen wiederverwendet werden. Während sie in Rabengestalt ist, erlaubt dir die Figur, den Zauber Tierbote beliebig oft auf sie zu wirken."]},
  {"id":"flammenzunge","name":"Flammenzunge","type":"Waffe (beliebiges Schwert)","rarity":"selten","desc":["Du kannst als Bonusaktion das Befehlswort dieses magischen Schwerts aussprechen. Daraufhin brechen Flammen aus der Klinge hervor. Die Flammen spenden im Radius von zwölf Metern helles Licht und im Radius von weiteren zwölf Metern dämmriges Licht. Solange das Schwert brennt, verursacht es bei allen Zielen, die es trifft, zusätzlich 2W6 Feuerschaden. Die Flammen halten an, bis du eine Bonusaktion verwendest, um das Befehlswort nochmals auszusprechen oder bis du das Schwert fallen lässt oder wegsteckst."],"attune":"beliebiges Schwert"},
  {"id":"fliegender-teppich","name":"Fliegender Teppich","type":"Wundersamer Gegenstand","rarity":"sehr selten","desc":["Du kannst als Aktion das Befehlswort des Teppichs aussprechen, um den Teppich zum Schweben und Fliegen zu bringen. Er folgt deinen gesprochenen Anweisungen, solange du dich im Abstand von bis zu neun Metern befindest.","Es gibt vier verschiedene Größen des Fliegenden Teppichs. Der SL wählt die Größe des jeweiligen Teppichs aus oder bestimmt sie zufällig.","Ein Teppich kann das Doppelte der in der Tabelle angegebenen Traglast tragen, fliegt jedoch bei mehr als der angegebenen Traglast mit der halben Bewegungsrate."]},
  {"id":"floete-des-rattenfaengers","name":"Flöte des Rattenfängers","type":"Wundersamer Gegenstand","rarity":"ungewöhnlich","desc":["Du musst im Umgang mit Blasinstrumenten geübt sein, um diese Flöte zu verwenden. Solange du auf die Flöte eingestimmt bist, verhalten sich normale Ratten und Riesenratten dir gegenüber gleichgültig und greifen dich nicht an - es sei denn, du bedrohst sie oder fügst ihnen Schaden zu.","Die Flöte hat drei Ladungen. Wenn du die Flöte als Aktion spielst, kannst du eine Bonusaktion verwenden, um eine bis drei Ladungen zu verbrauchen. Mit jeder verbrauchten Ladung rufst du einen Rattenschwarm herbei, sofern sich im Abstand von bis zu 800 Metern genug Ratten befinden, die du herbeirufen kannst (dies wird vom SL festgelegt). Wenn nicht genug Ratten für einen Schwarm vorhanden sind, ist die Ladung verloren. Herbeigerufene Schwärme bewegen sich so direkt wie möglich auf die Musik zu, sind jedoch ansonsten nicht unter deiner Kontrolle. Die Flöte erhält täglich im Morgengrauen 1W3 verbrauchte Ladungen zurück.","Wenn ein Rattenschwarm, der nicht von einer anderen Kreatur kontrolliert wird, sich dir im Abstand von bis zu neun Metern oder weniger nähert, während du die Flöte spielst, kannst du einen vergleichenden Charismawurf gegen den Weisheitswurf des Schwarms ausführen. Wenn du den Vergleich verlierst, verhält sich der Schwarm normal und kann für die nächsten 24 Stunden nicht von der Musik der Flöte beeinflusst werden. Gewinnst du den Vergleich, wird der Schwarm von der Musik der Flöte beeinflusst. Er verhält sich dir und deinen Verbündeten gegenüber freundlich, solange du die Flöte in jeder Runde als Aktion spielst Ein freundlicher Schwarm gehorcht deinen Befehlen. Wenn du einem freundlichen Schwarm keine Befehle erteilst, verteidigt er sich, führt aber keine anderen Aktionen aus. Wenn ein freundlicher Schwarm zu Beginn seines Zugs die Flötenmusik nicht hören kann, endet deine Kontrolle über den Schwarm. Er verhält sich dann normal und kann für die nächsten 24 Stunden nicht von der Musik der Flöte beeinflusst werden."],"attune":"erfordert Einstimmung"},
  {"id":"floete-des-unheimlichen","name":"Flöte des Unheimlichen","type":"Wundersamer Gegenstand","rarity":"ungewöhnlich","desc":["Du musst im Umgang mit Blasinstrumenten geübt sein, um diese Flöte zu verwenden. Sie hat drei Ladungen. Du kannst sie als Aktion spielen und eine Ladung verbrauchen, um eine unheimliche, bezaubernde Melodie zu spielen. Jede Kreatur im Abstand von bis zu neun Metern von dir, die dich spielen hört, muss einen SG-15-Weisheitsrettungswurf bestehen, oder sie ist eine Minute lang von dir verängstigt. Wenn du dies möchtest, bestehen alle Kreaturen in dem Bereich, die dir gegenüber nicht feindlich sind, automatisch den Rettungswurf. Wenn der Rettungswurf einer Kreatur scheitert, kann sie den Rettungswurf am Ende jedes ihrer Züge wiederholen und den Effekt bei einem Erfolg beenden. Wenn der eine Kreatur ihren Rettungswurf besteht, ist sie 24 Stunden lang gegen den Effekt der Flöte immun. Die Flöte erhält täglich im Morgengrauen 1W3 verbrauchte Ladungen zurück"]},
  {"id":"flotte-festung","name":"Flotte Festung","type":"Wundersamer Gegenstand","rarity":"selten","desc":["Du kannst diesen Würfel mit einer Kantenlänge von 2,5 Zentimetern als Aktion auf den Boden legen und sein Befehlswort aussprechen. Der Würfel wächst rasant zu einer Festung heran, die bestehen bleibt, bis du eine Aktion verwendest, um das Befehlswort auszusprechen, das sie verschwinden lässt. Dies funktioniert nur, wenn die Festung leer ist.","Die Festung ist ein Turm mit einer quadratischen Grundfläche von sechs Metern Breite. Sie ist neun Meter hoch, hat Schießscharten in alle Richtungen und einen Zinnenwall auf dem Dach. Im Inneren ist sie in zwei Ebenen geteilt, die über eine Leiter an einer Wand miteinander verbunden sind. Die Leiter endet an einer Falltür zum Dach. Wenn sie aktiviert wird, hat die Festung eine kleine Tür auf der dir zugewandten Seite. Die Tür öffnet sich nur auf deinen Befehl hin. Du musst eine Bonusaktion verwenden, um den Befehl auszusprechen. Die Tür ist gegen den Zauber Klopfen und ähnliche Magie (beispielsweise die der Glocke des Öffnens) immun.","Jede Kreatur, die sich in dem Bereich befindet, in dem die Festung erscheint, muss einen SG-15-Geschicklichkeitsrettungswurf ausführen. Scheitert der Wurf, erleidet sie 10W10 Wuchtschaden, anderenfalls die Hälfte. In beiden Fällen wird die Kreatur an eine freie Stelle außerhalb, aber direkt neben der Festung verschoben. Gegenstände in dem Bereich, die nicht getragen oder gehalten werden, erleiden diesen Schaden automatisch und werden automatisch verschoben.","Der Turm besteht aus Adamant, und seine Magie verhindert, dass er umgestoßen wird. Dach, Tür und Wände haben jeweils 100 Trefferpunkte, sind gegen Schaden von nichtmagischen Waffen außer Belagerungswaffen immun und gegen allen anderen Schaden resistent. Nur der Zauber Wunsch kann die Festung reparieren (diese Verwendung des Zaubers gilt als Replikat eines Zaubers des maximal 8. Grades). Jedes Wirken von Wunsch lässt das Dach, die Tür oder eine Wand 50 Trefferpunkte zurückerhalten."]},
  {"id":"flugbesen","name":"Flugbesen","type":"Wundersamer Gegenstand","rarity":"ungewöhnlich","desc":["Dieser hölzerne Besen wiegt 1,5 Kilogramm und ist als normaler Besen verwendbar, bis du dich über den Besenstiel stellst und sein Befehlswort aussprichst. Dann schwebt er unter dir und du kannst mit ihm durch die Luft fliegen. Die Flugbewegungsrate des Besens beträgt 15 Meter. Er kann bis zu 200 Kilogramm tragen. Allerdings sinkt seine Flugbewegungsrate auf neun Meter, wenn er mehr als 100 Kilogramm trägt. Der Besen hört auf zu schweben, wenn du landest.","Du kannst den Besen ohne Passagier zu einem Ziel im Abstand von bis zu 1,6 Kilometern von dir schicken, wenn du sein Befehlswort aussprichst, den Ort nennst und du mit dem Ort vertraut bist. Der Besen kehrt zu dir zurück, wenn du ein anderes Befehlswort aussprichst, sofern er immer noch maximal 1,6 Kilometer von dir entfernt ist."]},
  {"id":"frassbeutel","name":"Fraßbeutel","type":"Wundersamer Gegenstand","rarity":"sehr selten","desc":["Dieser Beutel sieht auf den ersten Blick wie ein Nimmervoller Beutel aus. Stattdessen ist er aber das Maul einer gigantischen extradimensionalen Kreatur. Das Umstülpen des Beutels schließt das Maul.","Die zum Beutel gehörige extradimensionale Kreatur kann wittern, was in den Beutel gelegt wird. Tierisches oder pflanzliches Material, das vollständig in den Beutel gelegt wird, wird verschlungen und ist für immer verloren. Wenn eine lebendige Kreatur teilweise in den Beutel gelangt, etwa, weil jemand in den Beutel greift, wird sie mit 50-prozentiger Wahrscheinlichkeit in den Beutel gezogen. Eine Kreatur im Inneren des Beutels kann als Aktion versuchen, mit einem erfolgreichen SG-15-Stärkewurf zu entkommen. Eine andere Kreatur kann als Aktion in den Beutel greifen und versuchen, eine Kreatur im Inneren herauszuziehen. Dies gelingt mit einem erfolgreichen SG-20-Stärkewurf (und nur, sofern die Kreatur, die in den Beutel greift, nicht vorher in den Beutel gezogen wird). Jede Kreatur, die ihren Zug im Inneren des Beutels beginnt, wird verschlungen und ihr Körper zerstört.","Im Beutel können bis zu 28 Liter unbelebte Gegenstände aufbewahrt werden. Allerdings verschluckt der Beutel einmal am Tag alle Gegenstände in seinem Inneren und spuckt sie in einer anderen Existenzebene wieder aus. Der SL bestimmt den Zeitpunkt und die Ebene.","Wenn er durchbohrt oder zerrissen wird, zerstört dies den Beutel, und alles, was sich darin befindet, wird an einen zufälligen Ort auf der Astralebene transportiert."]},
  {"id":"frostbrand","name":"Frostbrand","type":"Waffe (beliebiges Schwert)","rarity":"sehr selten","desc":["Wenn du bei einem Angriff mit diesem magischen Schwert triffst, erleidet das Ziel zusätzlich 1W6 Kälteschaden. Solange du das Schwert hältst, bist du außerdem gegen Feuerschaden resistent.","Bei eisigen Temperaturen spendet die Klinge im Radius von drei Metern helles Licht und im Radius von weiteren drei Metern dämmriges Licht.","Wenn du diese Waffe ziehst, kannst du alle nichtmagischen Flammen im Abstand von bis zu neun Metern von dir löschen. Diese Eigenschaft kann höchstens einmal pro Stunde verwendet werden."],"attune":"beliebiges Schwert"},
  {"id":"gefluegelte-stiefel","name":"Geflügelte Stiefel","type":"Wundersamer Gegenstand","rarity":"ungewöhnlich","desc":["Wenn du diese Stiefel trägst, hast du eine Flugbewegungsrate, die deiner Schrittbewegungsrate entspricht. Du kannst die Stiefel verwenden, um bis zu vier Stunden lang zu fliegen. Die Wirkungsdauer kann auf einmal oder in kürzeren Flügen von jeweils mindestens einer Minute verbraucht werden. Wenn du fliegst, wenn die Wirkungsdauer abläuft, sinkst du um neun Meter pro Runde, bis du landest.","Die Stiefel erhalten alle zwölf Stunden, in denen sie nicht verwendet werden, zwei Stunden Flugzeit zurück."],"attune":"erfordert Einstimmung"},
  {"id":"geschosse-1-2-oder-3","name":"Geschosse, +1, +2 oder +3","type":"Waffe (beliebige Geschosse)","rarity":"ungewöhnlich (+1 ), selten (+2) oder sehr selten (+3)","desc":["Du erhältst einen Bonus auf alle Angriffs- und Schadenswürfe, die du mit diesen magischen Geschossen ausführst. Der Bonus wird von der Seltenheit der Geschosse bestimmt. Sobald sie ein Ziel treffen, sind die Geschosse nicht mehr magisch."],"attune":"beliebige Geschosse"},
  {"id":"glocke-des-oeffnens","name":"Glocke des Öffnens","type":"Wundersamer Gegenstand","rarity":"selten","desc":["Dieses hohle Metallrohr ist etwa 30 Zentimeter lang und wiegt 0,5 Kilogramm. Du kannst es als Aktion auf einen Gegenstand im Abstand von bis zu 36 Metern von dir richten, der geöffnet werden kann (zum Beispiel eine Tür, einen Deckel oder ein Schloss), und die Glocke schlagen. Die Glocke erzeugt einen hellen Klang, und das Schloss oder der Riegel des Gegenstands öffnet sich, es sei denn, der Klang kann den Gegenstand nicht erreichen. Wenn keine Schlösser oder Riegel mehr verschlossen sind, öffnet sich der Gegenstand selbst.","Die Glocke kann zehnmal verwendet werden. Nach dem zehnten Mal springt sie und wird unbrauchbar."]},
  {"id":"gluecksklinge","name":"Glücksklinge","type":"Waffe (beliebiges Schwert)","rarity":"legendär","desc":["Du erhältst einen Bonus von +1 auf Angriffs- und Schadenswürfe, die du mit dieser magischen Waffe ausführst. Solange du das Schwert bei dir trägst, erhältst du einen Bonus von +1 auf Rettungswürfe.","Glück: Wenn du das Schwert bei dir trägst, kannst du sein innewohnendes Glück nutzen (keine Aktion notwendig), um einen unliebsamen Angriffswurf, Attributswurf oder Rettungswurf zu wiederholen. Du musst den zweiten Wurf verwenden. Diese Eigenschaft kann erst im nächsten Morgengrauen wiederverwendet werden.","Wunsch: Das Schwert hat 1W4-1 Ladungen.","Wenn du es hältst, kannst du als Aktion eine Ladung verbrauchen und den Zauber Wunsch mit ihm wirken. Diese Eigenschaft kann erst im nächsten Morgengrauen wiederverwendet werden. Das Schwert verliert diese Eigenschaft, wenn es keine Ladungen mehr hat."],"attune":"beliebiges Schwert"},
  {"id":"guertel-der-riesenstaerke","name":"Gürtel der Riesenstärke","type":"Wundersamer Gegenstand","rarity":"Seltenheit variiert","desc":["Wenn du diesen Gürtel trägst, ändert sich dein Stärkewert auf einen vom Gürtel bestimmten Wert. Falls deine Stärke bereits dem Wert des Gürtels entspricht oder höher ist, hat der Gegenstand keine Wirkung auf dich.","Dieser Gürtel existiert in sechs Varianten, die den sechs Arten wahrer Riesen entsprechen. Die Seltenheit richtet sich nach der Seltenheit der jeweiligen Riesen. Der Gürtel der Steinriesenstärke und der Gürtel der Frostriesenstärke sehen unterschiedlich aus, haben aber dieselbe Wirkung."],"attune":"erfordert Einstimmung"},
  {"id":"halskette-der-anpassung","name":"Halskette der Anpassung","type":"Wundersamer Gegenstand","rarity":"ungewöhnlich","desc":["Wenn du diese Halskette trägst, kannst du in jeder Umgebung normal atmen und du bist bei Rettungswürfen gegen schädliche Gase und Dämpfe (wie Stinkende Wolke und Todeswolke, inhalierte Gifte und die Odemwaffen mancher Drachen) im Vorteil."],"attune":"erfordert Einstimmung"},
  {"id":"halskette-der-feuerbaelle","name":"Halskette der Feuerbälle","type":"Wundersamer Gegenstand","rarity":"selten","desc":["An dieser Kette hängen 1W6+3 Perlen. Du kannst eine Aktion verwenden, um eine Perle abzunehmen und bis zu 18 Meter weit zu werfen. Am Ende ihrer Flugbahn explodiert die Perle wie ein Feuerball-Zauber des 3. Grades (Rettungswurf-SG 15).","Du kannst als eine Aktion mehrere Perlen oder sogar die ganze Kette werfen. In diesem Fall steigt der Grad des Feuerballs für jede Perle über den 1. Grad hinaus um 1."]},
  {"id":"halskette-der-gebetsperlen","name":"Halskette der Gebetsperlen","type":"Wundersamer Gegenstand","rarity":"selten","desc":["Diese Halskette hat 1W4+2 magische Perlen aus Aquamarin, schwarzen Perlen oder Topas. Außerdem befinden sich auch nichtmagische Perlen aus Bernstein, Blutstein, Citrin, Jade, Koralle, Perle oder Quarz an der Kette. Wenn eine magische Perle von der Halskette entfernt wird, verliert die Perle ihre Magie.","Es gibt sechs verschiedene magische Perlentypen. Der SL wählt die Perlentypen an der Halskette aus oder bestimmt sie zufällig. Eine Halskette kann mehr als eine Perle desselben Typs haben. Um eine der Perlen zu verwenden, musst du die Halskette tragen. Jede Perle enthält einen Zauber, den du als Bonusaktion mit ihr wirken kannst (etwa mit deinem Zauberret-tungswurf-SG, wenn ein Rettungswurf nötig ist). Nachdem der Zauber einer magischen Perle gewirkt wurde, kann diese Perle erst im nächsten Morgengrauen wiederverwendet werden."],"attune":"erfordert Einstimmung durch einen Druiden, Kleriker oder Paladin"},
  {"id":"hammer-des-blitzschlags","name":"Hammer des Blitzschlags","type":"Waffe (Zweihandhammer)","rarity":"legendär","desc":["Du erhältst einen Bonus von +1 auf Angriffs- und Schadenswürfe, die du mit dieser magischen Waffe ausführst.","Verderben der Riesen (erfordert Einstimmung): Du musst einen Gürtel der Riesenstärke (beliebige Art) und Panzerhandschuhe der Ogerkraft tragen, um dich auf diese Waffe einzustimmen. Die Einstimmung endet, wenn du einen dieser Gegenstände ablegst. Während du auf diese Waffe eingestimmt bist und sie hältst, erhöht sich dein Stärkewert um 4 und kann größer als 20, aber nicht größer als 30 sein. Wenn du bei einem Angriffswurf mit dieser Waffe gegen einen Riesen eine 20 würfelst, muss der Riese einen SG-17-Konstitutionsrettungswurf bestehen, oder er stirbt.","Außerdem hat der Hammer fünf Ladungen. Während du auf ihn eingestimmt bist, kannst du eine Ladung verbrauchen, um einen Fernkampfwaffenangriff mit dem Hammer auszuführen. Du wirfst ihn, als wäre er eine Wurfwaffe mit einer Grundreichweite von sechs Metern und einer Maximalreichweite von 18 Metern. Wenn der Angriff trifft, setzt der Hammer einen Donnerschlag frei, der im Umkreis von 90 Metern zu hören ist. Das Ziel und alle Kreaturen im Abstand von bis zu neun Metern von ihm müssen einen SG-17-Konstitutionsrettungswurf bestehen, oder sie sind bis zum Ende deines nächsten Zugs betäubt. Der Hammer erhält täglich im Morgengrauen 1W4+1 verbrauchte Ladungen zurück"],"attune":"Zweihandhammer"},
  {"id":"handbuch-der-golems","name":"Handbuch der Golems","type":"Wundersamer Gegenstand","rarity":"sehr selten","desc":["Dieser Foliant enthält die notwendigen Informationen und Beschwörungsformeln, um einen Golem eines bestimmten Typs zu erschaffen. Der SL wählt die Schadensart aus oder bestimmt sie zufällig. Um das Handbuch entziffern und verwenden zu könnten, musst du ein Zauberwirker mit mindestens zwei Zauberplätzen des 5. Grades sein. Eine Kreatur, die das Handbuch der Golems nicht verwenden kann und es versucht, erleidet 6W6 psychischen Schaden.","Um einen Golem zu erschaffen, musst du die in der Tabelle angegebene Zeit verbrauchen. Dabei arbeitest du ohne Unterbrechung genau nach der Anleitung im Handbuch und ruhst dich maximal acht Stunden pro Tag aus. Du musst außerdem die angegebenen Kosten für die Materialien ausgeben.","Sobald der Golem fertiggestellt ist, wird das Buch von mystischen Flammen verschlungen. Der Golem erwacht zum Leben, wenn die Asche des Handbuchs auf ihn gestreut wird. Er steht unter deiner Kontrolle, versteht deine gesprochenen Befehle und gehorcht diesen."]},
  {"id":"handbuch-der-koerperlichen-ertuechtigung","name":"Handbuch der körperlichen Ertüchtigung","type":"Wundersamer Gegenstand","rarity":"sehr selten","desc":["Dieses magisch geladene Buch beschreibt Fitnessübungen. Wenn du über einen Zeitraum von maximal sechs Tagen 48 Stunden damit verbringst, den Inhalt des Buchs zu studieren und seine Anleitungen zu befolgen, erhöhen sich dein Stärkewert und dein Maximalwert für Stärke um 2. Das Handbuch verliert dann seine Magie, erhält sie jedoch nach einem Jahrhundert zurück."]},
  {"id":"handbuch-der-koerperlichen-gesundheit","name":"Handbuch der körperlichen Gesundheit","type":"Wundersamer Gegenstand","rarity":"sehr selten","desc":["Dieses magisch geladene Buch enthält Gesundheits- und Ernährungstipps. Wenn du über einen Zeitraum von maximal sechs Tagen 48 Stunden damit verbringst, den Inhalt des Buchs zu studieren und seine Anleitungen zu befolgen, erhöhen sich dein Konstitutionswert und dein Maximalwert für Konstitution um 2. Das Handbuch verliert dann seine Magie, erhält sie jedoch nach einem Jahrhundert zurück"]},
  {"id":"handbuch-des-schnellen-handelns","name":"Handbuch des schnellen Handelns","type":"Wundersamer Gegenstand","rarity":"sehr selten","desc":["Dieses magisch geladene Buch enthält Koordinations- und Balanceübungen. Wenn du über einen Zeitraum von maximal sechs Tagen 48 Stunden damit verbringst, den Inhalt des Buchs zu studieren und seine Anleitungen zu befolgen, erhöhen sich dein Geschicklichkeitswert und dein Maximalwert für Geschicklichkeit um 2.","Das Handbuch verliert dann seine Magie, erhält sie jedoch nach einem Jahrhundert zurück."]},
  {"id":"handschuhe-des-geschossfangens","name":"Handschuhe des Geschossfangens ","type":"Wundersamer Gegenstand","rarity":"ungewöhnlich","desc":["Diese Handschuhe scheinen fast mit deinen Händen zu verschmelzen, wenn du sie anziehst. Wenn dich ein Fernkampfwaffenangriff trifft, wenn du sie trägst, kannst du deine Reaktion verwenden, um den Schaden um 1W10 + dein Geschicklichkeitsmodifikator zu reduzieren, sofern du eine Hand frei hast Wenn du den Schaden auf 0 verringerst, fängst du das Geschoss, solange es klein genug ist, dass du es in einer Hand halten kannst."],"attune":"erfordert Einstimmung"},
  {"id":"handschuhe-des-schwimmens-und-kletterns","name":"Handschuhe des Schwimmens und Kletterns ","type":"Wundersamer Gegenstand","rarity":"ungewöhnlich","desc":["Wenn du diese Handschuhe trägst, kosten dich Klettern und Schwimmen keine zusätzliche Bewegung, und du erhältst einen Bonus von +5 auf Stärkewürfe (Athletik), um zu klettern oder zu schwimmen."],"attune":"erfordert Einstimmung"},
  {"id":"heiliger-raecher","name":"Heiliger Rächer","type":"Waffe (beliebiges Schwert)","rarity":"legendär","desc":["Du erhältst einen Bonus von +3 auf Angriffs- und Schadenswürfe, die du mit dieser magischen Waffe ausführst. Wenn du einen Unhold oder Untoten damit triffst, erleidet diese Kreatur zusätzlich 2W10 gleißenden Schaden.","Wenn du das gezückte Schwert hältst, erzeugt es im Radius von drei Metern um dich herum eine Aura. Du und alle verbündeten Kreaturen in der Aura seit bei Rettungswürfen gegen Zauber und andere magische Effekte im Vorteil. Wenn du 17 oder mehr Stufen als Paladin hast, erhöht sich der Radius der Aura auf neun Meter."],"attune":"beliebiges Schwert"},
  {"id":"heiltrank","name":"Heiltrank","type":"Trank","rarity":"Seltenheit variiert","desc":["Wenn du diesen Trank trinkst, erhältst du Trefferpunkte zurück. Die Anzahl der wiederhergestellten Trefferpunkte hängt von der Seltenheit des Tranks entsprechend der Tabelle 'Heiltränke' ab. Unabhängig von ihrer Stärke bestehen Heiltränke aus roter Flüssigkeit, die schimmert, wenn sie bewegt wird."]},
  {"id":"helm-der-pracht","name":"Helm der Pracht","type":"Wundersamer Gegenstand","rarity":"sehr selten","desc":["Dieser umwerfende Helm ist mit 1W10 Diamanten, 2W10 Rubinen, 3W10 Feueropalen und 4W10 Opalen besetzt. Wenn ein Edelstein vom Helm gebrochen wird, zerfällt der Edelstein zu Staub. Wenn alle Edelsteine entfernt oder zerstört wurden, verliert der Helm seine Magie.","Wenn du ihn trägst, erhältst du die folgenden Vorteile:","Würfle mit einem W20, wenn du den Helm trägst und Feuerschaden erleidest, weil dir ein Rettungswurf gegen einen Zauber misslungen ist. Wenn du eine 1 würfelst, verströmt der Helm Lichtstrahlen von seinen übrigen Edelsteinen. Jede Kreatur im Abstand von bis zu 18 Metern vom Helm außer dir muss einen SG-17-Geschick-lichkeitsrettungswurf bestehen, oder sie wird von einem Strahl getroffen und erleidet so viel gleißenden Schaden, wie Edelsteine auf dem Helm übrig sind. Der Helm und seine Edelsteine werden dann zerstört."],"attune":"erfordert Einstimmung"},
  {"id":"helm-der-telepathie","name":"Helm der Telepathie","type":"Wundersamer Gegenstand","rarity":"ungewöhnlich","desc":["Wenn du diesen Helm trägst, kannst du als Aktion mit dem Helm den Zauber Gedanken wahrnehmen (Rettungswurf-SG 13) wirken. Solange du dich auf den Zauber konzentrierst, kannst du als Bonusaktion eine telepathische Botschaft an eine Kreatur senden, auf die du dich konzentrierst. Sie kann antworten -dies erfordert eine Bonusaktion -, solange du dich auf sie konzentrierst.","Wenn du dich mit Gedanken wahrnehmen auf eine Kreatur konzentrierst, kannst du als Aktion mit dem Helm den Zauber Einflüsterung (Rettungswurf-SG 13) auf diese Kreatur wirken. Nachdem die Einflüsterung-Eigenschaft verwendet wurde, kann sie erst im nächsten Morgengrauen wiederverwendet werden."],"attune":"erfordert Einstimmung"},
  {"id":"helm-der-teleportation","name":"Helm der Teleportation ","type":"Wundersamer Gegenstand","rarity":"selten","desc":["Dieser Helm hat drei Ladungen. Wenn du ihn trägst, kannst du als Aktion eine Ladung verbrauchen, um mit dem Helm den Zauber Teleportieren zu wirken. Der Helm erhält täglich im Morgengrauen 1W3 verbrauchte Ladungen zurück."],"attune":"erfordert Einstimmung"},
  {"id":"helm-des-sprachenverstehens","name":"Helm des Sprachenverstehens","type":"Wundersamer Gegenstand","rarity":"ungewöhnlich","desc":["Wenn du diesen Helm trägst, kannst du als Aktion mit dem Helm beliebig oft den Zauber Sprachen verstehen wirken."]},
  {"id":"henkersschwert","name":"Henkersschwert","type":"Waffe (beliebiges Schwert","rarity":"legendär","desc":["Du erhältst einen Bonus von +3 auf Angriffs- und Schadenswürfe, die du mit dieser magischen Waffe ausführst. Außerdem ignoriert die Waffe Resistenz gegen Hiebschaden.","Wenn du mit dieser Waffe eine Kreatur angreifst, die mindestens einen Kopf hat und beim Angriffswurf eine 20 würfelst, hackst du der Kreatur einen ihrer Köpfe ab. Die Kreatur stirbt, wenn sie ohne den verlorenen Kopf nicht überleben kann. Kreaturen sind gegen diesen Effekt immun, wenn sie gegen Hiebschaden immun sind, keinen Kopf haben oder brauchen, über legendäre Aktionen verfügen oder der SL beschließt, dass sie zu groß sind, als dass ihr Kopf mit dieser Waffe abgeschlagen werden könnte. In diesem Fall erleiden sie stattdessen zusätzlich 6W8 Hiebschaden durch den Treffer."],"attune":"beliebiges Schwert, das Hiebschaden verursacht"},
  {"id":"horn-der-sprengung","name":"Horn der Sprengung","type":"Wundersamer Gegenstand","rarity":"selten","desc":["Du kannst als Aktion das Befehlswort des Horns aussprechen und dann in das Horn blasen.","Es erzeugt in einem Kegel von neun Metern einen donnernden Ton, der 180 Meter weit zu hören ist Jede Kreatur in dem Kegel muss einen SG-15-Konstitutionsrettungswurf ausführen. Scheitert der Wurf, erleidet die jeweilige Kreatur 5W6 Schallschaden und ist eine Minute lang taub. Anderenfalls erleidet die jeweilige Kreatur halb so viel Schaden und ist nicht taub. Kreaturen und Gegenstände aus Glas oder Kristall sind bei dem Rettungswurf im Nachteil und erleiden 10W6 statt 5W6 Schallschaden.","Jedes Mal, wenn die Magie des Horns verwendet wird, besteht eine Chance von 20 Prozent, dass das Horn explodiert. Die Explosion verursacht beim Hornbläser 10W6 Feuerschaden und zerstört das Horn."]},
  {"id":"horn-von-walhalla","name":"Horn von Walhalla","type":"Wundersamer Gegenstand","rarity":"selten (Silber oder Messing), sehr selten (Bronze) oder legendär (Eisen)","desc":["Du kannst als Aktion in das Horn blasen. Daraufhin erscheinen Kriegergeister aus Walhalla im Abstand von bis zu 18 Metern von dir. Sie haben die Werte eines Berserkers. Nach einer Stunde oder wenn sie auf 0 Trefferpunkte sinken, kehren sie nach Walhalla zurück. Nachdem es verwendet wurde, kann das Horn erst nach sieben Tagen wiederverwendet werden.","Es sind vier Arten des Horns von Walhalla bekannt, die jeweils aus einem anderen Metall gefertigt sind. Die Hornart bestimmt, wie viele Berserker seinen Ruf beantworten und welche Voraussetzung zu seiner Verwendung erfüllt sein muss. Der SL wählt die Hornart aus oder bestimmt sie zufällig.","Wenn du in das Horn bläst ohne die Voraussetzung zu erfüllen, greifen die beschworenen Berserker dich an. Wenn du die Voraussetzung erfüllst, sind sie dir und deinen Verbündeten gegenüber freundlich und folgen deinen Befehlen."],"attune":"Silber oder Messing"},
  {"id":"hufeisen-der-geschwindigkeit","name":"Hufeisen der Geschwindigkeit","type":"Wundersamer Gegenstand","rarity":"selten","desc":["Diese eisernen Hufeisen sind in Vierersätzen zu finden. Wenn alle vier Hufeisen an den Hufen eines Pferds oder einer ähnlichen Kreatur befestigt sind, erhöhen sie die Schrittbewegungsrate der Kreatur um neun Meter."]},
  {"id":"hufeisen-des-zephyrs","name":"Hufeisen des Zephyrs","type":"Wundersamer Gegenstand","rarity":"sehr selten","desc":["Diese eisernen Hufeisen sind in Vierersätzen zu finden. Wenn alle vier Hufeisen an den Hufen eines Pferds oder einer ähnlichen Kreatur befestigt sind, kann sich die Kreatur normal bewegen, wobei sie zehn Zentimeter über dem Boden schwebt. Dieser Effekt erlaubt es der Kreatur, nicht feste oder instabile Oberflächen wie Wasser oder Lava zu überqueren oder auf ihnen zu stehen. Die Kreatur hinterlässt keine Spuren und ignoriert schwieriges Gelände. Außerdem kann die Kreatur sich bis zu zwölf Stunden lang am Tag mit normaler Bewegungsrate bewegen, ohne durch den Gewaltmarsch Erschöpfung zu erleiden."]},
  {"id":"hut-der-verkleidung","name":"Hut der Verkleidung","type":"Wundersamer Gegenstand","rarity":"ungewöhnlich","desc":["Wenn du diesen Hut trägst, kannst du als Aktion den Zauber Selbstverkleidung beliebig oft mit dem Hut wirken. Der Zauber endet, wenn der Hut abgesetzt wird."],"attune":"erfordert Einstimmung"},
  {"id":"ifriti-flasche","name":"Ifriti-Flasche","type":"Wundersamer Gegenstand","rarity":"sehr selten","desc":["Diese bemalte Glasflasche wiegt 0,5 Kilogramm. Du kannst als Aktion den Stopfen ziehen. Daraufhin wabert ein dicker Rauch aus der Flasche. Am Ende deines Zugs verschwindet der Rauch mit einer harmlosen Stichflamme und ein Ifriti erscheint an einer freien Stelle im Abstand von bis zu neun Metern von dir.","Wenn die Flasche zum ersten Mal geöffnet wird, würfelt der SL, um zu bestimmen, was passiert."]},
  {"id":"ionenstein","name":"Ionenstein","type":"Wundersamer Gegenstand","rarity":"Seltenheit variiert","desc":["Ionensteine tragen ihren Namen in Anlehnung an die Göttin loun, die für Wissen und Prophezeiungen steht und auf manchen Welten verehrt wird. Es gibt viele Arten von Ionensteinen mit einer jeweils eigenen Kombination aus Form und Farbe.","Wenn du eine Aktion verwendest, um einen dieser Steine in die Luft zu werfen, umkreist der Stein deinen Kopf im Abstand von 1W3 mal 30 Zentimetern und hat einen positiven Effekt auf dich. Danach muss eine andere Kreatur eine Aktion verwenden, um den Stein zu ergreifen oder abzufangen und so von dir zu trennen. Dafür muss die Kreatur entweder einen Angriffswurf gegen eine RK von 24 oder einen SG-24-Geschicklichkeitswurf (Akrobatik) bestehen. Du kannst den Stein als Aktion ergreifen und wegstecken, wodurch sein Effekt endet.","Ein Stein besitzt eine RKvon 24,10 Trefferpunkte und ist gegen alle Schadensarten resistent. Wenn er deinen Kopf umkreist, gilt er als Gegenstand, der getragen wird.","Absorption (sehr selten): Wenn dieser blasslilafarbene elliptische Stein deinen Kopf umkreist, kannst du als Reaktion einen Zauber des maximal 4. Grades aufheben, der nur auf dich und von einer Kreatur gewirkt wurde, die du sehen kannst.","Wenn der Stein insgesamt 20 Zaubergrade aufgehoben hat, brennt er aus, wird mattgrau und verliert seine Magie. Wenn du das Ziel eines Zaubers bist, dessen Grad höher als die Anzahl der Zaubergrade ist, über die der Stein verfügt, kann der Stein ihn nicht aufheben.","Agilität (sehr selten): Wenn dieser tiefrote, kugelrunde Stein deinen Kopf umkreist, steigt dein Geschicklichkeitswert um 2 (auf maximal 20).","Erkenntnis (sehr selten): Wenn dieser leuchtend blaue, kugelrunde Stein deinen Kopf umkreist, steigt dein Weisheitswert um 2 (auf maximal 20).","Ernährung (selten): Wenn dieser farblose, spindelförmige Stein deinen Kopf umkreist, musst du weder essen noch trinken.","Führungskraft (sehr selten): Wenn dieser kugelrunde, rosa und grün marmorierte Stein deinen Kopf umkreist, steigt dein Charismawert um 2 (auf maximal 20).","Höhere Absorption (legendär): Wenn dieser elliptische, lilafarben und grün marmorierte Stein deinen Kopf umkreist, kannst du als Reaktion einen Zauber des maximal 8. Grades aufheben, der nur auf dich und von einer Kreatur gewirkt wurde, die du sehen kannst.","Meisterschaft (legendär): Wenn dieses hellgrüne Prisma deinen Kopf umkreist, steigt dein Übungsbonus um 1.","Regeneration (legendär): Am Ende jeder Stunde, in der dieser perlweiße, spindelförmige Stein deinen Kopf umkreist, erhältst du 15 Trefferpunkte zurück, sofern du mindestens 1 Trefferpunkt hast.","Reserve (selten): Dieses leuchtend violette Prisma speichert Zauber, die in es gewirkt werden, sodass du sie später verwenden kannst Der Stein kann Zauber im Gesamtwert von bis zu drei Zaubergraden aufhehmen. Wenn er gefunden wird, enthält er 1W4-1 Zaubergrade in Form von Zaubern, die der SL bestimmt","Jede Kreatur kann einen Zauber des 1. bis 3. Grades in den Stein wirken, indem sie den Stein berührt, während sie den Zauber wirkt Der Zauber hat keinen Effekt und wird nur in dem Stein gespeichert Wenn der Stein den Zauber nicht aufnehmen kann, wird der Zauber wirkungslos verbraucht. Der beim Wirken verwendete Zaubergrad bestimmt, wie viel Platz der Zauber im Stein verbraucht.","Wenn dieser Stein deinen Kopf umkreist, kannst du die im Stein gespeicherten Zauber wirken. Der Zauber verwendet den Zaubergrad, den Zauberrettungswurf-SG, den Bonus für Zauberangriffe und das Attribut zum Zauberwirken des ursprünglichen Zauberwirkers, wird aber in jeder anderen Form behandelt, als hättest du den Zauber gewirkt. Der aus dem Stein gewirkte Zauber ist dann nicht mehr im Stein gespeichert und gibt seinen Platz frei.","Schutz (selten): Wenn dieses mattrosafarbene Prisma deinen Kopf umkreist, erhältst du einen Bonus von +1 auf deine RK.","Standhaftigkeit (sehr selten): Wenn dieser rosa, rautenförmige Stein deinen Kopf umkreist, steigt dein Konstitutionswert um 2 (auf maximal 20), Wenn der Stein insgesamt 50 Zaubergrade aufgehoben hat, brennt er aus, wird mattgrau und verliert seine Magie. Wenn du das Ziel eines Zaubers bist, dessen Grad höher als die Anzahl der Zaubergrade ist, über die der Stein verfügt, kann der Stein ihn nicht aufheben.","Stärke (sehr selten): Wenn dieser hellblaue, rautenförmige Stein deinen Kopf umkreist, steigt dein Stärkewert um 2 (auf maximal 20),","Verstand (sehr selten): Wenn dieser kugelrunde, scharlachrot und blau marmorierte Stein deinen Kopf umkreist, steigt dein Intelligenzwert um 2 (auf maximal 20),","Wahrnehmung (selten): Wenn dieser dunkelblaue, rautenförmige Stein deinen Kopf umkreist, kannst du nicht überrascht werden."],"attune":"erfordert Einstimm ung"},
  {"id":"karaffe-des-endlosen-wassers","name":"Karaffe des endlosen Wassers","type":"Wundersamer Gegenstand","rarity":"ungewöhnlich","desc":["Diese verkorkte Karaffe klingt, als wäre Wasser darin, wenn du sie schüttelst. Die Karaffe wiegt ein Kilogramm.","Du kannst als Aktion den Stopfen entfernen und eins von drei Befehlswörtern aussprechen. Daraufhin fließt eine bestimmte Menge an Süß- oder Salzwasser aus der Karaffe (du entscheidest). Das Wasser fließt bis zum Beginn deines nächsten Zugs. Wähle eine der folgenden Optionen aus:"]},
  {"id":"karten-der-illusionen","name":"Karten der Illusionen","type":"Wundersamer Gegenstand","rarity":"ungewöhnlich","desc":["Diese Schatulle enthält einen Satz Pergamentkarten. Ein vollständiger Satz besteht aus 34 Karten. Wenn die Karten als Teil eines Schatzes gefunden werden, fehlen in der Regel 1W20-1 Karten.","Die Magie der Karten funktioniert nur, wenn die Karten zufällig gezogen werden (du kannst angepasste Spielkarten verwenden). Du kannst als Aktion eine zufällige Karte aus dem Stapel ziehen und sie an einem Punkt im Abstand von bis zu neun Metern von dir auf den Boden werfen.","Die Illusion mindestens einer Kreatur entsteht über der geworfenen Karte und bleibt bestehen, bis sie gebannt wird. Eine illusionäre Kreatur erscheint real, hat die passende Größe und verhält sich, als wäre sie eine reale Kreatur. Sie kann allerdings keinen Schaden zufügen. Wenn du dich im Abstand von bis zu 36 Metern von der Kreatur befindest und sie sehen kannst, kannst du sie als Aktion auf magische Weise an einen anderen Ort im Abstand von bis zu neun Metern von ihrer Karte bewegen. Physische Interaktionen mit der illusionären Kreatur enttarnen sie als Illusion, da Gegenstände sie einfach durchdringen können. Wenn jemand eine Aktion verwendet, um die Kreatur genauer anzuschauen, erkennt er die Illusion mit einem erfolgreichen SG-15-Intelligenzwurf (Nachforschungen), Die Kreatur erscheint dann durchscheinend.","Die Illusion hält an, bis ihre Karte bewegt oder die Illusion gebannt wird. Wenn die Illusion endet, verschwindet das Bild auf der entsprechenden Karte und diese Karte kann nicht mehr verwendet werden."]},
  {"id":"kerze-der-anrufung","name":"Kerze der Anrufung","type":"Wundersamer Gegenstand","rarity":"sehr selten","desc":["Diese schlanke Wachskerze ist einer Gottheit geweiht und hat dieselbe Gesinnung. Die Gesinnung der Kerze kann durch den Zauber Gutes und Böses entdecken aufgedeckt werden. Der SL wählt die Gottheit und die entsprechende Gesinnung aus oder bestimmt die Gesinnung zufällig.","Die Magie der Kerze wird aktiv, wenn die Kerze angezündet wird. Dies erfordert eine Aktion. Nachdem sie vier Stunden gebrannt hat, ist die Kerze zerstört. Du kannst sie vorher ausblasen, um sie später wieder zu verwenden. Ziehe die Brenndauer in Minutenschritten von der Gesamt-Brenndauer der Kerze ab.","Wenn sie brennt, spendet die Kerze in einem Radius von neun Metern dämmriges Licht Kreaturen innerhalb des Lichtradius, deren Gesinnung mit der Gesinnung der Kerze übereinstimmt, sind bei Angriffs-, Rettungs- und Attributswürfen im Vorteil. Außerdem kann ein Kleriker oder Druide, der sich im Lichtradius befindet und dessen Gesinnung mit der Kerze übereinstimmt, vorbereitete Zauber des 1. Grades wirken, ohne dafür Zauberplätze zu verbrauchen. Die Zauber haben dieselbe Wirkung, als wären sie mit einem Zauberplatz des 1. Grades gewirkt worden.","Alternativ kannst du, wenn du die Kerze zum ersten Mal anzündest, den Zauber Tor wirken. Dies zerstört die Kerze."],"attune":"erfordert Einstimmung"},
  {"id":"kristallkugel","name":"Kristallkugel","type":"Wundersamer Gegenstand","rarity":"sehr selten oder legendär","desc":["Eine typische Kristallkugel ist ein sehr seltener Gegenstand und hat einen Durchmesser von etwa 15 Zentimetern. Wenn du sie berührst, kannst du den Zauber Ausspähung (Rettungswurf-SG 17) mit ihr wirken.","Die folgenden Kristallkugel-Varianten sind legendäre Gegenstände und haben zusätzliche Eigenschaften.","Kristallkugel des Gedankenlesens: Während du mit der Kristallkugel ausspähst, kannst du als Aktion den Zauber Gedanken wahrnehmen (Rettungswurf-SG 17) wirken. Du kannst dabei Kreaturen als Ziel auswählen, die du im Abstand von bis zu neun Metern vom Sensor des Zaubers sehen kannst. Du musst dich nicht auf Gedanken wahrnehmen konzentrieren, um den Zauber während seiner Wirkungsdauer aufrechtzuerhalten. Er endet jedoch, wenn die Ausspähung endet.","Kristallkugel der Telepathie: Während du mit der Kristallkugel ausspähst, kannst du telepathisch mit Kreaturen kommunizieren, die du im Abstand von bis zu neun Metern vom Sensor des Zaubers sehen kannst. Du kannst als Aktion auch den Zauber Einflüsterung (Rettungswurf-SG 17) durch den Sensor auf eine dieser Kreaturen wirken. Du musst dich nicht auf Einflüsterung konzentrieren, um den Zauber während seiner Wirkungsdauer aufrechtzuerhalten. Er endet jedoch, wenn die Ausspähung endet Nachdem sie verwendet wurde, kann die Kristallkugel erst im nächsten Morgengrauen wieder für Einflüsterung verwendet werden.","Kristallkugel des Wahren Blicks: Wenn du durch die Kristallkugel ausspähst, hast du in einem Radius von 36 Metern um den Sensor des Zaubers herum Wahrer Blick."],"attune":"erfordert Einstimmung"},
  {"id":"krummsaebel-der-geschwindigkeit","name":"Krummsäbel der Geschwindigkeit","type":"Waffe (Krummsäbel)","rarity":"sehr selten","desc":["Du erhältst einen Bonus von +2 auf Angriffs- und Schadenswürfe, die du mit dieser magischen Waffe ausführst. Außerdem kannst du damit in jedem Zug einen Angriff als Bonusaktion ausführen."],"attune":"Krummsäbel"},
  {"id":"kugel-der-drachen","name":"Kugel der Drachen","type":"Wundersamer Gegenstand","rarity":"Artefakt","desc":["Vor ewigen Zeiten führten Elfen und Menschen einen furchtbaren Krieg gegen böse Drachen. Als die Welt dem Untergang geweiht schien, versammelten sich mächtige Magier und wirkten ihre stärksten Zauber, um fünf Kugeln der Drachen - oder Drachenkugeln -zu schaffen und so zu helfen, die Drachen zu besiegen. Jeweils eine Kugel wurde zu einem der fünf Magiertürme gebracht. Dort wurden sie verwendet, um den Krieg bald darauf zu einem siegreichen Ende zu führen. Die Magier nutzten die Kugeln, um Drachen zu sich zu locken und sie dann mit mächtiger Magie zu zerstören.","Die Magiertürme zerfielen im Laufe der Zeit zu Ruinen, die Kugeln wurden zerstört oder verblassten zu Legenden. Es wird angenommen, dass nur drei der Kugeln die Zeiten überdauert haben. Im Laufe der Jahrhunderte wandelte sich ihre Magie. Obwohl sie ihren Hauptzweck noch erfüllen und Drachen herbeirufen, ermöglichen sie auch eine gewisse Kontrolle über Drachen.","Jede Kugel enthält die Essenz eines bösen Drachen. Diese Präsenz hasst es, dass der Kugel Magie entlockt wird. Schwache Persönlichkeiten können Gefahr laufen, von einer Kugel versklavt zu werden.","Eine Kugel ist eine geätzte Kristallkugel mit einem Durchmesser von rund 25 Zentimetern. Wenn sie verwendet wird, wächst ihr Durchmesser auf rund 50 Zentimeter an und in ihrem Inneren beginnt ein Nebel zu wirbeln.","Wenn du auf eine Kugel eingestimmt bist, kannst du als Aktion in die Tiefen der Kugel schauen und ihr Befehlswort aussprechen. Führe dann einen SG-15-Charismawurf aus. Bei einem Erfolg kontrollierst du die Kugel, solange du auf sie eingestimmt bist. Anderenfalls bist du von der Kugel bezaubert, solange du auf sie eingestimmt bist.","Während du von der Kugel bezaubert bist, kannst du deine Einstimmung auf sie nicht freiwillig beenden, und die Kugel wirkt beliebig oft Einflüsterung (Rettungswurf-SG 18) auf dich, um dich anzustacheln, die Arbeit an ihren bösen Zielen voranzutreiben.","Die Drachenessenz in der Kugel kann viele verschiedene Ziele haben: Sie kann die Vernichtung eines bestimmten Volks wünschen, Freiheit von der Kugel anstreben, Leid auf der Welt verbreiten wollen, die Vermehrung von Tiamats Gefolgschaft im Sinn haben oder ein anderes Ziel verfolgen, das der SL festlegt.","Zufällige Eigenschaften: Eine Kugel der Drachen hat die folgenden zufälligen Eigenschaften:","Zauber: Die Kugel hat sieben Ladungen und erhält täglich im Morgengrauen 1W4+3 verbrauchte Ladungen zurück. Wenn du die Kugel kontrollierst, kannst du als Aktion eine oder mehrere Ladungen verbrauchen, um einen der folgenden Zauber mit ihr zu wirken (Rettungswurf-SG 18): Ausspähung (drei Ladungen), Tageslicht (eine Ladung), Todesschutz (zwei Ladungen) oder Wunden heilen (5. Grades, drei Ladungen).","Du kannst außerdem eine Aktion verwenden, um mit der Kugel den Zauber Magie entdecken zu wirken, ohne Ladungen zu verbrauchen.","Drachen herbeirufen: Während du die Kugel kontrollierst, kannst du als Aktion das Artefakt dazu bringen, einen telepathischen Ruf auszusenden, der sich 64 Kilometer weit in alle Richtungen ausbreitet. Böse Drachen in Reichweite werden veranlasst, so schnell wie möglich und auf direktem Wege zur Kugel zu kommen. Drachengottheiten wie Tiamat werden von diesem Ruf nicht betroffen. Drachen, die von der Kugel angezogen werden, können dir feindlich gesinnt sein, weil du sie gegen ihren Willen gerufen hast. Nachdem du diese Eigenschaft verwendet hast, kann sie erst eine Stunde später erneut verwendet werden.","Eine Kugel zerstören: Eine Kugel der Drachen scheint zerbrechlich zu sein, ist aber gegen die meisten Schadensarten immun. Selbst die Odemwaffen von Drachen können ihr nichts anhaben. Der Zauber Auflösung oder ein guter Treffer mit einer magischen Waffe +3 kann eine Kugel jedoch zerstören."],"attune":"erfordert Einstimmung"},
  {"id":"laterne-der-enttarnung","name":"Laterne der Enttarnung","type":"Wundersamer Gegenstand","rarity":"ungewöhnlich","desc":["Wenn sie verwendet wird, brennt diese Blendlaterne mit 0,5 Litern Öl sechs Stunden lang und spendet im Radius von neun Metern helles Licht und im Radius von weiteren neun Metern dämmriges Licht. Unsichtbare Kreaturen und Gegenstände sind sichtbar, solange sie sich im hellen Licht der Laterne befinden. Du kannst als Aktion die Haube absenken und so das Licht auf dämmriges Licht in einem Radius von 1,5 Metern reduzieren."]},
  {"id":"leitfaden-der-fuehrungskraft-und-der-einflussnahme","name":"Leitfaden der Führungskraft und der Einflussnahme","type":"Wundersamer Gegenstand","rarity":"sehr selten","desc":["Dieses magisch geladene Buch enthält Richtlinien zur Beeinflussung und Bezauberung anderer. Wenn du über einen Zeitraum von maximal sechs Tagen 48 Stunden damit verbringst, den Inhalt des Buchs zu studieren und seine Anleitungen zu befolgen, erhöhen sich dein Charismawert und dein Maximalwert für Charisma um 2. Das Handbuch verliert dann seine Magie, erhält sie jedoch nach einem Jahrhundert zurück."]},
  {"id":"leitfaden-des-klaren-denkens","name":"Leitfaden des klaren Denkens","type":"Wundersamer Gegenstand","rarity":"sehr selten","desc":["Dieses magisch geladene Buch enthält Gedächtnis-und Logikübungen. Wenn du über einen Zeitraum von maximal sechs Tagen 48 Stunden damit verbringst, den Inhalt des Buchs zu studieren und seine Anleitungen zu befolgen, erhöhen sich dein Intelligenzwert und dein Maximalwert für Intelligenz um 2. Das Handbuch verliert dann seine Magie, erhält sie jedoch nach einem Jahrhundert zurück."]},
  {"id":"leitfaden-des-verstaendnisses","name":"Leitfaden des Verständnisses","type":"Wundersamer Gegenstand","rarity":"sehr selten","desc":["Dieses magisch geladene Buch enthält Intuitions- und Verständnisübungen. Wenn du über einen Zeitraum von maximal sechs Tagen 48 Stunden damit verbringst, den Inhalt des Buchs zu studieren und seine Anleitungen zu befolgen, erhöhen sich dein Weisheitswert und dein Maximalwert für Weisheit um 2. Das Handbuch verliert dann seine Magie, erhält sie jedoch nach einem Jahrhundert zurück."]},
  {"id":"liebestrank","name":"Liebestrank","type":"Trank","rarity":"ungewöhnlich","desc":["Du wirst von der nächsten Kreatur eine Stunde lang bezaubert, die du innerhalb von zehn Minuten nach dem Trinken dieses Tranks siehst. Wenn du Spezies und Geschlecht der Kreatur normalerweise attraktiv findest, siehst du sie als deine wahre Liebe an, solange du bezaubert bist. Die rosafarbene, sprudelnde Flüssigkeit des Tranks enthält eine leicht übersehbare Blase in Herzform."]},
  {"id":"mantel-des-zauberwiderstands","name":"Mantel des Zauberwiderstands","type":"Wundersamer Gegenstand","rarity":"selten","desc":["Wenn du diesen Mantel trägst, bist du bei Rettungswürfen gegen Zauber im Vorteil."],"attune":"erfordert Einstimmung"},
  {"id":"medaillon-der-gedanken","name":"Medaillon der Gedanken","type":"Wundersamer Gegenstand","rarity":"ungewöhnlich","desc":["Das Medaillon hat drei Ladungen. Wenn du es trägst, kannst du als Aktion eine Ladung verbrauchen, um den Zauber Gedanken wahrnehmen (Rettungswurf-SG 13) damit zu wirken. Das Medaillon erhält täglich im Morgengrauen 1W3 verbrauchte Ladungen zurück."],"attune":"erfordert Einstimmung"},
  {"id":"mithralruestung","name":"Mithralrüstung","type":"Rüstung (mittelschwer oder schwer","rarity":"ungewöhnlich","desc":["Mithral ist ein leichtes, flexibles Metall. Mithralkettenhemden oder -brustplatten können unter normalen Kleidungsstücken getragen werden. Wenn die Rüstung normalerweise einen Nachteil bei Geschicklichkeitswürfen (Heimlichkeit) verleiht oder eine Stärkevoraussetzung hat, gilt bei der Mithralrüstung keines von beidem."],"attune":"mittelschwer oder schwer, nicht Fell"},
  {"id":"nachtbrille","name":"Nachtbrille","type":"Wundersamer Gegenstand","rarity":"ungewöhnlich","desc":["Diese dunkle Brille gibt dir Dunkelsicht auf eine Entfernung von bis zu 18 Metern. Hast du bereits Dunkelsicht, so erhöht diese Brille deine Sichtweite um 18 Meter."]},
  {"id":"nimmervoller-beutel","name":"Nimmervoller Beutel","type":"Wundersamer Gegenstand","rarity":"ungewöhnlich","desc":["Das Innere dieses Beutels ist wesentlich größer als seine Außenmaße: Seine Öffnung hat einen Durchmesser von etwa 0,6 Metern und er ist 1,2 Meter tief. Der Beutel kann bis zu 250 Kilogramm und maximal 1.792 Liter fassen. Der Beutel wiegt unabhängig von seinem Inhalt 7,5 Kilogramm. Das Herausholen eines Gegenstands aus dem Beutel erfordert eine Aktion.","Wenn er überfüllt, durchbohrt oder zerrissen wird, zerreißt und zerstört dies den Beutel, und sein Inhalt wird in der Astralebene zerstreut. Wenn der Beutel umgestülpt wird, fällt sein gesamter Inhalt unbeschädigt heraus. Bevor er wieder genutzt werden kann, muss er jedoch wieder auf rechts gedreht werden. Atmende Kreaturen können bis zu zehn Minuten darin überleben (geteilt durch die Anzahl an Kreaturen im Beutel, mindestens eine Minute), bevor sie beginnen zu ersticken.","Wenn ein Nimmervoller Beutel in den extradimensionalen Raum eines Praktischen Rucksacks, eines Tragbaren Lochs oder eines ähnlichen Gegenstands gelangt, zerstört dies sofort beide Gegenstände, und ein Tor in die Astralebene öffnet sich. Das Tor erscheint dort, wo der eine Gegenstand in den anderen gelangt ist. Kreaturen im Abstand von bis zu drei Metern vom Tor werden hineingezogen und an einen zufälligen Ort auf der Astralebene transportiert. Dann schließt sich das Tor. Das Tor funktioniert nur in eine Richtung und kann nicht wieder geöffnet werden."]},
  {"id":"oel-der-glaette","name":"Öl der Glätte","type":"Trank","rarity":"ungewöhnlich","desc":["Diese klebrige, schwarze Salbe wirkt im Gefäß sehr dickflüssig und zäh, verteilt sich aber schnell, wenn sie ausgegossen wird. Das Öl kann eine höchstens mittelgroße Kreatur mit all ihrer getragenen und mitgeführten Ausrüstung bedecken (für jede Größenkategorie über mittelgroß wird eine weitere Phiole benötigt). Das Aufträgen des Öls dauert zehn Minuten. Die vom Öl bedeckte Kreatur erhält dann für acht Stunden den Effekt des Zaubers Bewegungsfreiheit.","Alternativ kann das Öl als Aktion auf den Boden gegossen werden, wo es einen quadratischen Bereich mit einer Kantenlänge von drei Metern bedeckt. Es dupliziert in diesem Bereich acht Stunden lang den Effekt des Zaubers Schmieren."]},
  {"id":"oel-der-koerperlosigkeit","name":"Öl der Körperlosigkeit","type":"Trank","rarity":"selten","desc":["An der Außenseite des Behälters bilden sich Tropfen dieses trübgrauen Öls, die schnell verdunsten. Das Öl kann eine höchstens mittelgroße Kreatur mit all ihrer getragenen und mitgeführten Ausrüstung bedecken (für jede Größenkategorie über mittelgroß wird eine weitere Phiole benötigt). Das Aufträgen des Öls dauert zehn Minuten. Die vom Öl bedeckte Kreatur erhält eine Stunde lang den Effekt des Zaubers Ätherische Gestalten."]},
  {"id":"oel-der-schaerfe","name":"Öl der Schärfe","type":"Trank","rarity":"sehr selten","desc":["In diesem klaren, gelatineartigen Öl glitzern winzige, extrem dünne Silbersplitter. Das Öl kann eine Hieb- oder Stichwaffe oder bis zu fünf Hieb- oder Stichgeschosse bedecken. Das Aufträgen des Öls dauert eine Minute. Der eingeölte Gegenstand ist eine Stunde lang magisch und hat einen Bonus von +3 auf Angriffs- und Schadenswürfe."]},
  {"id":"panzerhandschuhe-der-ogerkraft","name":"Panzerhandschuhe der Ogerkraft ","type":"Wundersamer Gegenstand","rarity":"ungewöhnlich","desc":["Wenn du diese Panzerhandschuhe trägst, ist dein Stärkewert 19. Sie haben keinen Effekt, wenn er bereits 19 oder höher ist."],"attune":"erfordert Einstimmung"},
  {"id":"perle-der-kraft","name":"Perle der Kraft","type":"Wundersamer Gegenstand","rarity":"selten","desc":["Diese kleine schwarze Kugel hat einen Durchmesser von etwa zwei Zentimetern und wiegt rund 30 Gramm. Üblicherweise finden sich 1W4+4 Perlen der Kraft auf einmal.","Du kannst die Perle als Aktion bis zu 18 Meter weit werfen. Die Perle explodiert beim Aufprall und wird zerstört Jede Kreatur in einem Radius von drei Metern um den Punkt, an dem die Perle aufgetroffen ist, muss einen SG-15-Geschicklichkeitsrettungswurfbestehen, oder sie erleidet 5W4 Energieschaden. Dann umschließt eine Sphäre aus transparenter Energie den Bereich eine Minute lang. Jede Kreatur, deren Rettungswurf scheitert und die sich vollständig im betroffenen Bereich befindet, ist in der Sphäre gefangen. Kreaturen, die ihren Rettungswurf bestehen oder die sich nur teilweise im betroffenen Bereich befinden, werden vom Zentrum der Sphäre weggestoßen, bis sie außerhalb ihres Bereichs sind. Nur Atemluft kann die Wand der Sphäre passieren. Angriffe oder andere Effekte bleiben außen vor.","Eine gefangene Kreatur kann sich als Aktion gegen die Wand der Sphäre lehnen und die Sphäre so bis zur halben Schrittbewegungsrate der Kreatur bewegen. Die Sphäre kann aufgehoben werden. Dank ihrer Magie wiegt sie unabhängig vom Gewicht der Kreaturen in ihrem Inneren nur 0,5 Kilogramm."]},
  {"id":"perle-der-macht","name":"Perle der Macht","type":"Wundersamer Gegenstand","rarity":"ungewöhnlich","desc":["Solange du diese Perle bei dir trägst, kannst du als Aktion ihr Befehlswort aussprechen und einen verbrauchten Zauberplatz zurückerhalten. Wenn der verbrauchte Platz ein Platz des 4. oder höheren Grades war, ist der neue Platz ein Zauberplatz des 3. Grades. Nachdem du die Perle verwendet hast, kannst du sie erst im nächsten Morgengrauen erneut verwenden."],"attune":"erfordert Einstimmung durch einen Zauberwirker"},
  {"id":"pfeil-des-toetens","name":"Pfeil des Tötens","type":"Waffe (Pfeil)","rarity":"sehr selten","desc":["Ein Pfeil des Tötens ist eine magische Waffe, die erschaffen wurde, um eine bestimmte Art Kr eatur zu töten. Manche sind spezifischer als andere. Es gibt zum Beispiel Pfeile des Drachentötens und Pfeile des Blauer-Drachen-Tötens. Wenn eine Kreatur, deren Typ, Volk oder Gruppe mit einem Pfeil des Tötens verbunden ist, durch den Pfeil Schaden erleidet, muss die Kreatur einen SG-17-Konstitutionsrettungswurf bestehen. Scheitert der Wurf, erleidet sie zusätzlich 6W10 Stichschaden, anderenfalls die Hälfte.","Nachdem ein Pfeil des Tötens einer Kreatur seinen zusätzlichen Schaden zugefügt hat, wird er zu einem nichtmagischen Pfeil.","Es gibt auch andere magische Geschosse dieser Art, zum Beispiel Bolzen des Tötens für Armbrüste. Pfeile sind allerdings am üblichsten."],"attune":"Pfeil"},
  {"id":"pfeilfangender-schild","name":"Pfeilfangender Schild","type":"Rüstung (Schild)","rarity":"selten","desc":["Wenn du diesen Schild trägst, erhältst du einen Bonus von +2 gegen Fernkampfangriffe auf deine RK Dieser Bonus des Schildes wirkt zusätzlich zu seinem normalen Bonus auf die RK Wenn ein Angreifer einen Fernkampfangriff gegen ein Ziel im Abstand von bis zu 1,5 Metern von dir ausführt, kannst du außerdem als Reaktion selbst das Ziel werden."],"attune":"Schild"},
  {"id":"praktischer-rucksack","name":"Praktischer Rucksack","type":"Wundersamer Gegenstand","rarity":"selten","desc":["Dieser Rucksack hat eine mittlere Tasche und zwei Seitentaschen, die alle einen extradimensionalen Raum enthalten. Jede Seitentasche kann bis zu zehn Kilogramm Material aufhehmen, solange dessen Volumen nicht größer als 56 Liter ist. Die große mittlere Tasche kann bis zu 224 Liter oder 40 Kilogramm Material aufnehmen. Der Rucksack wiegt unabhängig von seinem Inhalt immer 2,5 Kilogramm.","Einen Gegenstand in den Rucksack zu legen folgt den normalen Regeln zur Interaktion mit Gegenständen. Das Herausholen eines Gegenstands aus dem Rucksack erfordert eine Aktion. Wenn du in den Rucksack greifst, um einen bestimmten Gegenstand herauszuholen, ist der entsprechende Gegenstand auf magische Weise obenauf.","Für den Rucksack gelten einige Einschränkungen. Wenn er überlastet, von einem Gegenstand durchbohrt oder zerrissen wird, zerbirst der Rucksack und wird zerstört. Wenn der Rucksack zerstört wird, geht sein Inhalt für immer verloren. Nur Artefakte erscheinen an einem zufälligen Ort wieder. Wenn der Rucksack umgestülpt wird, fällt sein gesamter Inhalt unbeschädigt heraus. Bevor er wieder genutzt werden kann, muss er jedoch wieder auf rechts gedreht werden. Wenn eine atmende Kreatur in den Rucksack gelegt wird, kann die Kreatur bis zu zehn Minuten lang überleben. Danach beginnt sie zu ersticken.","Wenn der Rucksack in den extradimensionalen Raum eines Nimmervollen Beutels, eines Tragbaren Lochs oder eines ähnlichen Gegenstands gelangt, zerstört dies sofort beide Gegenstände, und ein Tor in die Astralebene öffnet sich. Das Tor erscheint dort, wo der eine Gegenstand in den anderen gelangt ist. Kreaturen im Abstand von bis zu drei Metern vom Tor werden hineingezogen und an einen zufälligen Ort auf der Astralebene transportiert. Dann schließt sich das Tor. Das Tor funktioniert nur in eine Richtung und kann nicht wieder geöffnet werden."]},
  {"id":"rauchfass-der-luftelementar-herrschaft","name":"Rauchfass der Luftelementar-Herrschaft","type":"Wundersamer Gegenstand","rarity":"selten","desc":["Wenn in diesem Räuchergefäß Weihrauch brennt, kannst du als Aktion das Befehlswort für das Rauchfass aussprechen und einen Luftelementar beschwören, als hättest du den Zauber Elementar beschwören gewirkt. Das Rauchfass kann erst im nächsten Morgengrauen wieder auf diese Weise verwendet werden.","Dieses 15 Zentimeter breite und 30 Zentimeter hohe Gefäß ähnelt einem Kelch mit einer dekorierten Abdeckung. Es wiegt 0,5 Kilogramm."]},
  {"id":"rauchflasche","name":"Rauchflasche","type":"Wundersamer Gegenstand","rarity":"ungewöhnlich","desc":["Obwohl sie mit einem Bleistopfen versiegelt ist, dringt aus dieser 0,5 Kilogramm schweren Flasche Rauch. Wenn du eine Aktion verwendest, um den Stopfen herauszuziehen, quillt in einem Radius von 18 Metern um die Flasche eine dichte Rauchwolke hervor. Der Bereich der Wolke ist komplett verschleiert Mit jeder Minute, die die Flasche geöffnet und innerhalb der Wolke bleibt, vergrößert sich der Radius um 1,5 Meter, bis der Maximalradius von 36 Metern erreicht ist.","Die Wolke bleibt bestehen, solange die Flasche geöffnet ist. Um die Flasche zu schließen, musst du als Aktion ihr Befehlswort aussprechen. Nachdem die Flasche verschlossen wurde, löst sich die Wolke innerhalb von zehn Minuten auf. Mäßiger Wind (17,6 bis 32 Kilometer pro Stunde) kann den Rauch in einer Minute verwehen, und starker Wind (33,6 Kilometer pro Stunde oder mehr) braucht dafür nur eine Runde."]},
  {"id":"restaurative-salbe","name":"Restaurative Salbe","type":"Wundersamer Gegenstand","rarity":"ungewöhnlich","desc":["Dieses Glasgefäß hat einen Durchmesser von 7,5 Zentimetern und enthält 1W4+1 Dosen einer zähen Salbe, die leicht nach Aloe riecht. Das Glas und die Salbe wiegen zusammen 250 Gramm.","Eine Dosis der Salbe kann als Aktion geschluckt oder auf die Haut aufgetragen werden. Die so behandelte Kreatur erhält 2W8+2 Trefferpunkte zurück, ist nicht mehr vergiftet und von allen Krankheiten geheilt."]},
  {"id":"riesentoeter","name":"Riesentöter","type":"Waffe (beliebige Axt oder beliebiges Schwert)","rarity":"selten","desc":["Du erhältst einen Bonus von +1 auf Angriffs- und Schadenswürfe, die du mit dieser magischen Waffe ausführst.","Wenn du einen Riesen mit ihr triffst, erleidet er zusätzlich 2W6 Schaden des Waffentyps und muss einen SG-15-Stärkerettungswurf bestehen oder wird umgestoßen. Als Riese zählen dabei alle Kreaturen, die den Typ 'Riese' haben, auch Ettin und Trolle."],"attune":"beliebige Axt oder beliebiges Schwert"},
  {"id":"ring-der-bewegungsfreiheit","name":"Ring der Bewegungsfreiheit","type":"Ring","rarity":"selten","desc":["Wenn du diesen Ring trägst, kostet dich schwieriges Gelände keine zusätzliche Bewegung. Außerdem kann Magie weder deine Bewegungsrate reduzieren noch dazu führen, dass du gelähmt oder festgesetzt wirst."],"attune":"erfordert Einstimmung"},
  {"id":"ring-der-drei-wuensche","name":"Ring der drei Wünsche","type":"Ring","rarity":"Legendär","desc":["Wenn du diesen Ring trägst, kannst du als Aktion eine seiner drei Ladungen verbrauchen, um mit ihm den Zauber Wunsch zu wirken. Der Ring wird nichtmagisch, nachdem du die letzte Ladung verbraucht hast."]},
  {"id":"ring-der-dschinni-beschwoerung","name":"Ring der Dschinni-Beschwörung","type":"Ring","rarity":"legendär","desc":["Wenn du diesen Ring trägst, kannst du als Aktion sein Befehlswort aussprechen, um einen bestimmten Dschinni von der Elementarebene der Luft zu beschwören. Der Dschinni erscheint an einer freien Stelle deiner Wahl im Abstand von bis zu 36 Metern von dir. Er bleibt so lange, wie du dich konzentrierst (wie bei einem Zauber), maximal jedoch eine Stunde lang oder bis seine Trefferpunkte auf 0 sinken. Er kehrt dann auf seine Heimatebene zurück.","Während er beschworen ist, ist der Dschinni dir und deinen Verbündeten gegenüber freundlich. Er gehorcht deinen Befehlen, unabhängig von der Sprache, in der du sie gibst. Wenn du ihm keine Befehle gibst, verteidigt sich der Dschinni gegen Angreifer, führt aber keine anderen Aktionen aus.","Nachdem der Dschinni verschwunden ist, kann er 24 Stunden lang nicht wieder gerufen werden und der Ring wird nichtmagisch, wenn der Dschinni stirbt."],"attune":"erfordert Einstimmung"},
  {"id":"ring-der-elementar-herrschaft","name":"Ring der Elementar-Herrschaft","type":"Ring","rarity":"legendär","desc":["Dieser Ring ist mit einer der vier Elementarebenen verbunden. Der SL wählt die verbundene Ebene aus oder bestimmt sie zufällig.","Während du diesen Ring trägst, bist du bei Angriffswürfen gegen Elementare von der verbundenen Ebene im Vorteil, und die Elementare sind bei Angriffswürfen gegen dich im Nachteil. Außerdem kannst du je nach verbundener Ebene bestimmte Eigenschaften nutzen.","Der Ring hat fünf Ladungen. Er erhält täglich im Morgengrauen 1W4+1 verbrauchte Ladungen zurück Mit dem Ring gewirkte Zauber haben einen Rettungswurf-SG von 17.","Ring der Erdelementar-Herrschaft: Du kannst zwei Ladungen des Rings verbrauchen, um Monster beherrschen auf einen Erdelementar zu wirken. Außerdem kannst du dich über schwieriges Gelände aus Geröll, Steinen oder Erde bewegen, als wäre es normales Gelände. Weiterhin sprichst und verstehst du Terral.","Wenn du hilfst, einen Erdelementar zu töten, während du auf den Ring eingestimmt bist, erhältst du außerdem die folgenden zusätzlichen Eigenschaften:","Ring der Feuereiementar-Herrschaft: Du kannst zwei Ladungen des Rings verbrauchen, um Monster beherrschen auf einen Feuerelementar zu wirken. Außerdem bist du gegen Feuerschaden resistent. Weiterhin sprichst und verstehst du Ignal.","Wenn du hilfst, einen Feuerelementar zu töten, während du auf den Ring eingestimmt bist, erhältst du außerdem die folgenden zusätzlichen Eigenschaften:","Ring der Luftelementar-Herrschaft: Du kannst zwei Ladungen des Rings verbrauchen, um Monster beherrschen auf einen Luftelementar zu wirken. Wenn du fällst, sinkst du außerdem mit einer Geschwindigkeit von 18 Metern pro Runde und erleidest keinen Fallschaden. Weiterhin sprichst und verstehst du Aural.","Wenn du hilfst, einen Luftelementar zu töten, während du auf den Ring eingestimmt bist, erhältst du außerdem die folgenden zusätzlichen Eigenschaften:","Ring der Wassereiementar-Herrschaft:","Du kannst zwei Ladungen des Rings verbrauchen, um Monster beherrschen auf einen Wasserelementar zu wirken. Außerdem kannst du auf flüssigen Oberflächen stehen und gehen, als wären sie fester Boden. Weiterhin sprichst und verstehst du Aqual.","Wenn du hilfst, einen Wasserelementar zu töten, während du auf den Ring eingestimmt bist, erhältst du außerdem die folgenden zusätzlichen Eigenschaften:"],"attune":"erfordert Einstimmung"},
  {"id":"ring-der-gedankenabschirmung","name":"Ring der Gedankenabschirmung","type":"Ring","rarity":"ungewöhnlich","desc":["Wenn du diesen Ring trägst, bist du gegen Magie immun, die es anderen Kreaturen ermöglicht, deine Gedanken zu lesen, zu erkennen, ob du die Wahrheit sagst oder deine Gesinnung oder deinen Kreaturentyp zu erfahren. Kreaturen können nur telepathisch mit dir kommunizieren, wenn du es erlaubst.","Du kannst den Ring als Aktion unsichtbar werden lassen. Er bleibt unsichtbar, bis du eine weitere Aktion verwendest, um ihn wieder sichtbar werden zu lassen, bis du ihn abnimmst oder bis du stirbst.","Wenn du stirbst, während du den Ring trägst, geht deine Seele in den Ring über, sofern sich noch keine Seele darin befindet. Du kannst im Ring bleiben oder ins Jenseits reisen. Solange sich deine Seele im Ring befindet, kannst du telepathisch mit jeder Kreatur kommunizieren, die ihn trägt. Der Träger kann diese telepathische Kommunikation nicht unterdrücken."],"attune":"erfordert Einstimmung"},
  {"id":"ring-der-regeneration","name":"Ring der Regeneration","type":"Ring","rarity":"sehr selten","desc":["Wenn du diesen Ring trägst, erhältst du alle zehn Minuten 1W6 Trefferpunkte zurück, sofern du mindestens 1 Trefferpunkt hast. Wenn du ein Körperteil verlierst, lässt der Ring es nachwachsen, sodass es nach 1W6+1 Tagen wieder voll einsatzfähig ist, sofern du während der gesamten Zeit mindestens 1 Trefferpunkt hast."],"attune":"erfordert Einstimmung"},
  {"id":"ring-der-sternschnuppen","name":"Ring der Sternschnuppen","type":"Ring","rarity":"sehr selten","desc":["Wenn du diesen Ring in dämmrigem Licht oder Dunkelheit trägst, kannst du beliebig oft Tanzende Lichter und Licht mit dem Ring wirken. Das Wirken dieser Zauber mithilfe des Rings erfordert eine Aktion.","Der Ring hat sechs Ladungen für die folgenden weiteren Eigenschaften. Der Ring erhält täglich im Morgengrauen 1W6 verbrauchte Ladungen zurück.","Feenfeuer: Du kannst als Aktion eine Ladung verbrauchen, um Feenfeuer mit dem Ring zu wirken.","Kugelblitz: Du kannst als Aktion zwei Ladungen verbrauchen, um einen bis vier Kugelblitze mit einem Durchmesser von einem Meter mit dem Ring zu wirken. Je mehr Kugelblitze du erzeugst, desto weniger Energie hat jeder einzelne Kugelblitz.","Jeder Kugelblitz erscheint an einer freien Stelle im Abstand von bis zu 36 Metern von dir, die du sehen kannst. Die Kugelblitze bleiben bis zu eine Minute lang bestehen, solange du dich konzentrierst (wie bei einem Zauber), Jede Kugel spendet in einem Radius von neun Metern dämmriges Licht.","Als Bonusaktion kannst du jede Kugel um bis zu neun Meter bewegen, sie können sich jedoch nicht weiter als 36 Meter von dir entfernen. Wenn eine Kreatur außer dir selbst sich einer Kugel auf bis zu 1,5 Meter nähert, entlädt sich die Kugel als Blitz auf die Kreatur und verschwindet. Die Kreatur muss einen SG-15-Geschicklichkeitsrettungswurf ausführen. Scheitert der Wurf, erleidet die Kreatur abhängig von der Anzahl der erzeugten Kugeln Blitzschaden.","Sternschnuppen: Du kannst als Aktion eine bis drei Ladungen verbrauchen. Für jede verbrauchte Ladung verschießt der Ring einen Lichtfunken an einen Punkt im Abstand von bis zu 18 Metern von dir, den du sehen kannst. Auf jede Kreatur innerhalb eines Würfels mit einer Kantenlänge von 4,5 Metern, der von diesem Punkt ausgeht, regnen Funken herab, und die Kreaturen müssen einen SG-15-Geschicklichkeitsrettungswurf bestehen. Scheitert der Wurf, erleidet die jeweilige Kreatur 5W4 Feuerschaden, anderenfalls die Hälfte."],"attune":"erfordert nächtliche Einstimmung unter freiem Himmel"},
  {"id":"ring-der-telekinese","name":"Ring der Telekinese","type":"Ring","rarity":"sehr selten","desc":["Wenn du diesen Ring trägst, kannst du mit ihm den Zauber Telekinese beliebig oft wirken. Allerdings kannst du nur Gegenstände als Ziel auswählen, die nicht getragen oder gehalten werden."],"attune":"erfordert Einstimmung"},
  {"id":"ring-der-unsichtbarkeit","name":"Ring der Unsichtbarkeit","type":"Ring","rarity":"legendär","desc":["Wenn du diesen Ring trägst, kannst du als Aktion unsichtbar werden. Alles, was du trägst oder mit dir führst, wird mit dir unsichtbar. Du bleibst unsichtbar, bis der Ring entfernt wird, bis du angreifst oder einen Zauber wirkst oder bis du eine Bonusaktion verwendest, um wieder sichtbar zu werden."],"attune":"erfordert Einstimmung"},
  {"id":"ring-der-waerme","name":"Ring der Wärme","type":"Ring","rarity":"ungewöhnlich","desc":["Wenn du diesen Ring trägst, bist du gegen Kälteschaden resistent. Außerdem kann alles, was du trägst oder hältst, Temperaturen bis zu -45 °C unbeschadet widerstehen."],"attune":"erfordert Einstimmung"},
  {"id":"ring-des-ausweichens","name":"Ring des Ausweichens","type":"Ring","rarity":"selten","desc":["Dieser Ring hat drei Ladungen und erhält täglich im Morgengrauen 1W3 verbrauchte Ladungen zurück Wenn du bei einem Geschicklichkeitsrettungswurf scheiterst, während du diesen Ring trägst, kannst du deine Reaktion verwenden, um eine seiner Ladungen zu verbrauchen und den Rettungswurf stattdessen zu bestehen."],"attune":"erfordert Einstimmung"},
  {"id":"ring-des-federfalls","name":"Ring des Federfalls","type":"Ring","rarity":"selten","desc":["Wenn du fällst, während du diesen Ring trägst, sinkst du mit einer Geschwindigkeit von 18 Metern pro Runde und erleidest keinen Fallschaden."],"attune":"erfordert Einstimmung"},
  {"id":"ring-des-roentgenblicks","name":"Ring des Röntgenblicks","type":"Ring","rarity":"selten","desc":["Wenn du diesen Ring trägst, kannst als Aktion sein Befehlswort aussprechen. Wenn du das tust, kannst du eine Minute lang in feste Stoffe hinein- und durch sie hindurchsehen. Der Radius des Röntgenblicks beträgt neun Meter. Für dich wirken feste Gegenstände innerhalb dieses Radius durchsichtig, und Licht kann durch sie hindurchdringen. Der Röntgenblick durchdringt 30 Zentimeter Stein, 2,5 Zentimeter gewöhnliches Metall oder einen Meter Holz oder Erde. Dickere Substanzen oder auch eine dünne Bleischichtblockieren die Sicht.","Wenn du den Ring erneut verwendest, bevor du eine lange Rast einlegst, musst du einen SG-15-Konstitutionsrettungswurf bestehen. Andernfalls erhältst du eine Erschöpfungsstufe."],"attune":"erfordert Einstimmung"},
  {"id":"ring-des-schutzes","name":"Ring des Schutzes","type":"Ring","rarity":"selten","desc":["Wenn du diesen Ring trägst, erhältst du einen Bonus von +1 auf deine RK und Rettungswürfe."],"attune":"erfordert Einstimmung"},
  {"id":"ring-des-schwimmens","name":"Ring des Schwimmens","type":"Ring","rarity":"ungewöhnlich","desc":["Wenn du diesen Ring trägst, hast du eine Schwimmbewegungsrate von zwölf Metern."]},
  {"id":"ring-des-springens","name":"Ring des Springens","type":"Ring","rarity":"ungewöhnlich","desc":["Wenn du diesen Ring trägst, kannst du mit ihm den Zauber Springen beliebig oft als Bonusaktion wirken. Allerdings kannst du nur dich als Ziel bestimmen, wenn du das tust."],"attune":"erfordert Einstimmung"},
  {"id":"ring-des-tierumgangs","name":"Ring des Tierumgangs","type":"Ring","rarity":"selten","desc":["Dieser Ring hat drei Ladungen und erhält täglich im Morgengrauen 1W3 verbrauchte Ladungen zurück. Wenn du diesen Ring trägst, kannst du als Aktion eine seiner Ladungen verbrauchen, um einen der folgenden Zauber zu wirken:"]},
  {"id":"ring-des-wasserlaufens","name":"Ring des Wasserlaufens","type":"Ring","rarity":"ungewöhnlich","desc":["Während du diesen Ring trägst, kannst du auf flüssigen Oberflächen stehen und gehen, als wären sie fester Boden."]},
  {"id":"ring-des-widders","name":"Ring des Widders","type":"Ring","rarity":"selten","desc":["Dieser Ring hat drei Ladungen und erhält täglich im Morgengrauen 1W3 verbrauchte Ladungen zurück. Wenn du diesen Ring trägst, kannst du eine Aktion verwenden, um eine bis drei Ladungen zu verbrauchen und eine Kreatur anzugreifen, die du im Abstand von bis zu 18 Metern von dir sehen kannst. Der Ring erzeugt einen geisterhaften Widderkopf, der einen Angriffswurf mit einem Bonus von +7 ausführt. Bei einem Treffer erleidet das Ziel für jede verbrauchte Ladung 2W10 Energieschaden und wird 1,5 Meter von dir weggestoßen.","Alternativ kannst du als Aktion eine bis drei Ladungen des Rings verbrauchen, um zu versuchen, einen Gegenstand im Abstand von bis zu 18 Metern von dir zu zerstören, den du sehen kannst und der weder getragen noch gehalten wird. Der Ring führt für jede Ladung, die du verbrauchst, einen Stärkewurf mit einem Bonus von +5 aus."],"attune":"erfordert Einstimmung"},
  {"id":"ring-des-widerstands","name":"Ring des Widerstands","type":"Ring","rarity":"selten","desc":["Wenn du diesen Ring trägst, bist du gegen eine Schadensart resistent. Die Schadensart wird vom SL ausgewählt oder zufällig bestimmt und ist durch den Edelstein erkennbar, der den Ring ziert."],"attune":"erfordert Einstimmung"},
  {"id":"ring-des-zauberspeichers","name":"Ring des Zauberspeichers","type":"Ring","rarity":"selten","desc":["Dieser Ring speichert Zauber, die in ihn gewirkt werden, bis der eingestimmte Träger des Rings sie verwendet. Der Ring kann Zauber von bis zu fünf Zaubergraden aufnehmen. Wenn er gefunden wird, enthält er 1W6-1 Zaubergrade in Form von Zaubern, die der SL bestimmt.","Jede Kr eatur kann einen Zauber des 1. bis 5. Grades in den Ring wirken, indem sie den Ring berührt, während sie den Zauber wirkt. Der Zauber hat keinen Effekt und wird nur in dem Ring gespeichert. Wenn der Ring den Zauber nicht aufhehmen kann, wird der Zauber wirkungslos verbraucht. Der beim Wirken verwendete Zaubergrad bestimmt, wie viel Platz der Zauber im Stein verbraucht.","Wenn du diesen Ring trägst, kannst du als Aktion einen beliebigen darin gespeicherten Zauber wirken. Der Zauber verwendet den Zaubergrad, den Zauberrettungswurf-SG, den Bonus für Zauberangriffe und das Attribut zum Zauberwirken des ursprünglichen Zauberwirkers, wird aber in jeder anderen Form behandelt, als hättest du den Zauber gewirkt. Der aus dem Ring gewirkte Zauber ist dann nicht mehr im Ring gespeichert und gibt seinen Platz frei."],"attune":"erfordert Einstimmung"},
  {"id":"ring-des-zauberwendens","name":"Ring des Zauberwendens","type":"Ring","rarity":"legendär","desc":["Während du diesen Ring trägst, bist du bei Rettungswürfen gegen Zauber, die nur dich (und keinen Wirkungsbereich) zum Ziel haben, im Vorteil. Wenn du außerdem eine 20 für den Rettungswurf würfelst und der Zauber ein Zauber des maximal 7. Grades ist, hat der Zauber keinen Effekt auf dich. Stattdessen zielt der Zauber auf den Zauberwirker und verwendet dabei den Zaubergrad, den Zauberrettungswurf-SG, den Bonus für Zauberangriffe und das Attribut zum Zauberwirken des Zauberwirkers."],"attune":"erfordert Einstimmung"},
  {"id":"ritterruestung-der-koerperlosigkeit","name":"Ritterrüstung der Körperlosigkeit","type":"Rüstung (Ritterrüstung)","rarity":"legendär","desc":["Wenn du dieser Rüstung trägst, kannst du als Aktion ihr Befehlswort aussprechen, um den Effekt des Zaubers Körperlosigkeit zu erhalten. Dieser dauert zehn Minuten an oder bis du die Rüstung ablegst oder als Aktion das Befehlswort nochmals sprichst. Diese Eigenschaft der Rüstung kann erst im nächsten Morgengrauen wiederverwendet werden."],"attune":"Ritterrüstung"},
  {"id":"robe-der-augen","name":"Robe der Augen","type":"Wundersamer Gegenstand","rarity":"selten","desc":["Diese Robe ist mit augenartigen Mustern verziert. Wenn du diese Robe trägst, erhältst du die folgenden Vorteile:","Die Augen auf der Robe können nicht geschlossen oder abgewendet werden. Du kannst zwar deine eigenen Augen schließen oder abwenden, doch wenn du diese Robe trägst, gelten deine Augen nie als geschlossen oder abgewendet.","Wenn der Zauber Licht auf die Robe oder der Zauber Tageslicht im Abstand von bis zu 1,5 Metern von der Robe gewirkt wird, bist du eine Minute lang blind. Du kannst am Ende jedes deiner Züge einen Konstitutionsrettungswurf (SG 11 für Licht oder SG 15 für Tageslicht) ausführen und die Blindheit bei einem Erfolg beenden."],"attune":"erfordert Einstimmung"},
  {"id":"robe-der-nuetzlichen-dinge","name":"Robe der nützlichen Dinge","type":"Wundersamer Gegenstand","rarity":"ungewöhnlich","desc":["Diese Robe ist mit Flicken verschiedener Farben und Formen bedeckt. Wenn du die Robe trägst, kannst du als Aktion einen der Flicken abreißen. Der Flicken wird dann zu dem Gegenstand oder der Kreatur, den oder die er darstellt. Nachdem der letzte Flicken entfernt wurde, ist die Robe ein gewöhnliches Kleidungsstück.","Die Robe hat jeweils zwei der folgenden Flicken:","Außerdem hat die Robe 4W4 andere Flicken. Der SL wählt die Flicken aus oder bestimmt sie zufällig."]},
  {"id":"robe-der-schillernden-farben","name":"Robe der schillernden Farben","type":"Wundersamer Gegenstand","rarity":"sehr selten","desc":["Diese Robe hat drei Ladungen und erhält täglich im Morgengrauen 1W3 verbrauchte Ladungen zurück. Wenn du sie trägst, kannst du eine Aktion verwenden und eine Ladung verbrauchen. Daraufhin stellt die Robe bis zum Ende deines nächsten Zugs ein wechselndes Muster aus schillernden Farben zur Schau. In diesem Zeitraum spendet die Robe im Radius von neun Metern helles Licht und im Radius von weiteren neun Metern dämmriges Licht Kreaturen, die dich sehen können, sind bei Angriffswürfen gegen dich im Nachteil. Außerdem muss jede Kreatur im hellen Licht, die dich sehen kann, wenn der Effekt der Robe aktiviert wird, einen SG-15-Weisheitsrettungswurf bestehen. Andernfalls ist die jeweilige Kreatur betäubt, bis der Effekt endet."],"attune":"erfordert Einstimmung"},
  {"id":"robe-der-sterne","name":"Robe der Sterne","type":"Wundersamer Gegenstand","rarity":"sehr selten","desc":["Diese schwarze oder dunkelblaue Robe ist mit kleinen weißen oder silbernen Sternen bestickt. Wenn du sie trägst, erhältst du einen Bonus von +1 auf deine Rettungswürfe.","Sechs Sterne im oberen Bereich der Vorderseite der Robe sind besonders groß. Wenn du diese Robe trägst, kannst du als Aktion einen der Sterne abreißen und damit den Zauber Magisches Geschoss als Zauber des 5. Grades zu wirken. In der Abenddämmerung erscheinen täglich 1W6 entfernte Sterne erneut auf der Robe.","Wenn du die Robe trägst, kannst du als Aktion mit allem, was du trägst oder hältst, die Astralebene betreten. Du bleibst dort, bis du eine Aktion verwendest, um zu deiner Ausgangsebene zurückzukehren. Du erscheinst wieder an der Stelle, an der du zuletzt warst, oder an der nächstgelegenen freien Stelle, falls dieser Ort besetzt ist."],"attune":"erfordert Einstimmung"},
  {"id":"robe-des-erzmagiers","name":"Robe des Erzmagiers","type":"Wundersamer Gegenstand","rarity":"legendär","desc":["Diese elegante Robe ist aus exquisitem weißen, grauen oder schwarzen Stoff gefertigt und mit silberfarbenen Runen verziert. Die Farbe der Robe entspricht der Gesinnung, für die der Gegenstand erschaffen wurde. Eine weiße Robe ist für gute, eine graue Robe für neutrale und eine schwarze Robe für böse Charaktere. Du kannst dich nicht auf eine Robe des Erzmagiers einstimmen, die nicht deiner Gesinnung entspricht.","Wenn du die Robe trägst, erhältst du die folgenden Vorteile:"],"attune":"erfordert Einstimmung durch einen Hexenmeister, Magier oder Zauberer"},
  {"id":"ruestung-der-unverwundbarkeit","name":"Rüstung der Unverwundbarkeit","type":"Rüstung (Ritterrüstung)","rarity":"legendär","desc":["Wenn du diese Rüstung trägst, bist du gegen nichtmagischen Schaden resistent Außerdem kannst du dich als Aktion zehn Minuten lang - oder bis du die Rüstung nicht mehr trägst - gegen nichtmagischen Schaden immun machen. Sobald du diese besondere Aktion verwendet hast, kannst du sie bis zum nächsten Morgengrauen nicht mehr verwenden."],"attune":"Ritterrüstung"},
  {"id":"ruestung-der-verwundbarkeit","name":"Rüstung der Verwundbarkeit","type":"Rüstung (Ritterrüstung)","rarity":"selten","desc":["Wenn du diese Rüstung trägst, bist du gegen eine der folgenden Schadensarten resistent: Hieb, Stich oder Wucht. Der SL wählt die Schadensart aus oder bestimmt sie zufällig.","Fluch: Diese Rüstung ist verflucht. Dies wird erst offenbar, wenn der Zauber Identifizieren auf sie gewirkt wird oder du dich auf sie einstimmst. Durch Einstimmen auf die Rüstung wirkt der Fluch, bis der Zauber Fluch brechen oder ähnliche Magie auf dich gewirkt wird. Das Ablegen der Rüstung beendet den Fluch nicht. Wenn du verflucht bist, bist du anfällig für zwei der drei Schadensarten, die mit dieser Rüstung verknüpft sind (nicht für diejenige, gegen die sie resistent macht),"],"attune":"Ritterrüstung"},
  {"id":"ruestung-des-widerstands","name":"Rüstung des Widerstands","type":"Rüstung (leicht","rarity":"selten","desc":["Wenn du diese Rüstung trägst, bist du gegen eine Schadensart resistent. Der SL wählt anhand der Optionen unten die Schadensart aus oder bestimmt sie zufällig."],"attune":"leicht, mittelschwer oder schwer"},
  {"id":"ruestung-1-2-oder-3","name":"Rüstung, +1, +2 oder +3","type":"Rüstung (leicht","rarity":"selten (+1), sehr selten (+2) oder legendär (+3)","desc":["Wenn du diese Rüstung trägst, erhältst du einen Bonus auf deine RK. Der Bonus wird durch ihre Seltenheit bestimmt."],"attune":"leicht, mittelschwer oder schwer"},
  {"id":"schale-der-wasserelementar-herrschaft","name":"Schale der Wasserelementar-Herrschaft","type":"Wundersamer Gegenstand","rarity":"selten","desc":["Wenn diese Schale mit Wasser gefüllt ist, kannst du als Aktion das Befehlswort für die Schale aussprechen und einen Wasserelementar beschwören, als hättest du den Zauber Elementar beschwören gewirkt.","Die Schale kann erst im nächsten Morgengrauen wieder auf diese Weise verwendet werden.","Die Schale misst ungefähr 30 Zentimeter im Durchmesser und ist halb so tief. Sie wiegt 1,5 Kilogramm und fasst etwa 12 Liter."]},
  {"id":"schicksalskarten","name":"Schicksalskarten","type":"Wundersamer Gegenstand","rarity":"legendär","desc":["Dieser Satz Karten ist meist in einer Schatulle oder einem Beutel zu finden. Die Karten sind aus Elfenbein oder Pergament gefertigt. Meistens -in 75 Prozent der Fälle - enthalten diese Sätze nur 13 Karten. In allen anderen Fällen sind es 22 Karten.","Bevor du eine Karte ziehst, musst du ansagen, wie viele Karten du ziehen möchtest und sie dann zufällig ziehen (du kannst angepasste Spielkarten verwenden). Karten, die über die angesagte Anzahl hinaus gezogen werden, haben keinen Effekt. Anderenfalls wirkt ihre Magie, sobald eine Karte gezogen wurde. Zwischen dem Ziehen jeder Karte darf nicht mehr als eine Stunde Zeit vergehen. Wenn du nicht die angesagte Anzahl an Karten ziehst, fliegen die übrigen Karten von selbst aus dem Stapel und entfalten ihre Effekte auf einmal.","Sobald eine Karte gezogen wurde, hört sie auf zu existieren. Sofern es sich nicht um den Narren oder den Hofnarren handelt, erscheint die Karte wieder im Ziehstapel, sodass dieselbe Karte zweimal gezogen werden kann.","*Nur in Versionen mit 22 Karten","Balance: Dein Geist erfährt einen qualvollen Wandel, der deine Gesinnung ändert. Rechtschaffen wird chaotisch, gut wird böse und umgekehrt. Wenn du vollständig neutral oder gesinnungslos bist, hat diese Karte keinen Effekt.","Die Leere: Diese schwarze Karte bedeutet ein furchtbares Unheil. Deine Seele wird deinem Körper entrissen, in einen Gegenstand gesperrt und an einem Ort verborgen, den der SL bestimmt. Mindestens ein mächtiges Wesen bewacht den Ort. Während deine Seele auf diese Weise gefangen ist, ist dein Körper kampfunfähig. Der Zauber Wunsch kann deine Seele zwar nicht zurückholen, enthüllt aber den Ort, an dem der Gegenstand mit deiner Seele sich befindet. Du ziehst keine Karten mehr.","Die Schicksale: Die Realität gerät aus den Fugen und wird neu zusammengesetzt. Du kannst ein Ereignis vermeiden oder löschen, als wäre es niemals passiert Du kannst die Magie der Karte sofort nach dem Ziehen nutzen oder zu jedem anderen Zeitpunkt, bevor du stirbst.","Edelstein: 25 Schmuckstücke im Wert von jeweils 2.000 GM oder 50 Edelsteine im Wert von jeweils 1.000 GM erscheinen zu deinen Füßen.","Euryale: Das medusenähnliche Antlitz auf dieser Karte verflucht dich. Du erhältst einen Malus von -2 auf Rettungswürfe, während du auf diese Weise verflucht bist. Nur ein Gott oder die Magie der Karte 'Die Schicksale' kann diesen Fluch aufheben.","Flammen: Ein mächtiger Teufel wird dein Feind. Der Teufel trachtet nach deinem Untergang und sucht dich heim. Er genießt dein Leiden, bevor er schließlich versucht, dich zu töten. Diese Feindschaft dauert an, bis du stirbst oder der Teufel tot ist.","Hofnarr: Du erhältst 10.000 EP dazu, oder du kannst über deine angesagten Züge hinaus zwei weitere Karte ziehen.","Idiot: Dein Intelligenzwert wird permanent um 1W4+1 (auf einen Mindestwert von 1) reduziert. Du kannst über deine angesagten Züge hinaus eine weitere Karte ziehen.","Komet: Wenn du das nächste feindlich gesinnte Monster oder die nächste feindlich gesinnte Monstergruppe allein besiegst, erhältst du genug Erfahrungspunkte, um eine Stufe aufzusteigen. Anderenfalls hat diese Karte keinen Effekt.","Krallen: Jeder magische Gegenstand, den du trägst oder mitführst, zerfällt. Artefakte in deinem Besitz werden nicht zerstört, aber verschwinden.","Mond: Du kannst lW3-mal den Zauber Wunsch wirken.","Narr: Du verlierst 10.000 EP, wirfst diese Karte ab und ziehst erneut vom Stapel. Beide Ziehereignisse zählen zusammen als einer deiner angesagten Züge. Wenn der Verlust von so vielen EP dazu führen würde, dass du eine Stufe absteigst, verlierst du stattdessen so viele EP, dass du gerade so deine Stufe behältst.","Ritter: Ein Kämpfer der 4. Stufe erscheint in einem von dir bestimmten Bereich im Abstand von bis zu neun Metern von dir und steht dir zu Diensten. Der Kämpfer gehört demselben Volk an wie du und dient dir treu bis zu seinem Tod, da er oder sie glaubt, dass das Schicksal euch zusammengeführt hat. Du kontrollierst diesen Charakter.","Ruin: Mit Ausnahme von magischen Gegenständen verlierst du alle Reichtümer, die du bei dir trägst oder besitzt. Bewegliches Eigentum verschwindet. Geschäfte, Gebäude und Grundstücke, die du besitzt, gehen auf eine Weise verloren, die die Realität am wenigsten verändert. Dokumente, die beweisen, dass du etwas besitzen solltest, das du durch diese Karte verloren hast, verschwinden ebenfalls.","Schlüssel: Eine seltene oder seltenere magische Waffe, im Umgang mit welcher du geübt bist, erscheint in deinen Händen. Der SL wählt die Waffe aus.","Schurke: Ein Nichtspielercharakter, den der SL bestimmt, ist dir gegenüber ab sofort feindlich gesinnt Du weißt nicht, wer dein neuer Gegner ist, bis der NSC oder jemand anderes es enthüllt. Abgesehen vom Zauber Wunsch oder einer Göttlichen Intervention kann nichts die Feindseligkeit des NSCs gegen dich aufheben.","Sonne: Du erhältst 50.000 EP und ein wundersamer Gegenstand, den der SL zufällig bestimmt, erscheint in deinen Händen.","Stern: Erhöhe einen deiner Attributswerte um 2. Der Wert kann größer als 20, aber nicht größer als 24 sein.","Thron: Du bist in der Fertigkeit Überzeugen geübt und verdoppelst deinen Übungsbonus bei Würfen, die diese Fertigkeit verwenden. Außerdem erhältst du die Besitzrechte an einem kleinen Bergfried irgendwo auf der Welt Allerdings ist der Bergfried momentan in Monsterhand. Du musst ihn von den Monstern befreien, bevor du deinen Anspruch geltend machen kannst","Totenschädel: Du beschwörst einen Avatar des Todes - ein gespenstisches humanoides Skelett in einem zerfetzten schwarzen Gewand, das eine geisterhafte Sense schwingt. Er erscheint im Abstand von bis zu drei Metern von dir an einer Stelle, die der SL bestimmt und greift dich an. Dabei warnt er dich und alle anderen, dass du diesen Kampf allein gewinnen musst Der Avatar kämpft, bis du stirbst oder seine Trefferpunkte auf 0 sinken, woraufhin er verschwindet Wenn jemand versucht, dir zu helfen, beschwört der Helfer seinen eigenen Avatar des Todes. Eine Kreatur, die von einem Avatar des Todes getötet wurde, kann nicht wiederbelebt werden."]},
  {"id":"schild-der-geschossanziehung","name":"Schild der Geschossanziehung","type":"Rüstung (Schild)","rarity":"selten","desc":["Wenn du diesen Schild hältst, bist du gegen Schaden durch Fernkampfwaffenangriffe resistent.","Fluch: Dieser Schild ist verflucht. Durch Einstimmen wirkt der Fluch, bis der Zauber Fluch brechen oder ähnliche Magie gewirkt wird. Das Ablegen des Schilds beendet den Fluch nicht. Wenn ein Fernkampfwaffenangriff gegen ein Ziel im Abstand von bis zu drei Metern von dir ausgeführt wird, macht der Fluch stattdessen dich zum Ziel."],"attune":"Schild"},
  {"id":"schild-1-2-oder-3","name":"Schild, +1, +2 oder +3","type":"Rüstung (Schild)","rarity":"ungewöhnlich (+1 ), selten (+2) oder sehr selten (+3)","desc":["Wenn du diesen Schild hältst, erhältst du einen Bonus auf deine RK, der von der Seltenheit des Schilds bestimmt wird. Dieser Bonus des Schildes wirkt zusätzlich zu seinem normalen Bonus auf die RK."],"attune":"Schild"},
  {"id":"schuhe-des-spinnenkletterns","name":"Schuhe des Spinnenkletterns","type":"Wundersamer Gegenstand","rarity":"ungewöhnlich","desc":["Wenn du diese leichten Schuhe trägst, kannst du dich an vertikalen Oberflächen sowie kopfüber an Decken frei bewegen, wobei du die Hände frei hast. Deine Kletterbewegungsrate entspricht deiner Schrittbewegungsrate. Allerdings erlauben die Schuhe es dir nicht, dich normal auf rutschigen Oberflächen zu bewegen, die zum Beispiel mit Eis oder Öl bedeckt sind."],"attune":"erfordert Einstimmung"},
  {"id":"schwert-der-schaerfe","name":"Schwert der Schärfe","type":"Waffe (beliebiges Schwert","rarity":"sehr selten","desc":["Wenn du einen Gegenstand mit diesem magischen Schwert angreifst und triffst, verursachst du den durch die Schadenswürfel der Waffe maximal möglichen Schaden beim Ziel.","Wenn du eine Kreatur mit dieser Waffe angreifst und beim Angriffswurf eine 2 0 würfelst, erleidet dieses Ziel zusätzlich 4W6 Hiebschaden. Würfle dann erneut mit einem W20. Wenn du eine 20 würfelst, trennst du eine Gliedmaße des Ziels ab. Der SL bestimmt, welchen Effekt der Verlust dieser Gliedmaße hat. Wenn die Kreatur keine Gliedmaßen hat, die abgetrennt werden könnten, schneidest du stattdessen ein Stück von ihrem Körper ab.","Außerdem kannst du das Befehlswort des Schwerts aussprechen. Daraufhin spendet die Klinge im Radius von drei Metern helles Licht und im Radius von weiteren drei Metern dämmriges Licht. Wenn das Befehlswort erneut ausgesprochen oder das Schwert eingesteckt wird, erlischt das Licht."],"attune":"beliebiges Schwert, das Hiebschaden verursacht"},
  {"id":"schwert-der-verwundung","name":"Schwert der Verwundung","type":"Waffe (beliebiges Schwert)","rarity":"selten","desc":["Durch den Schaden dieser Waffe verlorene Trefferpunkte können nur durch eine kurze oder lange Rast und nicht durch Regeneration, Magie oder andere Methoden zurückerhalten werden.","Wenn du eine Kreatur mit einem Angriff mit dieser magischen Waffe triffst, kannst du das Ziel einmal pro Zug verwunden. Zu Beginn jedes Zugs der verwundeten Kreatur erleidet diese 1W4 nekrotischen Schaden für jedes einzelne Wunde, die du ihr zugefügt hast. Dann kann sie einen SG-15-Konstitutionsrettungswurf ausführen. Bei einem Erfolg endet der Effekt aller auf diese Weise zugefügten Wunden. Alternativ kann die verwundete Kreatur oder eine Kreatur im Abstand von bis zu 1,5 Metern von ihr als Aktion einen SG-15-Weisheitswurf (Heilkunde) ausführen und den Effekt solcher Wunden bei einem Erfolg beenden."],"attune":"beliebiges Schwert"},
  {"id":"schwert-des-lebensentzugs","name":"Schwert des Lebensentzugs","type":"Waffe (beliebiges Schwert)","rarity":"selten","desc":["Wenn du eine Kreatur mit dieser magischen Waffe angreifst und beim Angriffswurf eine 20 würfelst, erleidet dieses Ziel zusätzlich 3W6 nekrotischen Schaden, sofern das Ziel kein Konstrukt oder Untoter ist. Du erhältst temporäre Trefferpunkte in Höhe des zusätzlich verursachten Schadens."],"attune":"beliebiges Schwert"},
  {"id":"schwurbogen","name":"Schwurbogen","type":"Waffe (Langbogen)","rarity":"sehr selten","desc":["Wenn du einen Pfeil in diesen Bogen einlegst, flüstert es 'Meinen Gegnern einen raschen Tod!' auf Elfisch. Wenn du einen Fernkampfangriff mit dieser Waffe ausführst, kannst du die folgende Befehlswendung aussprechen: 'Möge dein Tod rasch sein, Übeltäter!' Das Ziel deines Angriffs wird dein Erzfeind, bis es stirbt oder bis zum Morgengrauen sieben Tage später. Du kannst nur einen solchen Erzfeind gleichzeitig haben. Wenn dein Erzfeind stirbt, kannst du erst nach dem nächsten Morgengrauen einen neuen wählen.","Wenn du mit dieser Waffe einen Fernkampfangriff gegen deinen Erzfeind ausführst, bist du bei dem Wurf im Vorteil. Außerdem kann dein Ziel von keiner Form von Deckung außer vollständiger Deckung profitieren, und du bist aus der Maximalreichweite nicht im Nachteil. Wenn der Angriff trifft, erleidet dein Erzfeind zusätzlich 3W6 Stichschaden.","Solange dein Erzfeind lebt, bist du bei Angriffswürfen mit allen anderen Waffen im Nachteil."],"attune":"Langbogen"},
  {"id":"seelenspiegel","name":"Seelenspiegel","type":"Wundersamer Gegenstand","rarity":"sehr selten","desc":["Wenn man diesen 1,2 Meter hohen Spiegel indirekt betrachtet, sind blasse Abbilder von Kreaturen darin zu erkennen. Der Spiegel wiegt 25 Kilogramm, besitzt eine RK von 11,10 Trefferpunkte und ist anfällig für Wuchtschaden. Er zersplittert und ist zerstört, wenn seine Trefferpunkte auf 0 sinken.","Wenn der Spiegel an einer senkrechten Fläche hängt und du dich im Abstand von bis zu 1,5 Metern von ihm befindest, kannst du als Aktion sein Befehlswort aussprechen und ihn aktivieren. Er bleibt aktiviert, bis du eine Aktion verwendest, um das Befehlswort wieder auszusprechen.","Jede Kreatur außer dir, die sich im Abstand von bis zu neun Metern vom aktivierten Spiegel befindet und ihr Spiegelbild darin sieht, muss einen SG-15-Charismarettungswurf bestehen. Scheitert der Rettungswurf, wird sie mit allem, was sie trägt oder mitführt in einer der zwölf extradimensionalen Zellen des Spiegels gefangen. Bei diesem Rettungswurf ist die Kreatur im Vorteil, wenn sie das Wesen des Spiegels kennt. Konstrukte bestehen den Rettungswurf automatisch.","Eine extradimensionale Zelle ist eine unendliche Weite, die mit dichtem Nebel gefüllt ist. Dieser reduziert die Sichtweite auf drei Meter. In den Zellen des Spiegels gefangene Kreaturen altern nicht und müssen nicht essen, trinken oder schlafen. Eine in einer Zelle gefangene Kreatur kann mithilfe von Magie entkommen, die Ebenenreisen erlaubt Anderenfalls ist die Kreatur in der Zelle gefangen, bis sie befreit wird.","Wenn der Spiegel eine Kreatur einfängt, während seine zwölf Zellen bereits besetzt sind, befreit der Spiegel eine zufällige gefangene Kreatur, um den neuen Gefangenen aufzunehmen. Eine befreite Kr eatur erscheint an einer freien Stelle in Sichtweite des Spiegels, ist jedoch von ihm abgewandt. Wenn der Spiegel zerstört wird, werden alle Kreaturen daraus befr eit und erscheinen an freien Stellen in seiner Nähe.","Wenn du dich im Abstand von bis zu 1,5 Meter vom Spiegel befindest, kannst du als Aktion den Namen einer darin gefangenen Kreatur aussprechen oder eine bestimmte Zellnummer nennen. Die benannte oder in der angegebenen Zelle enthaltene Kreatur erscheint als Abbild auf der Oberfläche des Spiegels. Du kannst normal mit der Kreatur kommunizieren.","Ebenso kannst du als Aktion ein zweites Befehlswort aussprechen und eine im Spiegel gefangene Kreatur befreien. Die befreite Kreatur erscheint mit all ihren Eigentümern an der dem Spiegel nächsten freien Stelle und ist vom Spiegel abgewandt."]},
  {"id":"seil-des-kletterns","name":"Seil des Kletterns","type":"Wundersamer Gegenstand","rarity":"ungewöhnlich","desc":["Dieses 18 Meter lange Seidenseil wiegt 1,5 Kilogramm und kann bis zu 1.500 Kilogramm Last halten.","Wenn du ein Ende des Seils festhältst und als Aktion das Befehlswort aussprichst, erwacht das Seil zum Leben. Du kannst dem anderen Ende als Bonusaktion befehlen, sich auf ein Ziel deiner Wahl zuzubewegen. Wenn du ihm in deinem Zug den Befehl gibst, bewegt sich jenes Seilende drei Meter weit. Dann bewegt es sich in jedem deiner nächsten Züge jeweils weitere drei Meter weit, bis es sein Ziel erreicht, die ganze Seillänge aufgebraucht ist oder du ihm befiehlst, anzuhalten. Du kannst dem Seil auch befehlen, sich sicher an einem Gegenstand zu befestigen oder wieder zu lösen, sich zu ver- oder entknoten oder sich aufzurollen, damit du es tragen kannst.","Wenn du dem Seil befiehlst, sich zu verknoten, erscheinen alle 30 Zentimeter große Knoten am Seil. Wenn es verknotet ist, ist das Seil nur 15 Meter lang und verleiht dir bei Würfen, die du ausführst, um an ihm hochzuklettern, einen Vorteil.","Das Seil besitzt eine RK von 20 und 20 Trefferpunkte. Es erhält alle fünf Minuten 1 Trefferpunkt zurück, solange es noch mindestens 1 Trefferpunkt hat. Wenn die Trefferpunkte des Seils auf 0 sinken, ist das Seil zerstört."]},
  {"id":"skarabaeus-des-schutzes","name":"Skarabäus des Schutzes","type":"Wundersamer Gegenstand","rarity":"legendär","desc":["Wenn du dieses käferförmige Medaillon eine Runde lang in deiner Hand hältst, erscheint eine Inschrift auf seiner Oberfläche, die seine magische Natur enthüllt Solange du es bei dir trägst, verleiht es dir zwei Vorteile:"],"attune":"erfordert Einstimmung"},
  {"id":"sonnenklinge","name":"Sonnenklinge","type":"Waffe (Langschwert)","rarity":"selten","desc":["Dieser Gegenstand sieht aus wie der Griff eines Langschwerts. Wenn du den Griff hältst, kannst du eine Bonusaktion verwenden, um eine Klinge aus purem Licht erscheinen oder wieder verschwinden zu lassen. Während die Klinge existiert, hat dieses magische Langschwert die Eigenschaft Finesse. Wenn du im Umgang mit Kurzschwertern oder Langschwertern geübt bist, bist du auch im Umgang mit der Sonnenklinge geübt.","Du erhältst einen Bonus von +2 auf Angriffs- und Schadenswürfe mit dieser Waffe, die gleißenden statt Hiebschaden verursacht. Wenn du einen Untoten damit triffst, erleidet diese Kreatur zusätzlich 1W8 gleißenden Schaden.","Die leuchtende Klinge spendet in einem Radius von 4,5 Metern helles Licht und in einem Radius von weiteren 4,5 Metern dämmriges Licht. Das Licht ist Sonnenlicht. Solange die Klinge existiert, kannst du als Aktion den Radius des hellen und dämmrigen Lichts um jeweils 1,5 Meter erweitern oder reduzieren. Der maximale und der minimale Radius betragen jeweils neun Meter."],"attune":"Langschwert"},
  {"id":"sphaere-des-nichts","name":"Sphäre des Nichts","type":"Wundersamer Gegenstand","rarity":"legendär","desc":["Diese schwarze Kugel hat einen Durchmesser von 0,6 Metern. Sie ist ein Loch im Multiversum, das im Raum schwebt und durch ein umgebendes magisches Feld stabilisiert wird.","Die Kugel löscht alle Materie aus, die sie durchdringt oder die von ihr durchdrungen wird. Die einzige Ausnahme sind Artefakte. Sofern sie nicht anfällig für Schaden durch eine Sphäre des Nichts sind, durchdringen sie die Sphäre unbeschädigt. Alles andere, was die Kugel berührt, aber nicht vollständig von ihr umhüllt und ausgelöscht wird, erleidet 4W10 Energieschaden.","Die Sphäre bewegt sich nicht, bis sie jemand kontrolliert. Wenn sich eine von niemandem kontrollierte Sphäre im Abstand von bis zu 18 Metern von dir befindet, kannst du als Aktion einen SG-25-Intelligenzwurf (Arkane Kunde) ausführen. Bei einem Erfolg schwebt die Kugel in eine Richtung deiner Wahl. Die maximale Distanz in Metern entspricht dabei dem 1,5-fachen deines Intelligenzmodifikators (mindestens 1,5 Meter), Anderenfalls bewegt sich die Kugel drei Meter auf dich zu. Wenn die Sphäre in den Bereich einer Kreatur gelangt, muss die Kreatur einen SG-13-Geschicklichkeitsrettungswurf bestehen, oder sie wird von der Sphäre berührt und erleidet 4W10 Energieschaden.","Wenn du versuchst, eine Sphäre zu kontrollieren, die bereits von einer anderen Kreatur kontrolliert wird, führst du einen vergleichenden Intelligenzwurf (Arkane Kunde) gegen den Intelligenzwurf (Arkane Kunde) der anderen Kreatur aus. Der Gewinner des Vergleichs kontrolliert die Sphäre und kann sie normal schweben lassen.","Wenn die Sphäre ein Ebenenportal (wie das durch den Zauber Tor erschaffene) oder einen extradimensionalen Raum (wie den in einem Tragbaren Loch) berührt, entscheidet der SL mithilfe der folgenden Tabelle, was passiert."]},
  {"id":"stab-der-bezauberung","name":"Stab der Bezauberung","type":"Stab","rarity":"selten","desc":["Wenn du diesen Stab hältst, kannst du als Aktion eine seiner zehn Ladungen verbrauchen, um mit ihm Befehl, Person bezaubern oder Sprachen verstehen zu wirken. Verwende dafür deinen Zauberrettungswurf-SG. Der Stab kann auch als magischer Kampfstab verwendet werden.","Wenn du den Stab hältst und bei einem Rettungswurf gegen Verzauberungsmagie scheiterst, die nur dich zum Ziel hat, kannst du deinen gescheiterten Rettungswurf in einen Erfolg umwandeln. Diese Eigenschaft des Stabs kann erst im nächsten Morgengrauen wiederverwendet werden. Wenn du einen Rettungswurf gegen Verzauberungsmagie, die nur dich als Ziel hat, mit oder ohne die Hilfe des Stabs bestehst, kannst du als Reaktion eine Ladung des Stabs verbrauchen, um den Zauber umzukehren und gegen seinen Zauberwirker zu verwenden, als hättest du den Zauber gewirkt.","Der Stab erhält täglich im Morgengrauen 1W8+2 verbrauchte Ladungen zurück. Wenn du die letzte Ladung verbraucht hast, würfle mit einem W20. Bei einer 1 wird der Stab zu einem nichtmagischen Kampfstab."],"attune":"erfordert Einstimmung durch einen Barden, Druiden, Hexenmeister, Kleriker, Magier oder Zauberer"},
  {"id":"stab-der-heilung","name":"Stab der Heilung","type":"Stab","rarity":"selten","desc":["Dieser Stab hat zehn Ladungen. Wenn du ihn hältst, kannst du als Aktion eine oder mehrere Ladungen verbrauchen, um einen der folgenden Zauber mit ihm zu wirken, wobei du deinen Zauberrettungswurf-SG und Zauberwirken-Attributsmodifikator verwendest: Massen-Wunden heilen (fünf Ladungen) Schwache Genesung (zwei Ladungen) oder Wunden heilen (eine Ladung pro Zaubergrad, bis höchstens dem 4. Grad),","Der Stab erhält täglich im Morgengrauen 1W6+4 verbrauchte Ladungen zurück. Wenn du die letzte Ladung verbraucht hast, würfle mit einem W20. Bei einer 1 verschwindet der Stab mit einem Lichtblitz und ist für immer verloren."],"attune":"erfordert Einstimmung durch einen Barden, Druiden oder Kleriker"},
  {"id":"stab-der-insektenschwaerme","name":"Stab der Insektenschwärme","type":"Stab","rarity":"selten","desc":["Dieser Stab hat zehn Ladungen und erhält täglich im Morgengrauen 1W6+4 verbrauchte Ladungen zurück. Wenn du die letzte Ladung verbraucht hast, würfle mit einem W20. Bei einer 1 frisst ein Insektenschwarm den Stab auf und verschwindet dann.","Zauber: Wenn du den Stab hältst, kannst du als Aktion einige seiner Ladungen verbrauchen, um einen der folgenden Zauber mit ihm zu wirken, wobei du deinen Zauberrettungswurf-SG verwendest: Insektenplage (fünf Ladungen) oder Rieseninsekt (vier Ladungen).","Insektenschwarm: Wenn du den Stab hältst, kannst du eine Aktion verwenden und eine Ladung verbrauchen, um einen Schwarm harmloser fliegender Insekten erscheinen zu lassen, die sich im Radius von neun Metern um dich herum ausbreiten. Die Insekten verweilen zehn Minuten lang und bewirken, dass der Bereich für andere Kreaturen als dich komplett verschleiert ist. Der Schwarm bewegt sich mit dir, mit dir als seinem Mittelpunkt. Wind mit einer Geschwindigkeit von mindestens 16 Kilometern pro Stunde vertreibt den Schwarm und beendet den Effekt."],"attune":"erfordert Einstimmung durch einen Barden, Druiden, Hexenmeister, Kleriker, Magier oder Zauberer"},
  {"id":"stab-der-macht","name":"Stab der Macht","type":"Stab","rarity":"sehr selten","desc":["Dieser Stab kann als magischer Kampfstab geführt werden, der einen Bonus von +2 auf Angriffs- und Schadenswürfe verleiht, die du mit ihm ausführst. Wenn du ihn hältst, erhältst du einen Bonus von +2 auf deine Rüstungsklasse, Rettungswürfe und Zauberangriffswürfe.","Der Stab hat 20 Ladungen und die folgenden Eigenschaften. Der Stab erhält täglich im Morgengrauen 2W8+4 verbrauchte Ladungen zurück. Wenn du die letzte Ladung verbraucht hast, würfle mit einem W20. Bei einer 1 behält der Stab seinen Bonus von +2 auf Angriffs- und Schadenswürfe, verliert jedoch all seine anderen Eigenschaften. Bei einer 20 erhält er 1W8+2 Ladungen zurück","Kraftschlag: Wenn du mit dem Stab einen erfolgreichen Nahkampfangriff ausführst, kannst du eine Ladung verbrauchen, um dem Ziel zusätzlich 1W6 Energieschaden zuzufügen.","Zauber: Wenn du diesen Stab hältst, kannst du als Aktion eine oder mehrere Ladungen verbrauchen, um einen der folgenden Zauber zu wirken, wobei du deinen Zauberrettungswurf-SG und Zauberangriffsbonus verwendest Blitz (5. Grad, fünf Ladungen), Energiewand (fünf Ladungen), Feuerball (5. Grad, fünf Ladungen), Kältekegel (fünf Ladungen), Kugel der Unverwundbarkeit (sechs Ladungen), Magisches Geschoss (eine Ladung), Monster festhalten (fünf Ladungen), Schwächestrahl (eine Ladung) oder Schweben (zwei Ladungen).","Vergeltungsschlag: Du kannst den Stab als Aktion über deinem Knie oder an einer harten Oberfläche zerbrechen und einen Vergeltungsschlag ausführen. Der Stab wird zerstört und entlädt seine übrige Magie als Explosion, die sich als Kugel mit einem Radius von neun Metern um den Stab herum ausbreitet","Du hast eine Chance von 50 Prozent, sofort auf eine zufällige Existenzebene transportiert zu werden und der Explosion zu entkommen. Bei einem Fehlschlag entkommst du dem Effekt nicht und erleidest Energieschaden in Höhe des 16-fachen der Ladungen im Stab. Jede andere Kreatur im Bereich muss einen SG-17-GeschicklichkeitsRettungswurf bestehen. Scheitert der Wurf, erleidet eine Kreatur Schaden abhängig von ihrer Entfernung vom Ursprung, wie die folgende Tabelle zeigt. Anderenfalls erleidet eine Kreatur halb so viel Schaden."],"attune":"erfordert Einstimmung durch einen Hexenmeister, Magier oder Zauberer"},
  {"id":"stab-der-python","name":"Stab der Python","type":"Stab","rarity":"ungewöhnlich","desc":["Du kannst als Aktion das Befehlswort dieses Stabs aussprechen und ihn im Abstand von bis zu drei Metern von dir auf den Boden werfen. Der Stab wird zu einer Riesenwürgeschlange unter deiner Kontrolle, die ihre eigene Initiative würfelt. Wenn du eine Bonusaktion verwendest, um das Befehlswort erneut auszusprechen, verwandelst du den Stab wieder in seine normale Gestalt zurück Er erscheint in dem Bereich, den vorher die Schlange besetzt hatte.","Du kannst der Schlange in deinem Zug mentale Befehle erteilen, wenn sie sich im Abstand von bis zu 18 Metern von dir befindet und du nicht kampfunfähig bist. Du entscheidest über die Aktion der Schlange und ihre Bewegung in ihrem nächsten Zug. Alternativ kannst du einen allgemeinen Befehl erteilen und sie beispielsweise deine Feinde angreifen oder einen Ort bewachen lassen.","Wenn die Trefferpunkte der Schlange auf 0 sinken, stirbt sie und verwandelt sich wieder in ihre Stabgestalt Der Stab zerbricht dann und wird zerstört. Wenn die Schlange wieder zu einem Stab wird, bevor sie all ihre Trefferpunkte verliert, erhält sie alle Trefferpunkte zurück."],"attune":"erfordert Einstimmung durch einen Druiden, Hexenmeister oder Kleriker"},
  {"id":"stab-der-verkuemmerung","name":"Stab der Verkümmerung","type":"Stab","rarity":"selten","desc":["Dieser Stab hat drei Ladungen und erhält täglich im Morgengrauen 1W3 verbrauchte Ladungen zurück.","Der Stab kann als magischer Kampfstab verwendet werden. Bei einem Treffer verursacht er Schaden wie ein normaler Kampfstab, und du kannst eine Ladung verbrauchen, um dem Ziel zusätzlich 2W10 nekrotischen Schaden zuzufügen. Außerdem muss das Ziel einen SG-15-Konstitutionsrettungswurf bestehen, oder es ist eine Stunde lang bei allen Attributs- oder Rettungswürfen, die Stärke oder Konstitution verwenden, im Nachteil."],"attune":"erfordert Einstimmung durch einen Druiden, Hexenmeister oder Kleriker"},
  {"id":"stab-der-waldlande","name":"Stab der Waldlande","type":"Stab","rarity":"selten","desc":["Dieser Stab kann als magischer Kampfstab geführt werden, der einen Bonus von +2 auf Angriffs- und Schadenswürfe verleiht, die du mit ihm ausführst. Wenn du ihn hältst, erhältst du einen Bonus von +2 auf Zauberangriffswürfe.","Der Stab hat zehn Ladungen und die folgenden Eigenschaften. Er erhält täglich im Morgengrauen 1W6+4 verbrauchte Ladungen zurück. Wenn du die letzte Ladung verbraucht hast, würfle mit einem W20. Bei einer 1 verliert der Stab seine Eigenschaften und wird zu einem nichtmagischen Kampfstab.","Zauber: Du kannst als Aktion eine oder mehrere Ladungen des Stabs verbrauchen, um einen der folgenden Zauber mit ihm zu wirken, wobei du deinen Zauberrettungswurf-SG verwendest: Dornenwand (sechs Ladungen), Erwecken (fünf Ladungen), Mit Pflanzen sprechen (drei Ladungen), Mit Tieren sprechen (eine Ladung), Rindenhaut (zwei Ladungen), Tiere oder Pflanzen aufspüren (zwei Ladungen) oder Tierfreundschaft (eine Ladung).","Du kannst außerdem eine Aktion verwenden, um den Zauber Spurloses Gehen mit dem Stab zu wirken, ohne Ladungen zu verbrauchen.","Baumgestalt: Du kannst als Aktion ein Ende des Stabs in fruchtbare Erde einpflanzen und eine Ladung verbrauchen, um den Stab in einen gesunden Baum zu verwandeln. Der Baum ist 18 Meter hoch. Sein Stamm hat einen Durchmesser von 1,5 Metern, und die Krone erreicht einen Durchmesser von sechs Metern. Der Baum sieht normal aus, verströmt jedoch eine schwache Aura der Verwandlungsmagie, wenn er das Ziel von Magie entdecken wird. Wenn du den Baum berührst und eine weitere Aktion verwendest, um sein Befehlswort auszusprechen, verwandelst du den Stab wieder in seine normale Gestalt. Kreaturen auf dem Baum fallen herunter, wenn der Baum wieder zu einem Stab wird."],"attune":"erfordert Einstimmung durch einen Druiden"},
  {"id":"stab-des-blitzes-und-donners","name":"Stab des Blitzes und Donners","type":"Stab","rarity":"sehr selten","desc":["Dieser Stab kann als magischer Kampfstab geführt werden, der einen Bonus von +2 auf Angriffs- und Schadenswürfe verleiht, die du mit ihm ausführst. Außerdem hat er die folgenden zusätzlichen Eigenschaften. Wenn eine dieser Eigenschaften verwendet wird, kann sie erst im nächsten Morgengrauen wiederverwendet werden.","Blitz: Wenn du mit dem Stab einen erfolgreichen Nahkampfangriff ausführst, kannst du dem Ziel zusätzlich 2W6 Blitzschaden zufügen.","Schall: Wenn du mit dem Stab einen erfolgreichen Nahkampfangriff ausführst, kannst du den Stab einen lauten Donnerknall ausstoßen lassen, der 90 Meter weit zu hören ist. Das getroffene Ziel muss einen SG-17-Konstitutionsrettungswurf bestehen, oder es ist bis zum Ende deines nächsten Zugs betäubt.","Blitzschlag: Du kannst als Aktion einen Blitzschlag auslösen, der sich von der Spitze des Stabs in einer 1,5 Meter breiten und 36 Meter langen Linie ausbreitet Jede Kreatur in dieser Linie muss einen SG-17-Geschicklichkeitsrettungswurf ausführen. Scheitert der Wurf, erleidet sie 9W6 Blitzschaden, anderenfalls die Hälfte.","Donnerschlag: Du kannst den Stab als Aktion einen betäubenden Donnerschlag ausstoßen lassen, der 180 Meter weit zu hören ist Jede Kreatur (außer dir) im Abstand von bis zu 18 Metern von dir muss einen SG-17-Konstitutionsrettungswurf ausführen. Scheitert der Wurf, erleidet die Kreatur 2W6 Schallschaden und ist eine Minute lang taub. Bei einem erfolgreichen Rettungswurf erleidet die jeweilige Kreatur die Hälfte des Schadens und ist nicht taub.","Blitz und Donner: Du kannst eine Aktion verwenden, um die Eigenschaften Blitz und Donnerschlag gleichzeitig zu verwenden. Dabei verbrauchst du nicht die tägliche Verwendung dieser Eigenschaften, sondern nur die Verwendung dieser Eigenschaft."],"attune":"erfordert Einstimmung"},
  {"id":"stab-des-feuers","name":"Stab des Feuers","type":"Stab","rarity":"sehr selten","desc":["Wenn du diesen Stab hältst, bist du gegen Feuerschaden resistent.","Der Stab hat zehn Ladungen. Wenn du ihn hältst, kannst du als Aktion eine oder mehrere Ladungen verbrauchen, um einen der folgenden Zauber mit ihm zu wirken, wobei du deinen Zauberrettungswurf-SG verwendest: Brennende Hände (eine Ladung), Feuerball (drei Ladungen) oder Feuerwand (vier Ladungen).","Der Stab erhält täglich im Morgengrauen 1W6+4 verbrauchte Ladungen zurück. Wenn du die letzte Ladung verbraucht hast, würfle mit einem W20. Bei einer 1 wird der Stab schwarz, zerfällt zu Asche und ist damit zerstört."],"attune":"erfordert Einstimmung durch einen Druiden, Hexenmeister, Magier oder Zauberer"},
  {"id":"stab-des-frosts","name":"Stab des Frosts","type":"Stab","rarity":"sehr selten","desc":["Wenn du diesen Stab hältst, bist du gegen Kälteschaden resistent.","Der Stab hat zehn Ladungen. Wenn du ihn hältst, kannst du als Aktion eine oder mehrere Ladungen verbrauchen, um einen der folgenden Zauber mit ihm zu wirken, wobei du deinen Zauberrettungswurf-SG verwendest: Eissturm (vier Ladungen), Eiswand (vier Ladungen), Kältekegel (fünf Ladungen) oder Nebelwolke (eine Ladung).","Der Stab erhält täglich im Morgengrauen 1W6+4 verbrauchte Ladungen zurück. Wenn du die letzte Ladung verbraucht hast, würfle mit einem W20. Bei einer 1 verwandelt sich der Stab in Wasser und ist damit zerstört."],"attune":"erfordert Einstimmung durch einen Druiden, Hexenmeister, Magier oder Zauberer"},
  {"id":"stab-des-magus","name":"Stab des Magus","type":"Stab","rarity":"legendär","desc":["Dieser Stab kann als magischer Kampfstab geführt werden, der einen Bonus von +2 auf Angriffs- und Schadenswürfe verleiht, die du mit ihm ausführst. Wenn du ihn hältst, erhältst du einen Bonus von +2 auf Zauberangriffswürfe.","Der Stab hat 50 Ladungen und die folgenden Eigenschaften. Er erhält täglich im Morgengrauen 4W6+2 verbrauchte Ladungen zurück. Wenn du die letzte Ladung verbraucht hast, würfle mit einem W20. Bei einer 20 erhält er 1W12+1 Ladungen zurück.","Zauberabsorption: Wenn du den Stab hältst, bist du bei Rettungswürfen gegen Zauber im Vorteil. Außerdem kannst du deine Reaktion verwenden, wenn eine andere Kreatur einen Zauber wirkt, der nur dich als Ziel hat. Wenn du dies tust, absorbiert der Stab die Magie des Zaubers. Der Zauber hat keinen Effekt und der Stab erhält Ladungen in Höhe des Zaubergrades hinzu. Wenn jedoch die Gesamtanzahl der Ladungen des Stabs dadurch auf mehr als 50 steigt, explodiert der Stab, als hättest du seinen Vergeltungsschlag (siehe unten) aktiviert.","Zauber: Wenn du den Stab hältst, kannst du als Aktion einige Ladungen verbrauchen, um einen der folgenden Zauber zu wirken, wobei du deinen Zauberrettungswurf-SG und dein Attribut zum Zauberwirken verwendest: Blitz (7. Grad, sieben Ladungen), Ebenenwechsel (sieben Ladungen), Eissturm (vier Ladungen), Elementar beschwören (sieben Ladungen), Feuerball (7. Grad, sieben Ladungen), Feuerwand (vier Ladungen), Flammenkugel (zwei Ladungen), Klopfen (zwei Ladungen), Magie bannen (drei Ladungen), Netz (zwei Ladungen), Telekinese (fünf Ladungen), Unsichtbarkeit (zwei Ladungen) oder Wände passieren (fünf Ladungen).","Du kannst außerdem eine Aktion verwenden, um einen der folgenden Zauber mit dem Stab zu wirken, ohne Ladungen zu verbrauchen: Arkanes Schloss, Licht, Magie entdecken, Magierhand, Schutz vor Gut und Böse oder Vergrößern/Verkleinern.","Vergeltungsschlag: Du kannst den Stab als Aktion über deinem Knie oder an einer harten Oberfläche zerbrechen und einen Vergeltungsschlag ausführen. Der Stab wird zerstört und entlädt seine übrige Magie als Explosion, die sich als Kugel mit einem Radius von neun Metern um den Stab herum ausbreitet.","Du hast eine Chance von 50 Prozent, sofort auf eine zufällige Existenzebene transportiert zu werden und der Explosion zu entkommen. Bei einem Fehlschlag entkommst du dem Effekt nicht und erleidest Energieschaden in Höhe des 16-fachen der Ladungen im Stab. Jede andere Kreatur im Bereich muss einen SG-17-Geschicklichkeitsrettungswurf bestehen. Scheitert der Wurf, erleidet eine Kreatur Schaden abhängig von ihrer Entfernung vom Ursprung, wie die folgende Tabelle zeigt. Anderenfalls erleidet eine Kreatur halb so viel Schaden."],"attune":"erfordert Einstimmung durch einen Hexenmeister, Magier oder Zauberer"},
  {"id":"stab-des-schlagens","name":"Stab des Schlagens","type":"Stab","rarity":"sehr selten","desc":["Dieser Stab kann als magischer Kampfstab geführt werden, der einen Bonus von +3 auf Angriffs- und Schadenswürfe verleiht, die du mit ihm ausführst.","Der Stab hat zehn Ladungen. Wenn du mit ihm einen erfolgreichen Nahkampfangriff ausführst, kannst du bis zu drei seiner Ladungen verbrauchen. Das Ziel erleidet für jede verbrauchte Ladung zusätzlich 1W6 Energieschaden. Der Stab erhält täglich im Morgengrauen 1W6+4 verbrauchte Ladungen zurück. Wenn du die letzte Ladung verbraucht hast, würfle mit einem W20. Bei einer 1 wird der Stab zu einem nichtmagischen Kampfstab."],"attune":"erfordert Einstimmung"},
  {"id":"staub-der-trockenheit","name":"Staub der Trockenheit","type":"Wundersamer Gegenstand","rarity":"ungewöhnlich","desc":["Dieses kleine Paket enthält 1W6+4 Prisen Staub. Du kannst als Aktion eine Prise davon auf Wasser streuen. Der Staub verwandelt einen Würfel Wasser mit einer Kantenlänge von 4,5 Metern in ein murmelgroßes Kügelchen, das in der Nähe der Stelle treibt oder zum Liegen kommt, wo der Staub verstreut wurde. Das Gewicht des Kügelchens ist vernachlässigbar.","Wenn jemand eine Aktion verwendet, um das Kügelchen kraftvoll gegen eine harte Oberfläche zu werfen, zerspringt es und setzt das absorbierte Wasser wieder frei. Dies erschöpft die Magie dieses Kügelchens.","Wenn ein hauptsächlich aus Wasser bestehender Elementar mit einer Prise des Staubes in Berührung kommt, muss er einen SG-13-Konstitutionsrettungswurf bestehen. Scheitert der Wurf, erleidet der Elementar 10W6 nekrotischen Schaden, anderenfalls die Hälfte."]},
  {"id":"staub-des-niesens-und-erstickens","name":"Staub des Niesens und Erstickens","type":"Wundersamer Gegenstand","rarity":"ungewöhnlich","desc":["Dieses Pulver wird in einem kleinen Behälter aufbewahrt und ähnelt feinem Sand. Es ähnelt dem Staub des Verschwindens, und der Zauber Identifizieren enthüllt das Pulver als solchen. Der Behälter enthält ausreichend Pulver für einen Einsatz.","Du kannst als Aktion eine Handvoll des Pulvers in die Luft werfen. Du und jede atmende Kreatur im Abstand von bis zu neun Metern von dir müsst einen SG-15-Konstitutionsrettungswurf bestehen. Anderenfalls kann die betroffene Kreatur beziehungsweise der betroffene Charakter nicht atmen und niest unkontrollierbar. Auf diese Weise betroffene Kreaturen sind kampfunfähig und beginnen zu ersticken. Solange sie bei Bewusstsein ist, kann eine Kreatur den Rettungswurf am Ende jedes ihrer Züge wiederholen. Bei einem Erfolg endet der Effekt. Der Zauber Schwache Genesung kann den Effekt ebenfalls beenden."]},
  {"id":"staub-des-verschwindens","name":"Staub des Verschwindens","type":"Wundersamer Gegenstand","rarity":"ungewöhnlich","desc":["Dieses Pulver wird in einem kleinen Paket aufbewahrt und ähnelt feinem Sand. Das Paket enthält ausreichend Pulver für einen Einsatz. Du kannst eine Aktion verwenden und den Staub in die Luft werfen, um dich sowie jede Kreatur und jedes Objekt im Abstand von bis zu drei Metern von dir 2W4 Minuten lang unsichtbar werden zu lassen. Die Dauer gilt für alle Wesen und Objekte gleichermaßen. Der Staub wird verbraucht, wenn seine Magie wirkt. Wenn eine durch den Staub unsichtbare Kreatur angreift oder einen Zauber wirkt, endet ihre Unsichtbarkeit."]},
  {"id":"stein-der-erdelementar-herrschaft","name":"Stein der Erdelementar-Herrschaft","type":"Wundersamer Gegenstand","rarity":"selten","desc":["Wenn dieser Stein den Boden berührt, kannst du als Aktion sein Befehlswort aussprechen und einen Erdelementar beschwören, als hättest du den Zauber Elementar beschwören gewirkt. Der Stein kann erst im nächsten Morgengrauen wieder auf diese Weise verwendet werden. Der Stein wiegt 2,5 Kilogramm."]},
  {"id":"stein-des-gluecks-gluecksstein","name":"Stein des Glücks (Glücksstein)","type":"Wundersamer Gegenstand","rarity":"ungewöhnlich","desc":["Solange du diesen polierten Achat bei dir trägst, erhältst du einen Bonus von +1 auf Attributs- und Rettungswürfe."],"attune":"erfordert Einstimmung"},
  {"id":"stiefel-der-elfen","name":"Stiefel der Elfen","type":"Wundersamer Gegenstand","rarity":"ungewöhnlich","desc":["Wenn du diese Stiefel trägst, sind deine Schritte unabhängig vom Untergrund geräuschlos. Außerdem bist du bei Geschicklichkeitswürfen (Heimlichkeit), die geräuschlose Bewegung voraussetzen, im Vorteil."]},
  {"id":"stiefel-der-geschwindigkeit","name":"Stiefel der Geschwindigkeit","type":"Wundersamer Gegenstand","rarity":"selten","desc":["Wenn du diese Stiefel trägst, kannst du deren Absätze als Bonusaktion zusammenschlagen. Wenn du das tust, verdoppeln die Stiefel deine Schrittbewegungsrate, und jede Kreatur, die einen Gelegenheitsangriff gegen dich ausführt, ist beim Angriffswurf im Nachteil. Wenn du deine Fersen wieder zusammenschlägst, beendest du den Effekt.","Wenn die Eigenschaft der Stiefel für insgesamt zehn Minuten verwendet wurde, steht dir die Magie erst nach einer langen Rast wieder zur Verfügung."],"attune":"erfordert Einstimmung"},
  {"id":"stiefel-der-winterlande","name":"Stiefel der Winterlande","type":"Wundersamer Gegenstand","rarity":"ungewöhnlich","desc":["Diese bequemen Pelzstiefel fühlen sich ziemlich warm an. Wenn du sie trägst, erhältst du die folgenden Vorteile:"],"attune":"erfordert Einstimmung"},
  {"id":"stiefel-des-schreitens-und-springens","name":"Stiefel des Schreitens und Springens","type":"Wundersamer Gegenstand","rarity":"ungewöhnlich","desc":["Wenn du diese Stiefel trägst, beträgt deine Schrittbewegungsrate neun Meter, es sei denn, sie ist normalerweise höher. Außerdem verringert sich deine Bewegungsrate nicht, wenn du belastet bist oder schwere Rüstung trägst. Außerdem verdreifacht sich deine Sprungdistanz, wobei du jedoch nicht weiter springen kannst, als deine verbleibende Bewegung erlauben würde."],"attune":"erfordert Einstimmung"},
  {"id":"stiefel-des-schwebens","name":"Stiefel des Schwebens","type":"Wundersamer Gegenstand","rarity":"selten","desc":["Wenn du diese Stiefel trägst, kannst du den Zauber Schweben als Aktion beliebig oft auf dich selbst wirken."],"attune":"erfordert Einstimmung"},
  {"id":"stirnband-der-intelligenz","name":"Stirnband der Intelligenz","type":"Wundersamer Gegenstand","rarity":"ungewöhnlich","desc":["Wenn du diese dieses Stirnband trägst, ist dein Intelligenzwert 19. Es hat keinen Effekt, wenn er bereits 19 oder höher ist."],"attune":"erfordert Einstimmung"},
  {"id":"streitkolben-des-niederstreckens","name":"Streitkolben des Niederstreckens","type":"Waffe (Streitkolben)","rarity":"selten","desc":["Du erhältst einen Bonus von +1 auf Angriffs- und Schadenswürfe, die du mit dieser magischen Waffe ausführst. Der Bonus erhöht sich auf +3, wenn du ein Konstrukt mit dem Streitkolben angreifst.","Wenn du bei einem Angriffswurf mit dieser Waffe eine 20 würfelst, erleidet das Ziel zusätzlich 2W6 Wuchtschaden. Wenn das Ziel ein Konstrukt ist, erleidet es 4W6 Wuchtschaden. Wenn ein Konstrukt nach Erleiden des Schadens nur noch höchstens 25 Trefferpunkte hat, wird es zerstört."],"attune":"Streitkolben"},
  {"id":"streitkolben-des-terrors","name":"Streitkolben des Terrors","type":"Waffe (Streitkolben)","rarity":"selten","desc":["Diese magische Waffe hat drei Ladungen. Wenn du ihn trägst, kannst du als Aktion eine Ladung verbrauchen, um eine Welle des Terrors zu entfesseln. Jede Kreatur deiner Wahl im Radius von neun Metern von dir muss einen SG-15-Weisheitsrettungswurf bestehen, oder sie ist eine Minute lang von dir verängstigt Eine auf diese Weise verängstigte Kreatur muss ihre Züge dafür verwenden, sich so weit wie möglich von dir zu entfernen, und darf dir nicht absichtlich näher als neun Meter kommen. Außerdem kann sie nicht reagieren. Als Aktion kann sie nur die Spurt-Aktion ausführen oder versuchen, sich von einem Effekt zu befreien, der sie in ihrer Bewegung einschränkt. Kann die Kreatur sich nirgendwohin bewegen, kann sie trotzdem eine Ausweichaktion verwenden. Am Ende jedes ihrer Züge kann eine Kreatur den Rettungswurf wiederholen und den Effekt bei einem Erfolg beenden.","Der Streitkolben erhält täglich im Morgengrauen 1W3 verbrauchte Ladungen zurück."],"attune":"Streitkolben"},
  {"id":"streitkolben-des-zusammenbruchs","name":"Streitkolben des Zusammenbruchs","type":"Waffe (Streitkolben)","rarity":"selten","desc":["Wenn du einen Unhold oder Untoten mit dieser magischen Waffe triffst, erleidet diese Kreatur zusätzlich 2W6 gleißenden Schaden. Wenn das Ziel nach Erleiden des Schadens noch höchstens 25 Trefferpunkte hat, muss es einen SG-15-Weisheitsrettungswurf bestehen, oder es wird zerstört. Bei einem erfolgreichen Rettungswurf ist die Kreatur bis zum Ende deines nächsten Zugs von dir verängstigt.","Wenn du diese Waffe hältst, spendet sie im Radius von sechs Metern helles Licht und im Radius von weiteren sechs Metern dämmriges Licht."],"attune":"Streitkolben"},
  {"id":"talisman-des-absolut-boesen","name":"Talisman des absolut Bösen","type":"Wundersamer Gegenstand","rarity":"legendär","desc":["Dieser Gegenstand ist das Symbol des reuelosen Bösen. Eine Kreatur, deren Gesinnung weder gut noch böse ist, erleidet 6W6 nekrotischen Schaden, wenn sie den Talisman berührt. Eine gute Kreatur erleidet 8W6 nekrotischen Schaden, wenn sie den Talisman berührt. Beide Arten von Kreaturen erleiden den Schaden jedes Mal erneut, wenn sie ihren Zug beenden und den Talisman halten oder tragen.","Wenn du ein böser Kleriker oder Paladin bist, kannst du den Talisman als heiliges Symbol verwenden, und du erhältst einen Bonus von +2 auf Zauberangriffswürfe, wenn du ihn trägst oder hältst.","Der Talisman hat sechs Ladungen. Wenn du ihn trägst oder hältst, kannst du als Aktion eine Ladung verbrauchen und eine Kreatur am Boden auswählen, die du im Abstand von bis zu 36 Metern von dir sehen kannst. Wenn die Gesinnung des Ziels gut ist, öffnet sich ein brennender Spalt unter ihr. Das Ziel muss einen SG-20-Geschicklichkeitsrettungswurf bestehen, oder es fällt in den Spalt und wird zerstört, ohne sterbliche Überreste zu hinterlassen. Der Spalt schließt sich dann spurlos. Wenn du die letzte Ladung verbrauchst, löst sich der Talisman in eklig riechenden Schleim auf und wird zerstört."],"attune":"erfordert Einstimmung durch eine Kreatur böser Gesinnung"},
  {"id":"talisman-des-nichts","name":"Talisman des Nichts","type":"Wundersamer Gegenstand","rarity":"legendär","desc":["Wenn du einen Intelligenzwurf (Arkane Kunde) ausführst, um eine Sphäre des Nichts zu kontrollieren, während du diesen Talisman hältst, verdoppelst du deinen Übungsbonus für den Wurf. Außerdem kannst du, wenn du zu Beginn deines Zugs eine Sphäre des Nichts kontrollierst, eine Aktion verwenden, um sie drei Meter plus weitere drei Meter mal deinem Intelligenzmodifikator hoch schweben zu lassen."],"attune":"erfordert Einstimmung"},
  {"id":"talisman-des-reinen-guten","name":"Talisman des reinen Guten","type":"Wundersamer Gegenstand","rarity":"legendär","desc":["Dieser Talisman ist ein mächtiges Symbol des Guten. Eine Kreatur, deren Gesinnung weder gut noch böse ist, erleidet 6W6 gleißenden Schaden, wenn sie den Talisman berührt. Eine böse Kreatur erleidet 8W6 gleißenden Schaden, wenn sie den Talisman berührt. Beide Arten von Kreaturen erleiden den Schaden jedes Mal erneut, wenn sie ihren Zug beenden und den Talisman halten oder tragen.","Wenn du ein guter Kleriker oder Paladin bist, kannst du den Talisman als heiliges Symbol verwenden, und du erhältst einen Bonus von +2 auf Zauberangriffswürfe, wenn du ihn trägst oder hältst.","Der Talisman hat sieben Ladungen. Wenn du ihn trägst oder hältst, kannst du als Aktion eine Ladung verbrauchen und eine Kreatur am Boden auswählen, die du im Abstand von bis zu 36 Metern von dir sehen kannst. Wenn die Gesinnung des Ziels böse ist, öffnet sich ein brennender Spalt unter ihr. Das Ziel muss einen SG-20-Geschicklichkeitsrettungswurf bestehen, oder es fällt in den Spalt und wird zerstört, ohne sterbliche Überreste zu hinterlassen. Der Spalt schließt sich dann spurlos. Wenn du die letzte Ladung verbrauchst, löst sich der Talisman in goldene Lichtfunken auf und wird zerstört."],"attune":"erfordert Einstimmung durch eine Kreatur guter Gesinnung"},
  {"id":"tanzendes-schwert","name":"Tanzendes Schwert","type":"Waffe (beliebiges Schwert)","rarity":"sehr selten","desc":["Du kannst dieses magische Schwert als Bonusaktion in die Luft werfen und sein Befehlswort aussprechen. Wenn du das tust, beginnt das Schwert zu schweben, fliegt neun Meter hoch und greift eine Kreatur deiner Wahl im Abstand von bis zu 1,5 Metern vom Schwert an. Das Schwert verwendet deinen Angriffswurf und deinen Attributsmodifikator für Schadenswürfe.","Wenn das Schwert schwebt, kannst du es als Bonusaktion bis zu neun Meter an einen anderen Ort im Abstand von bis zu neun Metern von dir fliegen lassen. Innerhalb derselben Bonusaktion kannst du das Schwert eine Kreatur im Abstand von bis zu 1,5 Metern von ihm angreifen lassen.","Nachdem das schwebende Schwert seinen vierten Angriff ausgeführt hat, fliegt es bis zu neun Meter weit, um in deine Hand zurückzukehren. Wenn du keine Hand frei hast, fällt es zu deinen Füßen auf den Boden. Wenn das Schwert keinen freien Weg zu dir finden kann, bewegt es sich so weit wie möglich in deine Richtung und fällt dann zu Boden. Es hört auch auf zu schweben, wenn du es in die Hand nimmst oder dich weiter als neun Meter von ihm wegbewegst."],"attune":"beliebiges Schwert"},
  {"id":"tragbares-loch","name":"Tragbares Loch","type":"Wundersamer Gegenstand","rarity":"selten","desc":["Dieses feine, schwarze Tuch ist seidenweich und auf die Größe eines Taschentuchs zusammengefaltet. Ausgebreitet ist es ein kreisrundes Tuch mit einem Durchmesser von 1,8 Metern.","Du kannst ein Tragbares Loch als Aktion ausbreiten und auf oder gegen eine feste Oberfläche legen. Daraufhin erzeugt das Tragbare Loch ein drei Meter tiefes extradimensionales Loch. Der zylindrische Raum im Inneren des Lochs befindet sich auf einer anderen Ebene, sodass das Loch nicht verwendet werden kann, um Durchgänge zu öffnen. Eine Kreatur innerhalb eines offenen Tragbaren Lochs kann aus dem Loch hinausklettern.","Du kannst ein Tragbares Loch als Aktion schließen, indem du den Rand des Tuchs greifst und es zusammenfaltest Durch das Falten des Stoffs schließt sich das Loch und Kreaturen oder Gegenstände in seinem Inneren bleiben im extradimensionalen Raum. Das Loch wiegt unabhängig von seinem Inhalt fast nichts.","Wenn das Loch zusammengefaltet ist, kann eine Kreatur im Inneren des extradimensionalen Raums als Aktion einen SG-10-Stärkewurf ausführen. Bei einem Erfolg gelangt die Kreatur aus dem Loch und erscheint im Abstand von bis zu 1,5 Metern vom Tragbaren Loch oder von der Kreatur, die es trägt. Eine atmende Kreatur in einem geschlossenen Tragbaren Loch kann bis zu zehn Minuten lang überleben. Danach beginnt sie zu ersticken.","Wenn ein Tragbares Loch in den extradimensionalen Raum eines Nimmervollen Beutels, eines Praktischen Rucksacks oder eines ähnlichen Gegenstands gelangt, zerstört dies sofort beide Gegenstände, und ein Tor in die Astralebene öffnet sich. Das Tor erscheint dort, wo der eine Gegenstand in den anderen gelangt ist. Kreaturen im Abstand von bis zu drei Metern vom Tor werden hineingezogen und an einen zufälligen Ort auf der Astralebene transportiert. Dann schließt sich das Tor. Das Tor funktioniert nur in eine Richtung und kann nicht wieder geöffnet werden."]},
  {"id":"trank-der-gasfoermigen-gestalt","name":"Trank der gasförmigen Gestalt","type":"Trank","rarity":"selten","desc":["Wenn du diesen Trank trinkst, erhältst du eine Stunde lang - oder bis du den Effekt als Bonusaktion beendest - den Effekt des Zaubers Gasförmige Gestalt (keine Konzentration notwendig). Der Behälter dieses Tranks scheint mit einem Nebel gefüllt zu sein, der sich wie Wasser ausgießen lässt."]},
  {"id":"trank-der-geschwindigkeit","name":"Trank der Geschwindigkeit","type":"Trank","rarity":"sehr selten","desc":["Wenn du diesen Trank trinkst, erhältst du eine Minute lang den Effekt des Zaubers Hast (keine Konzentration notwendig). In der gelben Flüssigkeit des Tranks wirbeln schwarze Streifen umher."]},
  {"id":"trank-der-riesenstaerke","name":"Trank der Riesenstärke","type":"Trank","rarity":"Seltenheit variiert","desc":["Wenn du diesen Trank trinkst, verändert sich eine Stunde lang dein Stärkewert. Der Wert hängt von der Riesenart ab (siehe Tabelle unten). Der Trank hat keinen Effekt, wenn deine Stärke bereits gleich oder größer als dieser Wert ist.","In der klaren Flüssigkeit dieses Tranks schwimmt ein kleines Stück eines Fingernagels der jeweiligen Riesenart. Der Trank der Frostriesenstärke und der Trank der Steinriesenstärke haben dieselbe Wirkung."]},
  {"id":"trank-der-tierfreundschaft","name":"Trank der Tierfreundschaft","type":"Trank","rarity":"ungewöhnlich","desc":["Wenn du diesen Trank trinkst, kannst du den Zauber Tierfreundschaft (Rettungswurf-SG 13) eine Stunde lang beliebig oft wirken. Wird diese schlammfarbene Flüssigkeit geschüttelt, werden kleine Stücke sichtbar: eine Fischschuppe, die Zunge eines Kolibris, eine Katzenkralle oder ein Eichhörnchenhaar."]},
  {"id":"trank-der-unsichtbarkeit","name":"Trank der Unsichtbarkeit","type":"Trank","rarity":"sehr selten","desc":["Der Behälter für diesen Trank sieht leer aus, fühlt sich aber an, als wäre Flüssigkeit darin. Wenn du ihn trinkst, wirst du eine Stunde lang unsichtbar. Alles, was du trägst oder mit dir führst, wird mit dir unsichtbar. Der Effekt endet vorzeitig, wenn du angreifst oder einen Zauber wirkst."]},
  {"id":"trank-der-verkleinerung","name":"Trank der Verkleinerung","type":"Trank","rarity":"selten","desc":["Wenn du diesen Trank trinkst, erhältst du 1W4 Stunden lang den Verkleinern-Effekt des Zaubers Vergrößern/Verkleinern (keine Konzentration erforderlich). Das rote Zentrum dieses Tranks zieht sich ständig zu einem winzigen Kern zusammen und dehnt sich dann wieder aus, sodass die gesamte sonst klare Flüssigkeit rot wird. Das Pulsieren wird auch durch das Schütteln der Flasche nicht unterbrochen."]},
  {"id":"trank-der-wasseratmung","name":"Trank der Wasseratmung","type":"Trank","rarity":"ungewöhnlich","desc":["Wenn du diesen Trank trinkst, kannst du eine Stunde lang unter Wasser atmen. Die grüne wolkige Flüssigkeit riecht nach Meer, und es treibt eine kleine quallenartige Blase darin."]},
  {"id":"trank-des-fliegens","name":"Trank des Fliegens","type":"Trank","rarity":"sehr selten","desc":["Wenn du diesen Trank trinkst, erhältst du eine Stunde lang eine Flugbewegungsrate, die deiner Schrittbewegungsrate entspricht und kannst schweben. Wenn du in der Luft bist, wenn die Wirkung des Tranks endet, fällst du zu Boden, sofern du keine anderen Möglichkeiten hast, weiter zu fliegen oder zu schweben. Die klare Flüssigkeit dieses Tranks schwebt im oberen Teil seines Gefäßes. Trübweiße Unreinheiten treiben darin."]},
  {"id":"trank-des-gedankenlesens","name":"Trank des Gedankenlesens","type":"Trank","rarity":"selten","desc":["Wenn du diesen Trank trinkst, erhältst du den Effekt des Zaubers Gedanken wahrnehmen (Rettungswurf-SG 13), In der dickflüssigen, violetten Flüssigkeit des Tranks treibt eine ovale, rosafarbene Wolke."]},
  {"id":"trank-des-gifts","name":"Trank des Gifts","type":"Trank","rarity":"ungewöhnlich","desc":["Dieses Gebräu riecht, schmeckt und sieht aus wie ein Heiltrank oder ein anderer vorteilhafter Trank. Allerdings ist dieser Trank ein Gift, das durch Illusionsmagie maskiert wurde. Der Zauber Identifizieren enthüllt seine wahre Natur.","Wenn du ihn trinkst, erleidest du 3W6 Giftschaden und musst einen SG-13-Konstitutionsrettungswurf bestehen, oder du bist vergiftet. Solange du auf diese Weise vergiftet bist, erleidest du zu Beginn jedes deiner Züge 3W6 Giftschaden. Du kannst den Rettungswurf am Ende jedes deiner Züge wiederholen. Bei einem erfolgreichen Rettungswurf verringert sich der Giftschaden, den du in deinen weiteren Zügen erleidest, um 1W6. Das Gift verliert seine Wirkung, wenn der Schaden auf 0 reduziert wurde."]},
  {"id":"trank-des-heldenmuts","name":"Trank des Heldenmuts","type":"Trank","rarity":"selten","desc":["Du erhältst nach dem Trinken eine Stunde lang 10 temporäre Trefferpunkte. Während dieser Zeit profitierst du vom Effekt des Zaubers Segnen (keine Konzentration erforderlich). Dieser blaue Trank blubbert und dampft, als würde er kochen."]},
  {"id":"trank-des-hellsehens","name":"Trank des Hellsehens","type":"Trank","rarity":"selten","desc":["Wenn du diesen Trank trinkst, erhältst du den Effekt des Zaubers Hellsehen. In der gelblichen Flüssigkeit schwimmt ein Augapfel, der verschwindet, sobald der Trank geöffnet wird."]},
  {"id":"trank-des-kletterns","name":"Trank des Kletterns","type":"Trank","rarity":"gewöhnlich","desc":["Wenn du diesen Trank trinkst, erhältst du eine Stunde lang eine Kletterbewegungsrate, die deiner Schrittbewegungsrate entspricht. Während dieser Zeit bist du bei Stärkewürfen (Athletik) im Vorteil, die du zum Klettern ausführst Der Trank ist in braune, silberne und graue Schichten getrennt, die wie die Maserung von Steinen aussehen. Durch das Schütteln der Flasche vermischen sich die Schichten nicht."]},
  {"id":"trank-des-wachstums","name":"Trank des Wachstums","type":"Trank","rarity":"ungewöhnlich","desc":["Wenn du diesen Trank trinkst, erhältst du 1W4 Stunden lang den Vergrößern-Effekt des Zaubers Vergrößern/Verkleinern (keine Konzentration erforderlich). Das winzige rote Zentrum dieses Tranks expandiert ständig, sodass die gesamte sonst klare Flüssigkeit rot wird und zieht sich dann wieder zusammen. Das Pulsieren wird auch durch das Schütteln der Flasche nicht unterbrochen."]},
  {"id":"trank-des-widerstands","name":"Trank des Widerstands","type":"Trank","rarity":"ungewöhnlich","desc":["Wenn du diesen Trank trinkst, bist du eine Stunde lang gegen eine Schadensart resistent. Der SL wählt anhand der Optionen unten die Schadensart aus oder bestimmt sie zufällig."]},
  {"id":"trickbeutel","name":"Trickbeutel","type":"Wundersamer Gegenstand","rarity":"ungewöhnlich","desc":["Dieser gewöhnliche Beutel aus beigefarbenem, grauem oder rostfarbenem Stoff scheint leer zu sein. Ein Griff in den Beutel offenbart jedoch einen kleinen, flauschigen Gegenstand. Der Beutel wiegt 0,25 Kilogramm.","Du kannst den flauschigen Gegenstand als Aktion aus dem Beutel ziehen und sechs Meter in die Luft werfen. Wenn der Gegenstand landet, verwandelt er sich in eine Kreatur, die du bestimmst, indem du mit einem W8 würfelst und in der Tabelle nachschaust, die der Farbe des Beutels entspricht. Die Kreatur verschwindet im nächsten Morgengrauen oder wenn ihre Trefferpunkte auf 0 sinken.","Die Kreatur ist dir und deinen Verbündeten gegenüber freundlich und handelt in deinem Zug. Du kannst eine Bonusaktion verwenden, um der Kreatur Anweisungen zu geben, wohin sie sich bewegen und welche Aktion sie in ihrem nächsten Zug ausführen soll. Du kannst ihr auch allgemeinere Befehle wie 'greife deine Gegner an' geben. Wenn sie keine Befehle erhält, handelt die Kreatur, wie es ihrer Natur entspricht.","Nachdem drei flauschige Gegenstände aus dem Beutel gezogen wurden, kann der Beutel bis zum nächsten Morgengrauen nicht mehr verwendet werden."]},
  {"id":"umhang-der-fledermaus","name":"Umhang der Fledermaus","type":"Wundersamer Gegenstand","rarity":"selten","desc":["Wenn du diesen Umhang trägst, bist du bei Geschicklichkeitswürfen (Heimlichkeit) im Vorteil. In Bereichen mit dämmrigem Licht oder Dunkelheit kannst du die Ränder des Umhangs mit beiden Händen greifen und den Umhang verwenden, um mit einer Bewegungsrate von zwölf Metern zu fliegen. Falls dir die Enden des Umhangs aus den Fingern gleiten, während du auf diese Weise fliegst, oder wenn du nicht mehr in dämmrigem Licht oder in Dunkelheit bist, verlierst du die Flugbewegungsrate.","Wenn du den Umhang in einem Bereich mit dämmrigem Licht oder Dunkelheit trägst, kannst du deine Aktion verwenden, um Verwandlung auf dich selbst zu wirken und dich in eine Fledermaus zu verwandeln. Du behältst deine Intelligenz-,","Weisheits- und Charismawerte, während du eine Fledermaus bist. Der Umhang kann erst im nächsten Morgengrauen wieder auf diese Weise verwendet werden."],"attune":"erfordert Einstimmung"},
  {"id":"umhang-der-spinnentiere","name":"Umhang der Spinnentiere","type":"Wundersamer Gegenstand","rarity":"sehr selten","desc":["Dieser feine Umhang ist aus schwarzer Seide gewoben und mit zarten, silbrig glänzenden Fäden durchwirkt.","Wenn du ihn trägst, erhältst du die folgenden Vorteile:"],"attune":"erfordert Einstimmung"},
  {"id":"umhang-der-verlagerung","name":"Umhang der Verlagerung","type":"Wundersamer Gegenstand","rarity":"selten","desc":["Wenn du diesen Umhang trägst, projiziert er eine Illusion, die dich dicht neben deinem eigentlichen Standort erscheinen lässt. Dadurch sind Kreaturen bei Angriffswürfen gegen dich im Nachteil. Wenn du Schaden erleidest, kannst du diese Eigenschaft erst zu Beginn deines nächsten Zugs erneut verwenden. Diese Eigenschaft ist nicht aktiv, wenn du kampfunfähig, festgesetzt oder auf andere Art nicht in der Lage bist, dich zu bewegen."],"attune":"erfordert Einstimmung"},
  {"id":"umhang-des-mantarochens","name":"Umhang des Mantarochens","type":"Wundersamer Gegenstand","rarity":"ungewöhnlich","desc":["Wenn du diesen Umhang mit aufgesetzter Kapuze trägst, kannst du unter Wasser atmen und du hast eine Schwimmbewegungsrate von 18 Metern. Das Aufoder Absetzen der Kapuze erfordert eine Aktion."]},
  {"id":"umhang-des-scharlatans","name":"Umhang des Scharlatans","type":"Wundersamer Gegenstand","rarity":"selten","desc":["Dieser Umhang riecht leicht nach Schwefel. Wenn du ihn trägst, kannst du als Aktion den Zauber Dimensionstür mit ihn wirken. Diese Eigenschaft des Umhangs kann erst im nächsten Morgengrauen wiederverwendet werden.","Wenn du verschwindest, hinterlässt du am Ausgangsort eine Rauchwolke und erscheinst am Zielort in einer ähnlichen Rauchwolke. Der Rauch verschleiert den Ausgangs- und Zielbereich leicht. Er verzieht sich am Ende deines nächsten Zugs. Ein starker Wind verweht den Rauch."]},
  {"id":"umhang-des-schutzes","name":"Umhang des Schutzes","type":"Wundersamer Gegenstand","rarity":"ungewöhnlich","desc":["Wenn du diesen Umhang trägst, erhältst du einen Bonus von +1 auf deine RK und deine Rettungswürfe."],"attune":"erfordert Einstimmung"},
  {"id":"unbewegliches-zepter","name":"Unbewegliches Zepter","type":"Zepter","rarity":"ungewöhnlich","desc":["Dieses flache eiserne Zepter hat an einem Ende einen Knopf. Du kannst eine Aktion verwenden, um diesen Knopf zu drücken, damit das Zepter magisch fixiert wird. Bis eine weitere Aktion verwendet und der Knopf erneut gedrückt wird, bewegt sich das Zepter nicht, selbst wenn es dabei der Schwerkraft trotzt. Das Zepter kann bis zu 4.000 Kilogramm Gewicht tragen. Bei noch mehr Gewicht wird das Zepter deaktiviert und fällt zu Boden. Eine Kreatur kann als Aktion einen SG-30-Stärkewurf ausführen. Bei einem Erfolg bewegt sie das fixierte Zepter um bis zu drei Meter."]},
  {"id":"universelles-loesungsmittel","name":"Universelles Lösungsmittel","type":"Wundersamer Gegenstand","rarity":"legendär","desc":["Dieses Fläschchen enthält eine milchige Flüssigkeit mit starkem Alkoholgeruch. Du kannst eine Aktion verwenden, um den Inhalt des Fläschchens auf eine Oberfläche in Reichweite zu gießen. Die Flüssigkeit löst sofort eine quadratische Fläche mit einer Kantenlänge von bis zu 30 Zentimetern auf, wenn sie damit in Berührung kommt. Sie funktioniert auch bei Ewigem Leim."]},
  {"id":"verteidiger","name":"Verteidiger","type":"Waffe (beliebiges Schwert)","rarity":"legendär","desc":["Du erhältst einen Bonus von +3 auf Angriffs- und Schadenswürfe, die du mit dieser magischen Waffe ausführst.","Wenn in jedem deiner Züge du das erste Mal mit dem Schwert angreifst, kannst du einen Teil oder den gesamten Bonus des Schwerts auf deine Rüstungsklasse übertragen, statt ihn in dem Zug für Angriffe zu verwenden. Du kannst zum Beispiel den Bonus für deine Angriffs- und Schadenswürfe auf+1 reduzieren und einen Bonus von +2 auf deine RK erhalten. Die angepassten Boni bleiben bis zum Beginn deines nächsten Zugs bestehen. Du musst das Schwert allerdings halten, um einen Bonus auf deine RK zu erhalten."],"attune":"beliebiges Schwert"},
  {"id":"verzaubertes-beschlagenes-leder","name":"Verzaubertes beschlagenes Leder","type":"Rüstung (beschlagenes Leder)","rarity":"selten","desc":["Wenn du diese Rüstung trägst, erhältst du einen Bonus von +1 auf deine RK. Du kannst außerdem als Bonusaktion das Befehlswort der Rüstung aussprechen. Daraufhin nimmt die Rüstung das Aussehen normaler Kleidung oder einer anderen Rüstung an. Du entscheidest, wie sie aussieht - einschließlich Farbe, Stil und Zubehör - aber die Rüstung behält ihre normale Masse und ihr Gewicht. Die illusionäre Erscheinung hält an, bis du diese Eigenschaft wieder verwendest oder die Rüstung ablegst."],"attune":"beschlagenes Leder"},
  {"id":"waffe-1-2-oder-3","name":"Waffe, +1, +2 oder +3","type":"Waffe (beliebig)","rarity":"ungewöhnlich (+1), selten (+2) oder sehr selten (+3)","desc":["Du erhältst einen Bonus auf alle Angriffs- und Schadenswürfe, die du mit dieser magischen Waffe ausführst. Der Bonus wird durch die Seltenheit der Waffe bestimmt."],"attune":"beliebig"},
  {"id":"windfaecher","name":"Windfächer","type":"Wundersamer Gegenstand","rarity":"ungewöhnlich","desc":["Wenn du diesen Fächer hältst, kannst du als Aktion den Zauber Windstoß (Rettungswurf-SG 13) mit ihm wirken. Nachdem er verwendet wurde, kann der Fächer erst im nächsten Morgengrauen wiederverwendet werden. Jedes Mal, wenn er vor diesem Zeitpunkt wiederverwendet wird, besteht eine kumulative Chance von 20 Prozent, dass er nicht funktioniert und in nutzlose, nichtmagische Fetzen zerfällt."]},
  {"id":"wunderfarben","name":"Wunderfarben","type":"Wundersamer Gegenstand","rarity":"sehr selten","desc":["Diese Pigmente sind meist in 1W4 Töpfen in einer edlen Holzkiste mit Pinsel zu finden (alles zusammen wiegt 0,5 Kilogramm). Du kannst mit ihnen dreidimensionale Gegenstände erschaffen, indem du sie zweidimensional malst Die Farbe fließt vom Pinsel und formt den gewünschten Gegenstand, wenn du ihn visualisierst.","Jeder Farbtopf enthält genug Farbe, um 92 Quadratmeter Fläche zu bedecken. Du kannst damit unbelebte Gegenstände oder Geländebestandteile mit einem Volumen von maximal 283 Kubikmetern erschaffen - zum Beispiel eine Tür, eine Grube, Blumen, Zellen, Räume oder Waffen. Es dauert zehn Minuten, eine Fläche von neun Quadratmetern zu bemalen.","Wenn du das Bild fertigstellst, wird der dargestellte Gegenstand oder Geländebestandteil ein echter, nichtmagischer Gegenstand. Wenn du eine Tür an eine Wand malst, erschaffst du also eine echte Tür, die geöffnet werden kann und in den Bereich auf der anderen Seite der Wand führt Wenn du eine Grube auf den Boden malst, wird sie zu einer echten Grube, und ihre Tiefe wird zur Gesamtfläche deiner gemalten Gegenstände hinzugerechnet","Mit den Pigmenten erschaffene Dinge können maximal 25 GM wert sein. Wenn du einen Gegenstand malst, der mehr wert ist, beispielsweise einen Diamanten oder einen Haufen Gold, sieht der Gegenstand echt aus. Bei näherer Betrachtung wird jedoch offensichtlich, dass er aus Glas, Knochen oder einem anderen wertlosen Material besteht.","Wenn du eine Energieform wie Feuer oder Blitze malst, wird die Energie kurz real. Allerdings verflüchtigt sie sich sofort nach der Fertigstellung des Bildes, ohne Schaden anzurichten."]},
  {"id":"wuerfel-der-ebenen","name":"Würfel der Ebenen","type":"Wundersamer Gegenstand","rarity":"legendär","desc":["Dieser Würfel hat eine Kantenlänge von 7,5 Zentimetern und strahlt spürbare magische Energie aus. Die sechs Seiten des Würfels sind jeweils mit einer bestimmten Existenzebene verbunden. Eine davon ist die materielle Ebene. Die anderen Seiten sind mit Ebenen verbunden, die der SL bestimmt","Du kannst als Aktion eine Seite des Würfels drücken und den Zauber Tor mit dem Würfel wirken. Dadurch öffnet sich ein Portal zu der zur jeweiligen Würfelseite gehörigen Ebene. Wenn du allerdings eine Aktion verwendest, um eine Seite des Würfels zweimal zu drücken, wirkst du den Zauber Ebenenwechsel (Zauberrettungswurf-SG 17) mit dem Würfel und transportierst die Ziele zu der zur jeweiligen Würfelseite gehörigen Ebene.","Der Würfel hat drei Ladungen. Jede Verwendung des Würfels verbraucht eine Ladung. Der Würfel erhält täglich im Morgengrauen 1W3 verbrauchte Ladungen zurück."]},
  {"id":"wuerfel-der-kraft","name":"Würfel der Kraft","type":"Wundersamer Gegenstand","rarity":"selten","desc":["Dieser Würfel hat eine Kantenlänge von etwa 2,5 Zentimetern. Jede Seite hat ein deutliches Zeichen, das gedrückt werden kann. Der Würfel beginnt mit 36 Ladungen und erhält täglich im Morgengrauen 1W20 verbrauchte Ladungen zurück.","Du kannst als Aktion eine der Würfelseiten drücken. Du verbrauchst so viele Ladungen, wie die gewählte Seite anzeigt. Die Zeichen auf jeder Seite sind in der Tabelle 'Seiten des Würfels der Kraft' angegeben. Jede Seite hat einen anderen Effekt Wenn der Würfel nicht mehr genügend Ladungen hat, passiert nichts. Anderenfalls wird eine würfelförmige Barriere aus unsichtbarer Energie mit 4,5 Metern Kantenlänge erzeugt. Du bildest den Mittelpunkt der Barriere. Sie bewegt sich mit dir und existiert eine Minute lang, bis du eine Aktion verwendest, um die sechste Seite des Würfels zu drücken, oder bis der Würfel keine Ladungen mehr hat. Du kannst den Effekt der Barriere ändern, indem du eine andere Seite des Würfels drückst und die entsprechende Anzahl an Ladungen verbrauchst. Dabei wird die Wirkungsdauer zurückgesetzt","Wenn die Barriere durch deine Bewegung mit einem festen Gegenstand in Kontakt kommst, der den Würfel nicht durchdringen kann, kannst du nicht näher an den Gegenstand gelangen, bis die Barriere aufhört zu existieren.","Der Würfel verliert Ladungen, wenn die Barriere das Ziel bestimmter Zauber ist oder mit bestimmten Effekten von Zaubern oder magischen Gegenständen in Kontakt kommt. Diese sind in der folgenden Tabelle angegeben."],"attune":"erfordert Einstimmung"},
  {"id":"wurfspeer-des-blitzes","name":"Wurfspeer des Blitzes","type":"Waffe (Wurfspeer)","rarity":"ungewöhnlich","desc":["Dieser Wurfspeer ist eine magische Waffe. Wenn du ihn wirfst und dabei sein Befehlswort aussprichst, verwandelt er sich in einen 1,5 Meter breiten Blitz in Form einer Linie, die sich von dir bis zu einem Ziel im Abstand von bis zu 36 Metern erstreckt.","Jede Kreatur im Bereich der Linie außer dir und dem Ziel muss einen SG-13-Geschicklichkeitsrettungswurf bestehen. Scheitert der Wurf, erleidet die Kreatur 4W6 Blitzschaden, anderenfalls die Hälfte. Der Blitz wird wieder zu einem Wurfspeer, wenn er das Ziel erreicht. Führe einen Fernkampfwaffenangriff gegen das Ziel aus. Bei einem Treffer erleidet das Ziel Schaden durch den Wurfspeer und 4W6 Blitzschaden.","Die Eigenschaft des Wurfspeers kann erst im nächsten Morgengrauen wiederverwendet werden.","In der Zwischenzeit kann der Wurfspeer jedoch weiter als magische Waffe verwendet werden."],"attune":"Wurfspeer"},
  {"id":"zauberabwehrschild","name":"Zauberabwehrschild","type":"Rüstung (Schild)","rarity":"sehr selten","desc":["Wenn du diesen Schild hältst, bist du bei Rettungswürfen gegen Zauber und andere magische Effekte im Vorteil und Zauberangriffe gegen dich sind im Nachteil."],"attune":"Schild"},
  {"id":"zauberfluegel","name":"Zauberflügel","type":"Wundersamer Gegenstand","rarity":"selten","desc":["Wenn du diesen Umhang trägst, kannst du als Aktion sein Befehlswort aussprechen. Dadurch wird der Umhang eine Stunde lang - oder bis du als Aktion das Befehlswort erneut aussprichst - zu einem Paar Fledermaus- oder Vogelflügeln auf deinem Rücken. Die Flügel geben dir eine Flugbewegungsrate von 18 Metern. Wenn sie verschwinden, kannst du die Flügel erst nach 1W12 Stunden erneut verwenden."],"attune":"erfordert Einstimmung"},
  {"id":"zauberschriftrolle","name":"Zauberschriftrolle","type":"Schriftrolle","rarity":"variiert","desc":["Eine Zauberschriftrolle trägt die Worte eines einzigen Zaubers in mystischen Zeichen. Wenn sich der Zauber in der Liste deiner Klasse befindet, kannst du die Schriftrolle lesen und den Zauber wirken, ohne Materialkomponenten zu benötigen. Anderenfalls ist die Schriftrolle für dich unleserlich. Wird der Zauber gewirkt, indem die Schriftrolle verlesen wird, so ist der normale Zeitaufwand zum Wirken erforderlich. Ist der Zauber gewirkt, verblassen die Zeichen auf der Schriftrolle, und diese zerfällt zu Staub. Wird das Wirken des Zaubers unterbrochen, bleibt die Schriftrolle erhalten.","Wenn sich der Zauber in der Zauberliste deiner Klasse befindet, jedoch einen höheren Grad aufweist, als du normalerweise wirken kannst, musst du einen Attributswurf mit deinem Attribut zum Zauberwirken bestehen, um den Zauber erfolgreich zu wirken. Der SG ist gleich 10 + der Grad des Zaubers. Anderenfalls verschwindet er ohne weiteren Effekt von der Schriftrolle.","Der Grad des Zaubers in der Schriftrolle bestimmt den Rettungswurf-SG und Angriffsbonus des Zaubers sowie die Seltenheit der Schriftrolle entsprechend der Tabelle 'Zauberschriftrolle'.","Ein Magierzauber in einer Zauberschriftrolle kann wie Zauber aus Zauberbüchern kopiert werden. Wenn ein Zauber aus einer Zauberschriftrolle kopiert wird, muss der kopierende Charakter einen Intelligenzwurf (Arkane Kunde) bestehen, wobei der SG gleich 10 + der Zaubergrad ist. Bei einem Erfolg wird der Zauber erfolgreich kopiert. Unabhängig davon, ob der Wurf erfolgreich ist oder scheitert, wird die Zauberschriftrolle zerstört."]},
  {"id":"zauberstab-der-angst","name":"Zauberstab der Angst","type":"Zauberstab","rarity":"selten","desc":["Dieser Zauberstab hat sieben Ladungen für die folgenden Eigenschaften. Er erhält täglich im Morgengrauen 1W6+1 verbrauchte Ladungen zurück. Wenn du die letzte Ladung des Zauberstabs verbrauchst, würfle mit einem W20. Bei einer 1 zerfallt der Zauberstab zu Asche und ist damit zerstört.","Befehl: Wenn du den Zauberstab hältst, kannst du als Aktion eine Ladung verbrauchen und einer anderen Kreatur befehlen, zu fliehen oder auf die Knie zu gehen, als hättest du den Zauber Befehl (Rettungswurf-SG 15) gewirkt.","Angstkegel: Wenn du den Zauberstab hältst, kannst du als Aktion zwei Ladungen verbrauchen. Daraufhin verströmt die Spitze des Zauberstabs in einem Kegel von 18 Metern bernsteinfarbenes Licht Jede Kreatur innerhalb des Kegels muss einen SG-15-Weisheitsrettungswurf bestehen, oder sie ist eine Minute lang von dir verängstigt. Eine auf diese Weise verängstigte Kreatur muss ihre Züge dafür verwenden, sich so weit wie möglich von dir zu entfernen, und darf dir nicht absichtlich näher als neun Meter kommen. Außerdem kann sie nicht reagieren. Als Aktion kann sie nur die Spurt-Aktion ausführen oder versuchen, sich von einem Effekt zu befreien, der sie in ihrer Bewegung einschränkt. Kann die Kreatur sich nirgendwohin bewegen, kann sie trotzdem eine Ausweichaktion verwenden.","Am Ende jedes ihrer Züge kann eine Kreatur den Rettungswurf wiederholen und den Effekt bei einem Erfolg beenden."],"attune":"erfordert Einstimmung"},
  {"id":"zauberstab-der-bindung","name":"Zauberstab der Bindung","type":"Zauberstab","rarity":"selten","desc":["Dieser Zauberstab hat sieben Ladungen für die folgenden Eigenschaften. Er erhält täglich im Morgengrauen 1W6+1 verbrauchte Ladungen zurück. Wenn du die letzte Ladung des Zauberstabs verbrauchst, würfle mit einem W20. Bei einer 1 zerfällt der Zauberstab zu Asche und ist damit zerstört","Fluchthilfe: Während du den Zauberstab hältst, kannst du als Reaktion eine Ladung verbrauchen, um entweder bei einem Rettungswurf, den du ausführst, um nicht gelähmt oder festgesetzt zu werden, im Vorteil zu sein, oder um bei einem beliebigen Wurf, den du ausführst, um einem Haltegriff zu entkommen, im Vorteil zu sein.","Zauber: Wenn du diesen Zauberstab hältst, kannst du als Aktion einige seiner Ladungen verbrauchen, um einen der folgenden Zauber mit ihm zu wirken (Rettungswurf-SG 17): Monster festhalten (fünf Ladungen) oder Person festhalten (zwei Ladungen)."],"attune":"erfordert Einstimmung durch einen Zauberwirker"},
  {"id":"zauberstab-der-blitzschlaege","name":"Zauberstab der Blitzschläge","type":"Zauberstab","rarity":"selten","desc":["Dieser Zauberstab hat sieben Ladungen. Wenn du ihn hältst, kannst du als Aktion eine oder mehrere seiner Ladungen verbrauchen, um den Zauber Blitz (Rettungswurf-SG 15) mit ihm zu wirken. Für eine Ladung wirkst du den Zauber des 3. Grades. Du kannst den Zauberplatz-Grad für jede weitere Ladung, die du verbrauchst, um einen Grad erhöhen.","Der Zauberstab erhält täglich im Morgengrauen 1W6+1 verbrauchte Ladungen zurück. Wenn du die letzte Ladung des Zauberstabs verbrauchst, würfle mit einem W20. Bei einer 1 zerfällt der Zauberstab zu Asche und ist damit zerstört."],"attune":"erfordert Einstimmung durch einen Zauberwirker"},
  {"id":"zauberstab-der-feindeslokalisierung","name":"Zauberstab der Feindeslokalisierung","type":"Zauberstab","rarity":"selten","desc":["Dieser Zauberstab hat sieben Ladungen. Wenn du ihn hältst, kannst du als Aktion eine Ladung verbrauchen, um sein Befehlswort auszusprechen. In der nächsten Minute weißt du, in welcher Richtung sich die nächste feindliche Kreatur im Abstand von bis zu 18 Metern befindet, aber nicht ihren Abstand von dir. Der Zauberstab kann die Anwesenheit von ätherischen, unsichtbaren, verkleideten oder versteckten feindlichen Kreaturen genauso erkennen wie die von offen sichtbaren. Der Effekt endet, wenn du den Zauberstab nicht mehr hältst.","Der Zauberstab erhält täglich im Morgengrauen 1W6+1 verbrauchte Ladungen zurück. Wenn du die letzte Ladung des Zauberstabs verbrauchst, würfle mit einem W20. Bei einer 1 zerfällt der Zauberstab zu Asche und ist damit zerstört."],"attune":"erfordert Einstimmung"},
  {"id":"zauberstab-der-feuerbaelle","name":"Zauberstab der Feuerbälle","type":"Zauberstab","rarity":"selten","desc":["Dieser Zauberstab hat sieben Ladungen. Wenn du ihn hältst, kannst du als Aktion eine oder mehrere seiner Ladungen verbrauchen, um den Zauber Feuerball (Rettungswurf-SG 15) mit ihm zu wirken. Für eine Ladung wirkst du den Zauber des 3. Grades. Du kannst den Zauberplatz-Grad für jede weitere Ladung, die du verbrauchst, um einen Grad erhöhen.","Der Zauberstab erhält täglich im Morgengrauen 1W6+1 verbrauchte Ladungen zurück. Wenn du die letzte Ladung des Zauberstabs verbrauchst, würfle mit einem W20. Bei einer 1 zerfällt der Zauberstab zu Asche und ist damit zerstört."],"attune":"erfordert Einstimmung durch einen Zauberwirker"},
  {"id":"zauberstab-der-geheimnisse","name":"Zauberstab der Geheimnisse","type":"Zauberstab","rarity":"ungewöhnlich","desc":["Dieser Zauberstab hat drei Ladungen. Während du ihn hältst, kannst du eine Aktion verwenden, um eine seiner Ladungen zu verbrauchen. Falls sich eine Geheimtür oder Falle im Abstand von bis zu neun Metern von dir befindet, pulsiert der Zauberstab und zeigt auf die, die dir am nächsten ist Der Zauberstab erhält täglich im Morgengrauen 1W3 verbrauchte Ladungen zurück."]},
  {"id":"zauberstab-der-magieerkennung","name":"Zauberstab der Magieerkennung","type":"Zauberstab","rarity":"ungewöhnlich","desc":["Dieser Zauberstab hat drei Ladungen. Wenn du ihn hältst, kannst du als Aktion eine Ladung verbrauchen, um den Zauber Magie entdecken mit ihm zu wirken. Der Zauberstab erhält täglich im Morgengrauen 1W3 verbrauchte Ladungen zurück."]},
  {"id":"zauberstab-der-magischen-geschosse","name":"Zauberstab der magischen Geschosse","type":"Zauberstab","rarity":"ungewöhnlich","desc":["Dieser Zauberstab hat sieben Ladungen. Wenn du ihn hältst, kannst du als Aktion eine oder mehrere seiner Ladungen verbrauchen, um den Zauber Magisches Geschoss mit ihm zu wirken. Für eine Ladung wirkst du den Zauber des 1. Grades. Du kannst den Zauberplatz-Grad für jede weitere Ladung, die du verbrauchst, um einen Grad erhöhen.","Der Zauberstab erhält täglich im Morgengrauen 1W6+1 verbrauchte Ladungen zurück. Wenn du die letzte Ladung des Zauberstabs verbrauchst, würfle mit einem W20. Bei einer 1 zerfällt der Zauberstab zu Asche und ist damit zerstört."]},
  {"id":"zauberstab-der-paralyse","name":"Zauberstab der Paralyse","type":"Zauberstab","rarity":"selten","desc":["Dieser Zauberstab hat sieben Ladungen. Wenn du ihn hältst, kannst du eine Aktion verwenden, um eine Ladung zu verbrauchen und einen blauen Strahl von seiner Spitze auf eine Kreatur im Abstand von bis zu 18 Metern von dir abzufeuern, die du sehen kannst. Das Ziel muss einen SG-15-Konstitutionsrettungswurf bestehen, oder es ist eine Minute lang gelähmt. Am Ende jedes seiner Züge kann das Ziel den Rettungswurf wiederholen und den Effekt bei einem Erfolg beenden.","Der Zauberstab erhält täglich im Morgengrauen 1W6+1 verbrauchte Ladungen zurück. Wenn du die letzte Ladung des Zauberstabs verbrauchst, würfle mit einem W20. Bei einer 1 zerfällt der Zauberstab zu Asche und ist damit zerstört."],"attune":"erfordert Einstimmung durch einen Zauberwirker"},
  {"id":"zauberstab-der-verwandlung","name":"Zauberstab der Verwandlung","type":"Zauberstab","rarity":"sehr selten","desc":["Dieser Zauberstab hat sieben Ladungen. Wenn du ihn hältst, kannst du als Aktion eine seiner Ladungen verbrauchen, um den Zauber Verwandlung (Rettungswurf-SG 15) mit ihm zu wirken.","Der Zauberstab erhält täglich im Morgengrauen 1W6+1 verbrauchte Ladungen zurück. Wenn du die letzte Ladung des Zauberstabs verbrauchst, würfle mit einem W20. Bei einer 1 zerfällt der Zauberstab zu Asche und ist damit zerstört."],"attune":"erfordert Einstimmung durch einen Zauberwirker"},
  {"id":"zauberstab-des-kriegsmagiers-1-2-oder-3","name":"Zauberstab des Kriegsmagiers, +1, +2 oder +3","type":"Zauberstab","rarity":"ungewöhnlich (+1), selten (+2) oder sehr selten (+3)","desc":["Während du diesen Zauberstab hältst, erhältst du abhängig von der Seltenheit des Zauberstabs einen Bonus auf Zauberangriffswürfe. Außerdem ignorierst du Teildeckung, wenn du einen Zauberangriff ausführst."],"attune":"+1"},
  {"id":"zauberstab-des-netzes","name":"Zauberstab des Netzes","type":"Zauberstab","rarity":"ungewöhnlich","desc":["Dieser Zauberstab hat sieben Ladungen. Wenn du ihn hältst, kannst du als Aktion eine seiner Ladungen verbrauchen, um den Zauber Netz (Rettungswurf-SG 15) mit ihm zu wirken.","Der Zauberstab erhält täglich im Morgengrauen 1W6+1 verbrauchte Ladungen zurück. Wenn du die letzte Ladung des Zauberstabs verbrauchst, würfle mit einem W20. Bei einer 1 zerfällt der Zauberstab zu Asche und ist damit zerstört."],"attune":"erfordert Einstimmung durch einen Zauberwirker"},
  {"id":"zauberstab-des-wunders","name":"Zauberstab des Wunders","type":"Zauberstab","rarity":"selten","desc":["Dieser Zauberstab hat sieben Ladungen. Wenn du ihn hältst, kannst du als Aktion eine Ladung verbrauchen und ein Ziel im Abstand von bis zu 36 Metern von dir bestimmen. Das Ziel kann eine Kreatur, ein Gegenstand oder ein Punkt im Raum sein. Würfle mit einem W100 und ziehe die folgende Tabelle zurate, um herauszufinden, was passiert.","Wenn der Effekt dir erlaubt, einen Zauber mit dem Zauberstab zu wirken, ist der Rettungswurf-SG des Zaubers 15. Wenn der Zauber normalerweise eine in Metern ausgedrückte Reichweite hat, die nicht 36 Meter beträgt, wird seine Reichweite zu 36 Metern.","Wenn ein Effekt einen Bereich betrifft, muss das Ziel sich im Mittelpunkt des Zaubers befinden und vom Zauber betroffen sein. Wenn ein Effekt mehrere mögliche Ziele hat, bestimmt der SL zufällig, welche betroffen sind.","Der Zauberstab erhält täglich im Morgengrauen 1W6+1 verbrauchte Ladungen zurück. Wenn du die letzte Ladung des Zauberstabs verbrauchst, würfle mit einem W20. Bei einer 1 zerfällt der Zauberstab zu Staub und ist damit zerstört."],"attune":"erfordert Einstimmung durch einen Zauberwirker"},
  {"id":"zepter-der-absorption","name":"Zepter der Absorption","type":"Zepter","rarity":"sehr selten","desc":["Wenn du dieses Zepter hältst, kannst du als Reaktion einen Zauber absorbieren, der nur dich als Ziel und keinen Wirkungsbereich hat. Der Effekt des absorbierten Zaubers wird aufgehoben und die Energie des Zaubers - nicht aber der Zauber selbst -wird im Zepter gespeichert. Die Energie entspricht dem Grad des Zaubers, als er gewirkt wurde.","Das Zepter kann insgesamt bis zu 50 Zauberenergiegrade in sich aufnehmen. Nachdem das Zepter 50 Zauberenergiegrade aufgenommen hat, kann es keine Energie mehr aufnehmen. Wenn du das Ziel eines Zaubers bist, den das Zepter nicht speichern kann, hat das Zepter keinen Effekt auf diesen Zauber.","Wenn du dich auf das Zepter eingestimmt hast, weißt du, wie viele Zauberenergiegrade das Zepter seit seiner Erschaffung absorbiert hat und wie viele aktuell in ihm gespeichert sind.","Wenn du ein Zauberwirker bist und das Zepter hältst, kannst du die im Zepter gespeicherte Energie in Zauberplätze umwandeln, um Zauber zu wirken, die du vorbereitet hast oder kennst. Du kannst nur Zauberplätze bis zur Gradzahl deiner eigenen Zauberplätze oder niedriger erzeugen, maximal jedoch Zauberplätze des 5. Grades. Du verwendest die gespeicherten Grade anstelle deiner Zauberplätze. Ansonsten wirkst du die Zauber wie gewohnt.","Du kannst zum Beispiel drei im Zepter gespeicherte Zauberenergiegrade als einen Zauberplatz des 3. Grades verwenden.","Wenn es gefunden wird, sind in einem Zepter bereits 1W10 Zauberenergiegrade gespeichert. Ein Zepter, das keine weitere Zauberenergie aufnehmen kann und keine Energie mehr in sich gespeichert hat, wird nichtmagisch."],"attune":"erfordert Einstimmung"},
  {"id":"zepter-der-herrschaft","name":"Zepter der Herrschaft","type":"Zepter","rarity":"selten","desc":["Du kannst als Aktion das Zepter präsentieren und von jeder Kreatur deiner Wahl, die du im Abstand von bis zu 36 Metern von dir sehen kannst, Gehorsam verlangen. Jedes Ziel muss einen SG-15-Weisheitsrettungswurf bestehen, oder es ist für acht Stunden von dir bezaubert. Auf diese Art bezauberte Kreaturen betrachten dich als vertrauenswürdigen Anführer. Wenn ihnen von dir oder deinen Verbündeten Schaden zugefügt wird oder sie einen Befehl erhalten, der ihrer Natur widerspricht, endet die Bezauberung für die entsprechenden Ziele. Das Zepter kann erst im nächsten Morgengrauen wiederverwendet werden."],"attune":"erfordert Einstimmung"},
  {"id":"zepter-der-herrschaftlichen-macht","name":"Zepter der herrschaftlichen Macht","type":"Zepter","rarity":"legendär","desc":["Dieses Zepter hat einen angeflanschten Kopf und ist als magischer Streitkolben verwendbar, der einem Bonus von +3 auf Angriffs- und Schadenswürfe verleiht, die du mit ihm ausführst. Ins Heft des Zepters sind sechs verschiede Knöpfe eingelassen, die dem Zepter verschiedene Eigenschaften verleihen. Es hat außerdem drei weitere Eigenschaften, die unten aufgeführt sind.","Sechs Knöpfe: Du kannst als Bonusaktion einen der sechs Knöpfe des Zepters drücken. Der Effekt eines Knopfs hält an, bis du einen anderen Knopf drückst oder bis du denselben Knopf nochmals drückst, wodurch das Zepter wieder seine normale Gestalt annimmt.","Wenn du Knopf 1 drückst, schießt eine feurige Klinge aus dem unteren Ende des Zepters hervor und das Zepter wird eine Flammenzunge.","Wenn du Knopf 2 drückst, wird der Kopf des Zepters flacher und zwei halbmondförmige Klingen erscheinen. Das Zepter verwandelt sich in eine magische Streitaxt mit einem Bonus von +3 auf Angriffs- und Schadenswürfe, die du mit ihr ausführst.","Wenn du Knopf 3 drückst, wird der Kopf des Zepters eingeklappt, eine Speerspitze erscheint an seinem oberen Ende und der Griff verlängert sich zu einem 1,8 Meter langen Heft. Das Zepter verwandelt sich in einen magischen Speer mit einem Bonus von +3 auf Angriffs- und Schadenswürfe, die du mit ihm ausführst.","Wenn du Knopf 4 drückst, verwandelt sich das Zepter in eine Kletterstange mit einer von dir bestimmten Länge von bis zu 15 Metern. Auf Oberflächen, die so hart wie Granit sind, wird die Stange mithilfe eines Stachels am unteren Ende und dreier Haken am oberen Ende verankert. Alle 30 Zentimeter erscheinen 7,5 Zentimeter breite waagerechte Sprossen, sodass eine Leiter entsteht. Die Stange kann bis zu 2.000 Kilogramm Last tragen. Wird sie mit mehr Gewicht belastet oder kann sie sich nicht verankern, verwandelt sich die Stange wieder zum ursprünglichen Zepter zurück.","Wenn du Knopf 5 drückst, verwandelt sich das Zepter in einen tragbaren Rammbock. Dieser gewährt seinem Benutzer einen Bonus von +10 auf Stärke würfe, die ausgeführt werden, um Türen, Barrikaden und andere Barrieren zu durchbrechen.","Wenn du Knopf 6 drückst, verwandelt sich das Zepter in seine normale Gestalt zurück oder bleibt ein Zepter und zeigt den magnetischen Norden an. (Wenn diese Funktion des Zepters an einem Ort verwendet wird, der keinen magnetischen Norden hat, passiert nichts.) Das Zepter vermittelt dir außerdem ein Gefühl für deine ungefähre Tiefe unter oder Höhe über der Erde.","Lähmen: Wenn du eine Kreatur mit einem Nahkampfangriff mit diesem Zepter triffst, kannst du das Ziel zu einem SG-17-Stärkerettungswurf zwingen. Anderenfalls ist das Ziel eine Minute lang gelähmt. Das Ziel kann den Rettungswurf am Ende jedes seiner Züge wiederholen und den Effekt bei einem Erfolg beenden. Diese Eigenschaft kann erst im nächsten Morgengrauen wiederverwendet werden.","Leben entziehen: Wenn du eine Kreatur mit einem Nahkampfangriff mit diesem Zepter triffst, kannst du das Ziel zu einem SG-17-Konstitutions-rettungswurf zwingen. Anderenfalls erleidet das Ziel zusätzlich 4W6 nekrotischen Schaden und du erhältst Trefferpunkte in Höhe der Hälfte des nekrotischen Schadens zurück. Diese Eigenschaft kann erst im nächsten Morgengrauen wiederverwendet werden.","Terrorisieren: Wenn du das Zepter hältst, kannst du eine Aktion verwenden, um jede Kreatur im Abstand von bis zu neun Metern von dir zu zwingen, einen SG-17-Weisheitsrettungswurf auszuführen. Anderenfalls ist das jeweilige Ziel eine Minute lang von dir verängstigt. Ein verängstigtes Ziel kann den Rettungswurf am Ende jedes seiner Züge wiederholen und den Effekt bei einem Erfolg beenden. Diese Eigenschaft kann erst im nächsten Morgengrauen wiederverwendet werden."],"attune":"erfordert Einstimmung"},
  {"id":"zepter-der-sicherheit","name":"Zepter der Sicherheit","type":"Zepter","rarity":"sehr selten","desc":["Wenn du dieses Zepter hältst, kannst du es als Aktion aktivieren. Das Zepter transportiert dann dich und bis zu 199 bereitwillige Kreaturen, die du sehen kannst, sofort in ein Paradies in einem extraplanaren Bereich. Du bestimmst, welche Gestalt das Paradies annimmt Vielleicht ist es ein friedlicher Garten, eine wunderschöne Lichtung, eine heitere Taverne, ein gigantischer Palast, eine tropische Insel, ein fantastischer Jahrmarkt - oder was auch immer du dir vorstellen kannst. Das Paradies enthält unabhängig von seinem Aussehen genug Wasser und Nahrung, um seine Besucher zu versorgen. Ansonsten kann alles, womit in dem extraplanaren Bereich interagiert werden kann, nur dort existieren. Wenn zum Beispiel jemand eine Blume aus einem Garten im Paradies pflückt, verschwindet sie, wenn sie aus dem extraplanaren Bereich gebracht wird.","Für jede im Paradies verbrachte Stunde erhält ein Besucher so viele Trefferpunkte zurück, wie er durch einen Trefferwürfel zurückerhalten hätte. Weiterhin altern Kreaturen nicht, solange sie sich im Paradies befinden, auch wenn die Zeit normal vergeht. Besucher können für bis zu 200 Tage geteilt durch die Anzahl der Kreaturen im Paradies bleiben (abgerundet).","Wenn die Zeit abläuft oder du eine Aktion verwendest, um das Paradies zu verlassen, erscheinen alle Besucher an derselben Stelle, die sie besetzt hatten, als du das Zepter aktiviert hast, oder an der nächsten freien Stelle. Das Zepter kannst erst nach zehn Tagen wiederverwendet werden."]},
  {"id":"zepter-der-wachsamkeit","name":"Zepter der Wachsamkeit","type":"Zepter","rarity":"sehr selten","desc":["Dieses Zepter hat einen angeflanschten Kopf und die folgenden Eigenschaften.","Wachsamkeit: Wenn du das Zepter hältst, bist du bei Weisheitswürfen (Wahrnehmung) und Initiativwürfen im Vorteil.","Zauber: Wenn du das Zepter hältst, kannst du als Aktion einen der folgenden Zauber mit ihm wirken: Gift und Krankheit entdecken, Gutes und Böses entdecken, Magie entdecken oder Unsichtbares sehen.","Schützende Aura: Du kannst das Heft des Zepters als Aktion in den Boden rammen, woraufhin der Kopf des Zepters in einem Radius von 18 Metern helles Licht und in einem Radius von weiteren 18 Metern dämmriges Licht spendet Wenn du und dir freundlich gesinnte Kreaturen vom Licht des Zepters erhellt werdet, erhaltet ihr einen Bonus von +1 auf eure RK und auf Rettungswürfe, und ihr könnt die Position von unsichtbaren feindlich gesinnten Kreaturen spüren, die sich ebenfalls in diesem hellen Licht befinden.","Der Kopf des Zepters hört auf zu leuchten und der Effekt endet entweder nach zehn Minuten oder wenn eine Kreatur eine Aktion verwendet, um das Zepter aus dem Boden zu ziehen. Diese Eigenschaft kann erst im nächsten Morgengrauen wiederverwendet werden."],"attune":"erfordert Einstimmung"},
  {"id":"zwergenguertel","name":"Zwergengürtel","type":"Wundersamer Gegenstand","rarity":"selten","desc":["Wenn du diesen Gürtel trägst, erhältst du die folgenden Vorteile:","Wenn du auf den Gürtel eingestimmt bist, hast du außerdem jeden Tag im Morgengrauen eine Chance von 50 Prozent, dass dir ein Vollbart wächst, sofern du dazu in der Lage bist, oder dass dein Bart wesentlich dichter wird, falls du schon einen hast.","Falls du kein Zwerg bist, erhältst du die folgenden zusätzlichen Vorteile, wenn du diesen Gürtel trägst:"],"attune":"erfordert Einstimmung"},
  {"id":"zwergische-ritterruestung","name":"Zwergische Ritterrüstung","type":"Rüstung (Ritterrüstung)","rarity":"sehr selten","desc":["Wenn du diese Rüstung trägst, erhältst du einen Bonus von +2 auf deine RK. Wenn ein Effekt dich gegen deinen Willen über den Boden bewegt, kannst du außerdem die Entfernung dieser Bewegung als Reaktion um bis zu drei Meter reduzieren."],"attune":"Ritterrüstung"},
  {"id":"zwergischer-wurfhammer","name":"Zwergischer Wurfhammer","type":"Waffe (Kriegshammer)","rarity":"sehr selten","desc":["Du erhältst einen Bonus von +3 auf Angriffs- und Schadenswürfe, die du mit dieser magischen Waffe ausführst Sie ist eine Wurfwaffe mit einer Grundreichweite von sechs Metern und einer Maximalreichweite von 18 Metern. Wenn ein Fernkampfangriff mit dieser Waffe trifft, verursacht sie zusätzlich 1W8 Schaden oder, wenn das Ziel ein Riese ist, 2W8 Schaden. Unmittelbar nach dem Angriff fliegt die Waffe zurück in deine Hand."],"attune":"Kriegshammer"},
];
